package com.loadoutstudio;

import com.google.gson.*;

/** Versioned, bounded snapshot in this plugin's own profile-scoped configuration. */
final class DraftRecovery
{
	static String encode(JsonObject portable, String editingId, String section, boolean favorite, BankLayouts.Mode mode,
			boolean bottom, boolean ignoreAmmo, Gson gson)
	{
		JsonObject check = portable.deepCopy();
		SetupCodec.setup(check).addProperty("name", "Recovery validation");
		SetupCodec.validate(check, false);
		JsonObject value = new JsonObject();
		value.addProperty("version", 1);
		value.addProperty("savedAt", System.currentTimeMillis());
		value.add("portable", portable.deepCopy());
		value.addProperty("editingId", editingId);
		value.addProperty("section", section);
		value.addProperty("favorite", favorite);
		value.addProperty("layout", mode.name());
		value.addProperty("bottom", bottom);
		value.addProperty("ignoreAmmo", ignoreAmmo);
		String text = gson.toJson(value);
		if (text.length() > 200000)
			throw new IllegalArgumentException("Draft recovery exceeds its size limit. Save or export the setup.");
		return text;
	}

	static JsonObject decode(String text, Gson gson)
	{
		if (text == null || text.isEmpty())
			return null;
		if (text.length() > 200000)
			throw new IllegalArgumentException("Draft recovery is too large.");
		JsonObject value = new SetupCodec(gson).parse(text).getAsJsonObject();
		if (value.get("version").getAsInt() != 1)
			throw new IllegalArgumentException("Unsupported draft recovery.");
		for (String flag : new String[]{"favorite", "bottom", "ignoreAmmo"})
			SetupCodec.validateBoolean(value, flag, true);
		JsonObject copy = value.getAsJsonObject("portable").deepCopy();
		JsonObject setup = SetupCodec.setup(copy);
		// A transient empty/long name may occur while typing. Validate the remainder without changing the snapshot.
		setup.addProperty("name", "Recovery validation");
		SetupCodec.validate(copy, false);
		String name = SetupCodec.name(value.getAsJsonObject("portable"));
		if (name.length() > 1000)
			throw new IllegalArgumentException("Invalid recovery name.");
		BankLayouts.Mode.valueOf(value.get("layout").getAsString());
		return value;
	}

	static String optional(JsonObject object, String key)
	{
		return !object.has(key) || object.get(key).isJsonNull() ? null : object.get(key).getAsString();
	}
}

/* SPDX-License-Identifier: BSD-2-Clause */
package com.loadoutstudio;
import static net.runelite.api.gameval.ItemID.*;
/** Usable cosmetic/combat equivalence; exact stored/exported IDs are never rewritten. */
final class EquipmentVariants
{
	static boolean runePouch(int id)
	{
		return net.runelite.client.game.ItemVariationMapping.map(id) == BH_RUNE_POUCH;
	}

	static boolean divinePouch(int id)
	{
		return net.runelite.client.game.ItemVariationMapping.map(id) == DIVINE_RUNE_POUCH;
	}

	/** Separate imbued combat functionality from cosmetic colours and imbue sources. */
	static int slayerBase(int id)
	{
		switch (id)
		{
			case SLAYER_HELM_I:
			case SLAYER_HELM_I_BLACK:
			case SLAYER_HELM_I_GREEN:
			case SLAYER_HELM_I_RED:
			case SLAYER_HELM_I_PURPLE:
			case SLAYER_HELM_I_TURQUOISE:
			case SLAYER_HELM_I_HYDRA:
			case SLAYER_HELM_I_TWISTED:
			case SW_SLAYER_HELM_I:
			case SW_SLAYER_HELM_I_BLACK:
			case SW_SLAYER_HELM_I_GREEN:
			case SW_SLAYER_HELM_I_RED:
			case SW_SLAYER_HELM_I_PURPLE:
			case SW_SLAYER_HELM_I_TURQUOISE:
			case SW_SLAYER_HELM_I_HYDRA:
			case SW_SLAYER_HELM_I_TWISTED:
			case SLAYER_HELM_I_JAD:
			case SW_SLAYER_HELM_I_JAD:
			case SLAYER_HELM_I_VERZIK:
			case SW_SLAYER_HELM_I_VERZIK:
			case SLAYER_HELM_I_ZUK:
			case SW_SLAYER_HELM_I_ZUK:
			case PVPA_SLAYER_HELM_I:
			case PVPA_SLAYER_HELM_I_BLACK:
			case PVPA_SLAYER_HELM_I_GREEN:
			case PVPA_SLAYER_HELM_I_RED:
			case PVPA_SLAYER_HELM_I_PURPLE:
			case PVPA_SLAYER_HELM_I_TURQUOISE:
			case PVPA_SLAYER_HELM_I_HYDRA:
			case PVPA_SLAYER_HELM_I_TWISTED:
			case PVPA_SLAYER_HELM_I_JAD:
			case PVPA_SLAYER_HELM_I_VERZIK:
			case PVPA_SLAYER_HELM_I_ZUK:
			case SLAYER_HELM_I_ARAXYTE:
			case SW_SLAYER_HELM_I_ARAXYTE:
			case PVPA_SLAYER_HELM_I_ARAXYTE:
			case SLAYER_HELM_I_HOODED:
			case SW_SLAYER_HELM_I_HOODED:
			case PVPA_SLAYER_HELM_I_HOODED:
			case LEAGUE_6_SLAYER_HELM1_I:
			case SW_LEAGUE_6_SLAYER_HELM1_I:
			case PVPA_LEAGUE_6_SLAYER_HELM1_I:
			case LEAGUE_6_SLAYER_HELM2_I:
			case SW_LEAGUE_6_SLAYER_HELM2_I:
			case PVPA_LEAGUE_6_SLAYER_HELM2_I:
				return SLAYER_HELM_I;
			default:
				return net.runelite.client.game.ItemVariationMapping.map(id) == SLAYER_HELM ? SLAYER_HELM : id;
		}
	}

	static int combatBase(int id)
	{
		int slayer = slayerBase(id);
		if (slayer != id)
			return slayer;
		switch (id)
		{
			case SKILLCAPE_MAX_INFERNALCAPE:
			case SKILLCAPE_MAX_INFERNALCAPE_TROUVER:
			case INFERNAL_CAPE_TROUVER:
				return INFERNAL_CAPE;
			case SKILLCAPE_MAX_FIRECAPE:
			case SKILLCAPE_MAX_FIRECAPE_TROUVER:
			case TZHAAR_CAPE_FIRE_TROUVER:
				return TZHAAR_CAPE_FIRE;
			case SKILLCAPE_MAX_ANMA:
				return ANMA_50_REWARD;
			case SKILLCAPE_MAX_ARDY:
				return ARDY_CAPE_ELITE;
			case SKILLCAPE_MAX_MYTHICAL:
				return MYTHICAL_CAPE;
			case SKILLCAPE_MAX_ASSEMBLER:
			case SKILLCAPE_MAX_ASSEMBLER_TROUVER:
			case SKILLCAPE_MAX_ASSEMBLER_MASORI:
			case SKILLCAPE_MAX_ASSEMBLER_MASORI_TROUVER:
			case AVAS_ASSEMBLER_MASORI:
