				return TOXIC_BLOWPIPE_LOADED;
			case TOXIC_BLOWPIPE_ORNAMENT:
				return TOXIC_BLOWPIPE;
			case TORVA_HELM_SANGUINE:
				return TORVA_HELM;
			case TORVA_CHEST_SANGUINE:
				return TORVA_CHEST;
			case TORVA_LEGS_SANGUINE:
				return TORVA_LEGS;
			case RADIANT_OATHPLATE_HELM:
				return OATHPLATE_HELM;
			case RADIANT_OATHPLATE_CHEST:
				return OATHPLATE_CHEST;
			case RADIANT_OATHPLATE_LEGS:
				return OATHPLATE_LEGS;
			default:
				return id;
		}
	}

	/** Charged/blessed may replace an uncharged quiver, never the reverse. */
	static boolean alternative(int owned, int expected)
	{
		if (owned < 1 || expected < 1)
			return false;
		if (divinePouch(owned) && runePouch(expected))
			return true;
		int actual = combatBase(owned), wanted = combatBase(expected);
		if (actual == wanted)
			return true;
		if (actual == SLAYER_HELM || actual == SLAYER_HELM_I || wanted == SLAYER_HELM || wanted == SLAYER_HELM_I)
			return false;
		if (actual == ELIDINIS_WARD || wanted == ELIDINIS_WARD)
			return false;
		if (wanted == DIZANAS_QUIVER_UNCHARGED && actual == DIZANAS_QUIVER_INFINITE)
			return true;
		if (wanted == DIZANAS_QUIVER_INFINITE && actual == DIZANAS_QUIVER_UNCHARGED)
			return false;
		return net.runelite.client.game.ItemVariationMapping
				.map(actual) == net.runelite.client.game.ItemVariationMapping.map(wanted);
	}

	/** Locked cape requirements remain exact unless the player chooses a replacement. */
	static int base(int id)
	{
		if (runePouch(id))
			return BH_RUNE_POUCH;
		if (divinePouch(id))
			return DIVINE_RUNE_POUCH;
		switch (id)
		{
			case TORVA_HELM_SANGUINE:
				return TORVA_HELM;
			case TORVA_CHEST_SANGUINE:
				return TORVA_CHEST;
			case TORVA_LEGS_SANGUINE:
				return TORVA_LEGS;
			case RADIANT_OATHPLATE_HELM:
				return OATHPLATE_HELM;
			case RADIANT_OATHPLATE_CHEST:
				return OATHPLATE_CHEST;
			case RADIANT_OATHPLATE_LEGS:
				return OATHPLATE_LEGS;
			case DEADMAN_VOIDWAKER:
				return VOIDWAKER;
			default:
				return id;
		}
	}

	static boolean same(int a, int b)
	{
		return a > 0 && b > 0 && base(a) == base(b);
	}
}

