			ItemID.DRAGON_BOLTS_UNENCHANTED_DRAGONSTONE, ItemID.DRAGON_BOLTS_UNENCHANTED_ONYX,
			ItemID.DRAGON_BOLTS_ENCHANTED_OPAL, ItemID.DRAGON_BOLTS_ENCHANTED_JADE, ItemID.DRAGON_BOLTS_ENCHANTED_PEARL,
			ItemID.DRAGON_BOLTS_ENCHANTED_TOPAZ, ItemID.DRAGON_BOLTS_ENCHANTED_SAPPHIRE,
			ItemID.DRAGON_BOLTS_ENCHANTED_EMERALD, ItemID.DRAGON_BOLTS_ENCHANTED_RUBY,
			ItemID.DRAGON_BOLTS_ENCHANTED_DIAMOND, ItemID.DRAGON_BOLTS_ENCHANTED_DRAGONSTONE,
			ItemID.DRAGON_BOLTS_ENCHANTED_ONYX, ItemID.BARROWS_KARIL_AMMO};
	static boolean isBoltVarbit(int bit)
	{
		for (int id : BOLT_TYPES)
			if (id == bit)
				return true;
		for (int id : BOLT_AMOUNTS)
			if (id == bit)
				return true;
		return false;
	}

	static int[] trackedVarbits()
	{
		int[] core = {VarbitID.SPELLBOOK, VarbitID.COMBAT_WEAPON_CATEGORY, VarbitID.AUTOCAST_DEFMODE,
				VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
				VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
				VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4};
		int[] all = java.util.Arrays.copyOf(core, core.length + 8);
		System.arraycopy(BOLT_TYPES, 0, all, core.length, 4);
		System.arraycopy(BOLT_AMOUNTS, 0, all, core.length + 4, 4);
		return all;
	}

	static int boltId(int type)
	{
		return type > 0 && type < BOLTS.length ? BOLTS[type] : -1;
	}

	static void capture(Client client, JsonObject setup)
	{
		boolean pouch = false;
		for (JsonElement e : setup.getAsJsonArray("inv"))
			if (SetupCodec.id(e) == ItemID.XBOWS_BOLT_POUCH)
				pouch = true;
		if (pouch)
		{
			JsonArray contents = SetupCodec.empty(4);
			for (int i = 0; i < 4; i++)
			{
				int id = boltId(client.getVarbitValue(BOLT_TYPES[i])), amount = client.getVarbitValue(BOLT_AMOUNTS[i]);
				if (id > 0 && amount > 0)
					contents.set(i, SetupCodec.item(id, amount));
			}
			setup.add("bp", contents);
		}
		String option = attackOption(client);
		if (!option.isEmpty())
			setup.addProperty("ao", option);
	}

	static String attackOption(Client client)
	{
		int mode = client.getVarpValue(VarPlayerID.COM_MODE),
				category = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		if (mode == 4)
			return client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE) == 1 ? "D. Cast" : "Cast";
		// Cache DBTable 78 maps weapon categories to combat modes; no gameval constant exists.
		try
		{
			for (int row : client.getDBTableRows(78))
			{
				Object[] kind = client.getDBTableField(row, 0, 0);
				if (kind.length == 0 || !kind[0].equals(category))
					continue;
				Object[] modes = client.getDBTableField(row, 1, 0), names = client.getDBTableField(row, 1, 1);
				for (int i = 0; i < Math.min(modes.length, names.length); i++)
					if (modes[i].equals(mode))
						return String.valueOf(names[i]);
			}
		}
		catch (RuntimeException ex)
		{
			return "";
		}
		return "";
	}
}

