	@Override
	protected void startUp()
	{
		active = true;
		diagnostics.clear();
		diagnostics.enabled(config.localDiagnostics());
		wiki = new WikiClient(http, gson, 2000, new WikiCacheFile(this::getPluginDirectory), config::wikiFreshDays);
		wiki.diagnostics(diagnostics);
		potionStorage = new StudioPotionStorage(client, itemManager);
		independentBank = new IndependentBankView(client, clientThread, bankSearch,
				id -> bankFilter == null ? itemManager.canonicalize(id) : bankFilter.layoutItemId(id));
		independentBank.potions(potionStorage);
		independentBank.onChanged(this::localBankLayoutChanged);
		independentBank.onFailure(error ->
		{
			diagnostics.failure(StudioDiagnostics.Operation.BANK_LAYOUT, error, 0);
			if (bankFilter != null)
				bankFilter.pause();
			reportBankStatus(
					"Bank layout failed and was paused. Close and reopen the Bank, then review Diagnostics before retrying.");
		});
		placeholderOverlay = new BankPlaceholderOverlay(client, independentBank, itemManager);
		overlayManager.add(placeholderOverlay);
		bankBuildRefresh = new BankBuildRefresh(task -> clientThread.invokeAtTickEnd(task),
				this::refreshAfterBankBuild);
		filterHotkey = new net.runelite.client.util.HotkeyListener(config::filterHotkey)
		{
			@Override
			public void hotkeyPressed()
			{
				clientThread.invoke(() ->
				{
					net.runelite.api.widgets.Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
					if (!active || bank == null || bank.isHidden())
						return;
					String owner = recoveryOwner();
					SwingUtilities.invokeLater(() ->
					{
						if (active && panel != null && owner.equals(recoveryOwner()))
							panel.toggleBankFilter();
					});
				});
			}
		};
		keyManager.registerKeyListener(filterHotkey);
		importWorker = java.util.concurrent.Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "loadout-local-import");
			t.setDaemon(true);
			return t;
		});
		bankFilter = new StudioBankFilter(new StudioBankFilter.Gateway()
		{
			public boolean bankOpen()
			{
				net.runelite.api.widgets.Widget w = client.getWidget(InterfaceID.Bankmain.ITEMS);
				return client.getGameState() == GameState.LOGGED_IN && w != null && !w.isHidden()
						&& w.getChildren() != null && w.getChildren().length > 0;
			}

			public String competingTag()
			{
				BankTagsPlugin tags = coreBankTags();
				return tags == null ? null : tags.getActiveTag();
			}

			public boolean respectOtherFilters()
			{
				return config.respectOtherBankFilters();
			}

			public void pauseOwnedView()
			{
				if (independentBank.active())
					independentBank.clear();
			}

			public int capacity()
			{
				net.runelite.api.widgets.Widget w = client.getWidget(InterfaceID.Bankmain.ITEMS);
				return w == null || w.getChildren() == null ? 0 : w.getChildren().length;
			}

			public String activeTag()
			{
				return independentBank.active()
						? ownedTag()
						: coreBankTags() == null ? null : coreBankTags().getActiveTag();
			}

			public int[] currentLayout()
			{
				return independentBank.active() ? independentBank.layout() : null;
			}

			public int canonicalize(int id)
			{
				return itemManager.canonicalize(id);
			}

			public int variation(int id)
			{
				return SetupVariationMapping.fuzzy(id);
			}

			public void register(String tag, java.util.function.IntPredicate matches)
			{
				activeBankMatches = matches;
			}

			public void open(String tag, int[] layout)
			{
				BankTagsPlugin tags = coreBankTags();
				if (tags != null && tags.getActiveTag() != null)
					tags.closeBankTag();
				independentBank.select(layout, activeBankMatches);
			}

			public void title(String title)
			{
				net.runelite.api.widgets.Widget widget = client.getWidget(InterfaceID.Bankmain.TITLE);
				if (widget != null && !title.equals(widget.getText()))
					widget.setText(title);
			}

			public void close()
			{
				independentBank.clear();
			}

			public void unregister(String tag)
			{
				activeBankMatches = id -> false;
			}

			public void discardLayout(String tag)
			{
			}
		}, ownedBankTag);
		SwingUtilities.invokeLater(() ->
		{
			if (!active)
				return;
			panel = new StudioPanel(this, gson);
			navigation = NavigationButton.builder().tooltip("Loadout Studio").icon(icon()).panel(panel).priority(7)
					.build();
			toolbar.addNavigation(navigation);
		});
		clientThread.invokeLater(() ->
		{
			indexItems();
			if (client.getGameState() == GameState.LOGGED_IN)
				indexGearVarps();
		});
		gearDirty = true;
	}

	@Override
	protected void shutDown()
	{
		active = false;
		importRevision.incrementAndGet();
		cancelItemInput();
		if (wiki != null)
			wiki.close();
		if (importWorker != null)
			importWorker.shutdownNow();
		if (placeholderOverlay != null)
			overlayManager.remove(placeholderOverlay);
		placeholderOverlay = null;
		if (filterHotkey != null)
			keyManager.unregisterKeyListener(filterHotkey);
		filterHotkey = null;
		quickLinks = java.util.Collections.emptyList();
		gearObserver = null;
		layoutObserver = null;
		bankObserver = null;
		lastGear = null;
		clearBankObservation();
		bankRevision.incrementAndGet();
		StudioBankFilter previousFilter = bankFilter;
		bankFilter = null;
		clientThread.invoke(() ->
		{
			if (previousFilter != null)
				previousFilter.clear();
		});
		SwingUtilities.invokeLater(() ->
		{
			if (navigation != null)
				toolbar.removeNavigation(navigation);
			if (panel != null)
				panel.dispose();
			panel = null;
			navigation = null;
		});
		catalogue.clear();
		indexing = false;
		nextItem = 0;
	}

	private String ownedTag()
	{
		return ownedBankTag;
	}

	private BankTagsPlugin coreBankTags()
	{
		for (Plugin plugin : pluginManager.getPlugins())
			if (plugin instanceof BankTagsPlugin && pluginManager.isPluginActive(plugin))
				return (BankTagsPlugin) plugin;
		return null;
	}

	@Override
	public void observeBank(Runnable observer)
	{
		bankObserver = observer;
	}

	private void localBankLayoutChanged()
	{
		if (bankFilter == null)
			return;
		JsonArray layout = bankFilter.readChangedLayout();
		Consumer<JsonArray> observer = layoutObserver;
		long revision = bankRevision.get();
		if (layout != null && observer != null)
			SwingUtilities.invokeLater(() ->
			{
				if (active && revision == bankRevision.get())
					observer.accept(layout);
			});
	}

	@Subscribe(
			priority = -2)
	public void onScriptCallbackEvent(net.runelite.api.events.ScriptCallbackEvent event)
	{
		if (active && independentBank != null)
			independentBank.callback(event);
	}

	@Subscribe
	public void onPluginChanged(net.runelite.client.events.PluginChanged event)
	{
		if (event.getPlugin() instanceof BankTagsPlugin)
			clientThread.invokeAtTickEnd(() ->
			{
				if (active && bankFilter != null)
				{
					reportBankStatus(bankFilter.apply(independentBank.active()));
					bankBuildRefresh.request(false);
				}
			});
	}

	private static BufferedImage icon()
	{
