	@Subscribe
	public void onMenuOpened(net.runelite.api.events.MenuOpened event)
	{
		if (!active || panel == null || (!config.bankMenu() && !config.bankLayoutMenu()))
			return;
		net.runelite.api.MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (java.util.Arrays.stream(entries)
				.anyMatch(e -> (e.getOption().equals("Loadout setups:") || e.getOption().equals("Loadout:"))))
			return;
		if (java.util.Arrays.stream(entries).noneMatch(e -> e.getParam1() == InterfaceID.Bankmain.WORNITEMS_BUTTON
				&& e.getType() == net.runelite.api.MenuAction.CC_OP && e.getIdentifier() == 1))
			return;
		String owner = recoveryOwner(), token = panel.bankMenuToken();
		if (token == null && (!config.bankMenu() || quickLinks.isEmpty()))
			return;
		StudioBankMenu.add(client.getMenu(), token != null, config.bankLayoutMenu(),
				config.bankMenu() ? quickLinks : java.util.Collections.emptyList(),
				action -> runBankMenu(owner, token, action), id -> SwingUtilities.invokeLater(() ->
				{
					if (active && panel != null && owner.equals(recoveryOwner()))
					{
						if (navigation != null)
							toolbar.openPanel(navigation);
						panel.openSaved(id);
					}
				}));
	}

	private void runBankMenu(String owner, String token, Consumer<StudioPanel> action)
	{
		SwingUtilities.invokeLater(() ->
		{
			StudioPanel current = panel;
			if (active && current != null && owner.equals(recoveryOwner()) && token.equals(current.bankMenuToken()))
			{
				if (navigation != null)
					toolbar.openPanel(navigation);
				action.accept(current);
			}
		});
	}

	@Override
	public void pauseBankFilter()
	{
		clientThread.invoke(() ->
		{
			if (active && bankFilter != null)
				bankFilter.pause();
		});
	}

	@Subscribe
	public void onMenuOptionClicked(net.runelite.api.events.MenuOptionClicked event)
	{
		if (active && independentBank != null)
			independentBank.rewrite(event);
		if (!active || bankFilter == null
				|| net.runelite.api.widgets.WidgetUtil.componentToInterface(event.getParam1()) != InterfaceID.BANKMAIN)
			return;
		String option = event.getMenuEntry().getOption();
		if (option.startsWith("View tab") || option.equals("View tag tab") || option.equals("View all items")
				|| event.getParam1() == InterfaceID.Bankmain.POTIONSTORE_BUTTON)
			bankFilter.pause();
	}

	@Subscribe
	public void onWidgetLoaded(net.runelite.api.events.WidgetLoaded event)
	{
		if (active && bankFilter != null && event.getGroupId() == InterfaceID.BANKMAIN)
		{
			potionStorage.invalidate();
			bankFilter.bankOpened();
			bankBuildRefresh.request(true);
		}
