	@Override
	public void observeGear(Consumer<JsonObject> observer)
	{
		gearObserver = observer;
		gearDirty = true;
	}

	@Override
	public void requestGear()
	{
		clientThread.invoke(() ->
		{
			lastGear = null;
			gearDirty = true;
		});
	}

	private void indexGearVarps()
	{
		gearVarps.clear();
		for (int bit : GearContainers.trackedVarbits())
			gearVarps.add(client.getVarbit(bit).getIndex());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
			gearDirty = true;
		if (event.getContainerId() == InventoryID.BANK)
			observeBank();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (active && potionStorage != null && potionStorage.changed(event.getVarpId()) && bankBuildRefresh != null)
			bankBuildRefresh.request(false);
		if (gearVarps.contains(event.getVarpId()))
			gearDirty = true;
		if (event.getVarpId() == VarPlayerID.COM_MODE || event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO
				|| event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT)
			gearDirty = true;
		int bit = event.getVarbitId();
		if (bit == VarbitID.SPELLBOOK || bit == VarbitID.COMBAT_WEAPON_CATEGORY || bit == VarbitID.AUTOCAST_DEFMODE
				|| bit == VarbitID.RUNE_POUCH_TYPE_1 || bit == VarbitID.RUNE_POUCH_TYPE_2
				|| bit == VarbitID.RUNE_POUCH_TYPE_3 || bit == VarbitID.RUNE_POUCH_TYPE_4
				|| bit == VarbitID.RUNE_POUCH_QUANTITY_1 || bit == VarbitID.RUNE_POUCH_QUANTITY_2
				|| bit == VarbitID.RUNE_POUCH_QUANTITY_3 || bit == VarbitID.RUNE_POUCH_QUANTITY_4
				|| GearContainers.isBoltVarbit(bit))
			gearDirty = true;
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (active && independentBank != null && independentBank.active() && bankFilter != null)
			bankFilter.refreshTitle();
		if (!active || !gearDirty || client.getGameState() != GameState.LOGGED_IN)
			return;
		gearDirty = false;
		String owner = recoveryOwner();
		long epoch = gearEpoch;
		capture(snapshot ->
		{
			if (!active || !owner.equals(recoveryOwner()) || epoch != gearEpoch)
				return;
			if (!snapshot.equals(lastGear))
			{
				lastGear = snapshot.deepCopy();
				if (gearObserver != null)
					gearObserver.accept(snapshot);
			}
		}, error ->
		{
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (active && LoadoutStudioConfig.GROUP.equals(event.getGroup())
				&& event.getKey().equals("respectOtherBankFilters"))
			clientThread.invokeAtTickEnd(() ->
			{
				if (active && bankFilter != null)
					reportBankStatus(bankFilter.apply());
			});
		if (active && LoadoutStudioConfig.GROUP.equals(event.getGroup())
				&& LoadoutStudioConfig.isPreferenceKey(event.getKey()))
		{
			SwingUtilities.invokeLater(() ->
			{
				if (active && panel != null)
					panel.preferencesChanged();
			});
			return;
		}
	}

	private void clearBankObservation()
	{
		clientThread.invoke(() ->
		{
			observedBank.clear();
			bankObservedAt = 0;
			if (potionStorage != null)
				potionStorage.clear();
		});
	}

	private void observeBank()
	{
		net.runelite.api.widgets.Widget widget = client.getWidget(InterfaceID.Bankmain.ITEMS);
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (client.getGameState() != GameState.LOGGED_IN || widget == null || widget.isHidden() || bank == null)
			return;
		boolean firstObservation = bankObservedAt == 0;
		java.util.Map<Integer, Integer> before = new java.util.LinkedHashMap<>(observedBank);
		observedBank.clear();
		for (Item item : bank.getItems())
			if (item.getId() > 0 && item.getQuantity() > 0
					&& itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() == -1)
				observedBank.merge(itemManager.canonicalize(item.getId()), item.getQuantity(),
						(a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b));
		bankObservedAt = System.currentTimeMillis();
		if ((firstObservation || !before.equals(observedBank)) && bankObserver != null)
		{
			String owner = recoveryOwner();
			SwingUtilities.invokeLater(() ->
			{
				if (active && owner.equals(recoveryOwner()) && bankObserver != null)
					bankObserver.run();
			});
		}
	}

	@Override
	public void availableGear(JsonObject expected, Consumer<OwnedGear> success, Consumer<String> error)
	{
		String owner = recoveryOwner();
		clientThread.invoke(() ->
		{
			if (!active || !owner.equals(recoveryOwner()))
				return;
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				SwingUtilities
						.invokeLater(() -> error.accept("Log in and open your Bank to check owned alternatives."));
				return;
			}
			observeBank();
			java.util.Map<Integer, Integer> amounts = new java.util.LinkedHashMap<>(observedBank);
			if (potionStorage != null)
				potionStorage.counts().forEach((id, count) -> amounts.merge(id, count,
						(a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b)));
			java.util.Map<Integer, StudioPanel.ItemInfo> details = new java.util.LinkedHashMap<>();
			for (int container : new int[]{InventoryID.INV, InventoryID.WORN})
			{
				ItemContainer items = client.getItemContainer(container);
				if (items != null)
					for (Item item : items.getItems())
						if (item.getId() > 0 && item.getQuantity() > 0)
							amounts.merge(itemManager.canonicalize(item.getId()), item.getQuantity(),
									(a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b));
			}
			java.util.Set<Integer> ids = new java.util.LinkedHashSet<>(amounts.keySet());
			for (com.google.gson.JsonElement e : BankLayouts.items(expected))
				if (SetupCodec.id(e) > 0)
					ids.add(SetupCodec.id(e));
			for (int id : ids)
			{
				ItemComposition item = itemManager.getItemComposition(id);
				ItemStats stats = equipmentStats(id);
				details.put(id, new StudioPanel.ItemInfo(id, item.getMembersName(), item.isStackable(),
						stats != null && stats.getEquipment() != null ? stats.getEquipment().getSlot() : -1, null));
			}
			net.runelite.api.widgets.Widget widget = client.getWidget(InterfaceID.Bankmain.ITEMS);
			OwnedGear result = new OwnedGear(amounts, details, bankObservedAt, widget != null && !widget.isHidden());
			SwingUtilities.invokeLater(() ->
			{
				if (active && owner.equals(recoveryOwner()))
					success.accept(result);
			});
		});
	}

