	@Subscribe(
			priority = -1)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (independentBank != null
				&& (event.getScriptId() == ScriptID.BANKMAIN_BUILD || event.getScriptId() == ScriptID.BANKMAIN_INIT))
			independentBank.removeCopies();
		if (event.getScriptId() == ScriptID.BANKMAIN_INIT)
		{
			if (potionStorage != null)
				potionStorage.invalidate();
			observeBank();
			if (bankBuildRefresh != null)
				bankBuildRefresh.request(true);
		}
		else if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING && bankBuildRefresh != null)
			bankBuildRefresh.request(false);
	}

	private void refreshAfterBankBuild(boolean opening)
	{
		if (!active || bankFilter == null)
			return;
		try
		{
			if (potionStorage != null)
				try
				{
					potionStorage.refresh();
				}
				catch (RuntimeException | AssertionError error)
				{
					potionStorage.unavailable();
					diagnostics.failure(StudioDiagnostics.Operation.BANK_LAYOUT, error, 0);
					reportBankStatus(
							"Potion storage could not be read. Bank items remain available; reopen the Bank to retry.");
				}
			observeBank();
			BankTagsPlugin tags = coreBankTags();
			if (opening || bankFilter.waiting()
					|| independentBank.active() && tags != null && tags.getActiveTag() != null)
				reportBankStatus(bankFilter.apply(independentBank.active()));
			bankFilter.refreshTitle();
			if (independentBank.active())
				independentBank.arrange();
		}
		catch (RuntimeException ex)
		{
			diagnostics.failure(StudioDiagnostics.Operation.BANK_FILTER, ex, 0);
			bankFilter.clear();
			reportBankStatus(ex.getMessage());
		}
	}

