	@Override
	public void updateBankFilter(JsonObject portable, String scope, Consumer<String> callback,
			Consumer<JsonArray> layoutChanged, boolean explicit)
	{
		long started = System.nanoTime();
		JsonObject snapshot = portable.deepCopy();
		long revision = bankRevision.incrementAndGet();
		clientThread.invoke(() ->
		{
			if (!active || bankFilter == null || revision != bankRevision.get()
					|| !java.util.Objects.equals(scope, scope()))
				return;
			layoutObserver = layoutChanged;
			String result;
			try
			{
				result = bankFilter.select(snapshot, explicit);
				diagnostics.completed(StudioDiagnostics.Operation.BANK_FILTER,
						result.startsWith("Another Bank filter")
								? StudioDiagnostics.Outcome.EXPECTED_STATE
								: StudioDiagnostics.Outcome.SUCCESS,
						started);
			}
			catch (RuntimeException ex)
			{
				diagnostics.failure(StudioDiagnostics.Operation.BANK_FILTER, ex, started);
				bankFilter.clear();
				result = ex.getMessage();
			}
			String message = result;
			SwingUtilities.invokeLater(() ->
			{
				if (active && revision == bankRevision.get())
					callback.accept(message);
			});
		});
	}

