			return;
		importWorker.execute(() ->
		{
			try
			{
				ExistingSetupReader.Result result = new ExistingSetupReader(gson, new ExistingSetupReader.Source()
				{
					public List<String> keys(String group, String prefix)
					{
						String whole = ConfigManager.getWholeKey(group, null, prefix);
						List<String> keys = new java.util.ArrayList<>();
						for (String key : configManager.getConfigurationKeys(whole))
							keys.add(key.substring(whole.length() - prefix.length()));
						return keys;
					}

					public String get(String group, String key)
					{
						return configManager.getConfiguration(group, key);
					}
				}).read();
				SwingUtilities.invokeLater(() ->
				{
					if (active && revision == importRevision.get() && owner.equals(recoveryOwner()))
						success.accept(result);
				});
			}
			catch (RuntimeException ex)
			{
				SwingUtilities.invokeLater(() ->
				{
					if (active && revision == importRevision.get() && owner.equals(recoveryOwner()))
						error.accept(
								"Existing setups could not be read. Their original data was not changed; portable JSON import is still available.");
