	private void indexItems()
	{
		if (!active || indexing || client.getItemCount() < 1 || nextItem >= client.getItemCount())
			return;
		indexing = true;
		clientThread.invokeLater(() ->
		{
			if (!active)
			{
				indexing = false;
				return true;
			}
			int limit = Math.min(client.getItemCount(), nextItem + 150);
			for (; nextItem < limit; nextItem++)
			{
				ItemComposition composition = itemManager.getItemComposition(nextItem);
				ItemStats stats = equipmentStats(nextItem);
				int slot = stats != null && stats.getEquipment() != null ? stats.getEquipment().getSlot() : -1;
				catalogue.add(nextItem, composition.getMembersName(), composition.isStackable(), composition.getNote(),
						composition.getPlaceholderTemplateId(), slot, composition.isGeTradeable(),
						composition.getInventoryActions() != null && java.util.Arrays
								.stream(composition.getInventoryActions()).anyMatch(java.util.Objects::nonNull));
				catalogue.bankId(nextItem, itemManager.canonicalize(nextItem));
			}
			if (nextItem < client.getItemCount())
				return false;
			indexing = false;
			catalogue.indexed();
			return true;
		});
	}

	private ItemStats equipmentStats(int id)
	{
		ItemStats stats = itemManager.getItemStats(id);
		int base = EquipmentVariants.combatBase(id);
		return (stats == null || stats.getEquipment() == null) && base != id ? itemManager.getItemStats(base) : stats;
	}

