	@Override
	public void capture(Consumer<JsonObject> callback, Consumer<String> error)
	{
		clientThread.invoke(() ->
		{
			if (!active)
				return;
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				SwingUtilities.invokeLater(() -> error.accept("Log in before capturing gear."));
				return;
			}
			JsonObject p = SetupCodec.blank("Current gear"), s = SetupCodec.setup(p);
			s.add("inv", snapshot(client.getItemContainer(InventoryID.INV), 28));
			s.add("eq", snapshot(client.getItemContainer(InventoryID.WORN), 14));
			boolean pouch = false, divine = false, quiver = false;
			for (String key : new String[]{"inv", "eq"})
				for (com.google.gson.JsonElement e : s.getAsJsonArray(key))
					if (SetupCodec.id(e) > 0)
					{
						String name = itemManager.getItemComposition(SetupCodec.id(e)).getName()
								.toLowerCase(Locale.ROOT);
						pouch |= name.contains("rune pouch");
						divine |= name.contains("divine rune pouch");
						quiver |= name.contains("dizana") && (name.contains("quiver") || name.contains("max cape"));
					}
			if (pouch)
			{
				int[] types = {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
						VarbitID.RUNE_POUCH_TYPE_4};
				int[] amounts = {VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
						VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4};
				// Rune pouch enum 982 is the cache's rune-type-to-item mapping (no gameval constant is provided).
				for (int i = 0; i < (divine ? 4 : 3); i++)
				{
					int type = client.getVarbitValue(types[i]), amount = client.getVarbitValue(amounts[i]);
					if (type > 0 && amount > 0)
						s.getAsJsonArray("rp").set(i, SetupCodec.item(client.getEnum(982).getIntValue(type), amount));
				}
			}
			if (quiver)
			{
				int ammo = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO),
						amount = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
				if (ammo > 0 && amount > 0)
					s.getAsJsonArray("qv").set(0, SetupCodec.item(ammo, amount));
			}
			s.addProperty("sb", client.getVarbitValue(VarbitID.SPELLBOOK));
			GearContainers.capture(client, s);
			SetupCodec.rebuildLayout(p);
			SwingUtilities.invokeLater(() ->
			{
				if (active)
					callback.accept(p);
			});
		});
	}

	private static JsonArray snapshot(ItemContainer container, int size)
	{
		JsonArray result = SetupCodec.empty(size);
		if (container == null)
			return result;
		Item[] items = container.getItems();
		for (int i = 0; i < Math.min(size, items.length); i++)
			if (items[i].getId() > 0 && items[i].getQuantity() > 0)
				result.set(i, SetupCodec.item(items[i].getId(), items[i].getQuantity()));
		return result;
	}
}

