		bankStatus.setWrapStyleWord(true);
		host.observeBank(this::scheduleAlternatives);
		host.observeGear(this::acceptLiveGear);
		preferencesChanged();
	}

	public void dispose()
	{
		if (editingId != null)
			autoSaveNow();
		autoSaveTimer.stop();
		disposed = true;
		bankMenuToken = null;
		host.observeBank(null);
		host.observeGear(null);
		host.cancelItemInput();
		catalogueTimer.stop();
		alternativeTimer.stop();
		if (wikiSuggestTimer != null)
			wikiSuggestTimer.stop();
		if (wikiPageTimer != null)
			wikiPageTimer.stop();
		wikiSearchRevision++;
		wikiPageRevision++;
	}

	public void bankMessage(String value)
	{
		if (!disposed)
		{
			bankStatus.setText(value == null ? "Bank filtering failed." : value);
			boolean paused = value != null && value.startsWith("Another Bank filter");
			if (paused || builderFeedback.getText().startsWith("Another Bank filter"))
			{
				builderFeedback.setText(paused ? value : "");
				builderFeedback.setVisible(paused);
				builderTools.revalidate();
				builderTools.repaint();
			}
		}
	}

	private void syncBankFilter()
	{
		syncBankFilter(false);
	}

	private void syncBankFilter(boolean explicit)
	{
		if (disposed || draft == null)
			return;
		String token = session;
		fieldsToDraft();
		host.updateBankFilter(draft, scope, value ->
		{
			if (token.equals(session))
				bankMessage(value);
		}, layout ->
		{
			if (!disposed && token.equals(session) && draft != null && !layout.equals(draft.get("layout")))
			{
				draft.add("layout", layout.deepCopy());
				editorLayout = BankLayouts.Mode.CUSTOM;
				markDirty();
				renderBuilder();
				message("Custom Bank layout updated and autosave scheduled.");
			}
		}, explicit);
	}

