	{
		return bankMenuToken;
	}

	public void showBankFromMenu()
	{
		host.pauseBankFilter();
		bankMessage("Showing your Bank. Return to loadout from Show worn items, or reopen the Bank.");
	}

	public void activateFromBankMenu()
	{
		attempt(StudioDiagnostics.Operation.BANK_FILTER, () ->
		{
			if (draft == null)
				throw new IllegalStateException("Open a setup in Builder first.");
			filterBank.setSelected(true);
			markDirty();
			renderBuilder();
			syncBankFilter(true);
		});
	}

	public void clearFromBankMenu()
	{
		attempt(StudioDiagnostics.Operation.BANK_FILTER, () -> setBankFiltering(false));
	}

	public void layoutFromBankMenu(BankLayouts.Mode mode, boolean bottom)
	{
		attempt(StudioDiagnostics.Operation.BANK_LAYOUT, () ->
		{
			if (draft == null)
				throw new IllegalStateException("Open a setup in Builder first.");
			if (mode == BankLayouts.Mode.CUSTOM)
				throw new IllegalArgumentException("Choose Preset or Zigzag.");
			fieldsToDraft();
			editorLayout = mode;
			editorBottom = bottom;
			filterBank.setSelected(true);
			draft.add("layout", BankLayouts.generate(draft, mode, bottom));
			markDirty();
			renderBuilder();
			syncBankFilter(true);
			message("Loadout Studio layout changed to " + mode + ". Changes are saved automatically.");
		});
	}

	private void setBankFiltering(boolean enabled)
	{
		if (draft == null)
			return;
		filterBank.setSelected(enabled);
		fieldsToDraft();
		markDirty();
		syncBankFilter(enabled);
		renderBuilder();
	}

	private void rebuildDraftLayout()
	{
		draft.add("layout", BankLayouts.generate(draft, editorLayout, editorBottom));
		syncBankFilter();
	}
