	private JPanel disclosure(String title, Component content)
	{
		JPanel p = vertical();
		content.setVisible(expandedPanels.contains(title));
		JButton toggle = button((content.isVisible() ? "- " : "+ ") + title, () ->
		{
		});
		toggle.setName("disclosure:" + title);
		toggle.setHorizontalAlignment(JButton.LEFT);
		toggle.putClientProperty("disclosure", true);
		toggle.addActionListener(e ->
		{
			boolean open = !content.isVisible();
			content.setVisible(open);
			if (open)
				expandedPanels.add(title);
			else
				expandedPanels.remove(title);
			toggle.setText((open ? "- " : "+ ") + title);
			for (Container ancestor = p; ancestor != null; ancestor = ancestor.getParent())
			{
				ancestor.invalidate();
				if (ancestor == this)
					break;
			}
			p.revalidate();
		});
		p.add(toggle);
		p.add(content);
		return p;
	}

