	private void message(String value)
	{
		if (!disposed)
		{
			for (JTextArea feedback : new JTextArea[]{libraryFeedback, builderFeedback, exportFeedback})
			{
				feedback.setVisible(false);
				feedback.setText("");
			}
			status.setText(value == null ? "Could not complete this action." : value);
			status.setToolTipText(status.getText());
		}
	}

	private void failure(String value)
	{
		message(value);
		if (disposed)
			return;
		JTextArea feedback = tabs.getSelectedIndex() == 0
				? libraryFeedback
				: tabs.getSelectedIndex() == 1 ? builderFeedback : tabs.getSelectedIndex() == 3 ? exportFeedback : null;
		if (feedback != null)
		{
			feedback.setText(status.getText());
			feedback.setToolTipText(status.getText());
			themeForm(feedback);
			feedback.setForeground(RED);
			feedback.setVisible(true);
			revalidate();
			repaint();
		}
	}

	private static String failureMessage(RuntimeException error)
	{
		String detail = error.getMessage();
		return detail == null || detail.trim().isEmpty()
				? "Could not complete this action (" + error.getClass().getSimpleName() + ")."
				: detail;
	}

	private void attempt(Runnable action)
	{
		attempt(StudioDiagnostics.Operation.UI_ACTION, action);
	}

	private void attempt(StudioDiagnostics.Operation operation, Runnable action)
	{
		long started = System.nanoTime();
		try
		{
			action.run();
			diagnostics.completed(operation, StudioDiagnostics.Outcome.SUCCESS, started);
		}
		catch (RuntimeException error)
		{
			diagnostics.failure(operation, error, started);
			failure(failureMessage(error));
		}
	}

	public void reloadScope()
	{
		autoSaveTimer.stop();
		alternativeTimer.stop();
		alternativeRequestVersion++;
		diagnostics.enabled(host.settings().localDiagnostics());
		appliedAutoExpand = host.settings().autoShowAlternatives();
		autoShownAlternativeSession = null;
		if (!appliedAutoExpand)
			expandedPanels.remove("My gear alternatives");
		libraryOrder = host.settings().libraryOrder();
		ignoreAmmo.setSelected(host.settings().ignoreAmmoQuantities());
		liveActual = null;
		alternativeUndo = null;
		upgradeBefore = null;
		upgradeAfter = null;
		alternativeRows.removeAll();
		host.cancelItemInput();
		host.clearBankFilter();
		bankMessage("Bank filter off.");
		if (disposed)
			return;
		boolean recoveryFailed = false;
		if (wikiSuggestTimer != null)
			wikiSuggestTimer.stop();
		if (wikiPageTimer != null)
			wikiPageTimer.stop();
		wikiSearchRevision++;
		wikiPageRevision++;
		wikiPresetRows.removeAll();
		wikiPageStatus.setText("Choose a Wiki page to see its setups.");
		scope = host.scope();
		recoveryOwner = host.recoveryOwner();
		recovery = null;
		existingControls.removeAll();
		draft = null;
		editingId = null;
		dirty = false;
		differences.clear();
		session = UUID.randomUUID().toString();
		code.setText("");
		storageError = false;
		try
		{
			library = SetupLibrary.read(host.read(scope), gson);
		}
		catch (RuntimeException e)
		{
			library = new SetupLibrary();
			storageError = true;
			failure("Library could not be read. Existing data was not overwritten. Restore a backup before saving.");
		}
		try
		{
			recovery = DraftRecovery.decode(host.readRecovery(scope, recoveryOwner), gson);
		}
		catch (RuntimeException ex)
		{
			recoveryFailed = true;
			failure("Recovery data could not be read. It was not overwritten.");
		}
		renderRecovery();
		scopeLabel.setText(scope == null ? "Local guest library" : "Character-specific library");
		renderLibrary();
		renderBuilder();
		if (!storageError && !recoveryFailed)
			message("Ready. Choose a saved setup, capture gear or search Wiki.");
	}

	private static String pageAge(WikiClient.Page page)
	{
		if (page.fetchedAt < 1)
			return "";
		String date = java.time.Instant.ofEpochMilli(page.fetchedAt).atZone(java.time.ZoneId.systemDefault())
				.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"));
		return (page.stale ? "Stale cached source · " : page.cached ? "Cached source · " : "Fetched from Wiki · ")
				+ date;
	}

	private void persistRecovery()
	{
		if (disposed || rendering || !dirty || draft == null)
			return;
		try
		{
			host.saveRecovery(scope, recoveryOwner, DraftRecovery.encode(draft, editingId, editorSection,
					editorFavorite, editorLayout, editorBottom, ignoreAmmo.isSelected(), gson));
		}
		catch (RuntimeException ex)
		{
			message("Draft recovery could not be saved. Use Save or export a backup.");
		}
	}

	private void clearRecovery()
	{
		host.saveRecovery(scope, recoveryOwner, null);
		recovery = null;
		renderRecovery();
	}

	private void renderRecovery()
	{
		recoveryControls.removeAll();
		if (recovery != null)
		{
			recoveryControls.add(info("An unsaved draft is available for this character/profile.", 2));
			JButton restore = button("Restore draft", this::restoreRecovery);
			restore.setName("restoreDraft");
			recoveryControls.add(row(restore, button("Discard recovery", () ->
			{
				if (JOptionPane.showConfirmDialog(this, "Discard this unsaved recovery? Saved setups stay intact.",
						"Discard recovery", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
					clearRecovery();
			})));
		}
		themeForm(recoveryControls);
		recoveryControls.revalidate();
		recoveryControls.repaint();
	}

	private void restoreRecovery()
	{
		if (recovery == null)
			return;
		JsonObject value = recovery.deepCopy();
		if (!discard())
			return;
		host.cancelItemInput();
		draft = value.getAsJsonObject("portable").deepCopy();
		editingId = DraftRecovery.optional(value, "editingId");
		if (editingId != null && library.find(editingId) == null)
			editingId = null;
		editorSection = DraftRecovery.optional(value, "section");
		editorFavorite = value.get("favorite").getAsBoolean();
		editorLayout = BankLayouts.Mode.valueOf(value.get("layout").getAsString());
		editorBottom = value.get("bottom").getAsBoolean();
		ignoreAmmo.setSelected(value.get("ignoreAmmo").getAsBoolean());
		dirty = true;
		session = UUID.randomUUID().toString();
		differences.clear();
		recovery = null;
		renderRecovery();
		renderBuilder();
		persistRecovery();
		syncBankFilter();
		tabs.setSelectedIndex(1);
		message("Unsaved draft restored. Review it, then Save.");
	}

