	int importCopies(List<ExistingSetupReader.Entry> selected)
	{
		if (selected.size() > 100)
			throw new IllegalArgumentException("Copy at most 100 setups at once.");
		int[] count = {0};
		commit(next ->
		{
			for (ExistingSetupReader.Entry candidate : selected)
			{

				SetupLibrary.Entry copy = new SetupLibrary.Entry(candidate.portable);
				SetupCodec.setup(copy.portable).addProperty("name", next.uniqueName(SetupCodec.name(copy.portable)));
				copy.favorite = candidate.favorite;
				if (candidate.section != null)
				{
					SetupLibrary.Section target = next.sections.stream()
							.filter(group -> group.name.equals(candidate.section)).findFirst().orElse(null);
					if (target == null)
					{
						target = new SetupLibrary.Section(candidate.section);
						next.sections.add(target);
					}
					copy.section = target.id;
				}
				copy.bankLayout = BankLayouts.infer(copy.portable);
				copy.zigzagBottomToTop = BankLayouts.inferBottom(copy.portable);
				next.setups.add(copy);
				count[0]++;
			}
		});
		return count[0];
	}

	private void commit(Consumer<SetupLibrary> change)
	{
		if (storageError)
			throw new IllegalStateException("Restore a valid library backup before saving.");
		SetupLibrary next = SetupLibrary.read(library.serialize(gson), gson);
		change.accept(next);
		String json = next.serialize(gson);
		host.save(scope, json);
		library = next;
		renderLibrary();
	}

