	private void renderLibrary()
	{
		List<SetupLibrary.Entry> recent = new ArrayList<>();
		for (SetupLibrary.Entry e : library.setups)
			if (!e.archived && (e.favorite || e.lastOpened > 0))
				recent.add(e);
		recent.sort(Comparator.comparing((SetupLibrary.Entry e) -> !e.favorite)
				.thenComparing(Comparator.comparingLong((SetupLibrary.Entry e) -> e.lastOpened).reversed()));
		List<QuickLink> shortcuts = new ArrayList<>();
		for (SetupLibrary.Entry e : recent.subList(0, Math.min(5, recent.size())))
			shortcuts.add(new QuickLink(e.id, SetupCodec.name(e.portable)));
		host.quickLinks(shortcuts);
		libraryRows.removeAll();
		String query = search.getText().trim().toLowerCase(java.util.Locale.ROOT);
		int matching = 0;
		List<SetupLibrary.Section> groups = new ArrayList<>();
		groups.add(new SetupLibrary.Section("Unfiled"));
		groups.get(0).id = null;
		groups.addAll(library.sections);
		for (SetupLibrary.Section group : groups)
		{
			List<SetupLibrary.Entry> records = new ArrayList<>();
			for (SetupLibrary.Entry entry : library.setups)
				if (Objects.equals(entry.section, group.id) && entry.archived == archived.isSelected()
						&& (!favorites.isSelected() || entry.favorite)
						&& LibraryTools.matches(entry, query, host::itemMatches))
					records.add(entry);
			if (libraryOrder.ordinal() == 0)
				records.sort(Comparator.comparing(e -> SetupCodec.name(e.portable), String.CASE_INSENSITIVE_ORDER));
			if (libraryOrder.ordinal() == 1)
				records.sort(Comparator.comparingLong((SetupLibrary.Entry e) -> e.lastOpened).reversed());
			if (libraryOrder.ordinal() == 2)
				records.sort(Comparator.comparing((SetupLibrary.Entry e) -> !e.favorite)
						.thenComparing(e -> SetupCodec.name(e.portable), String.CASE_INSENSITIVE_ORDER));
			matching += records.size();
			if (records.isEmpty() && (!query.isEmpty() || favorites.isSelected()))
				continue;
			String groupId = group.id == null ? "" : group.id;
			boolean filtering = !query.isEmpty() || favorites.isSelected();
			boolean folded = collapsed.contains(groupId) && !filtering;
			JButton heading = button((folded ? "+ " : "- ") + group.name + " (" + records.size() + ")", () ->
			{
				if (!collapsed.add(groupId))
					collapsed.remove(groupId);
				renderLibrary();
			});
			heading.setName("libraryGroup:" + groupId);
			heading.setForeground(GOLD);
			heading.setAlignmentX(LEFT_ALIGNMENT);
			heading.setEnabled(!filtering);
			if (filtering)
				heading.setToolTipText("Matching sections stay expanded while filtering.");
			installLibraryTarget(heading, group.id);
			libraryRows.add(heading);
			if (folded)
				continue;
			for (SetupLibrary.Entry entry : records)
			{
				LibrarySetupRow setupRow = new LibrarySetupRow(entry.id, SetupCodec.name(entry.portable),
						entry.favorite, entry.archived, () -> open(entry),
						() -> attempt(() -> setLibraryFavorite(entry.id, !entry.favorite)),
						() -> attempt(() -> commit(l -> l.find(entry.id).archived = !entry.archived)),
						() -> confirmDeleteArchived(entry.id));
				installLibrarySource((JButton) setupRow.getComponent(0), entry.id, group.id);
				installLibraryTarget(setupRow, group.id);
				String rowOwner = recoveryOwner;
				javax.swing.JPopupMenu ordering = new javax.swing.JPopupMenu();
				for (int direction : new int[]{-1, 1})
				{
					javax.swing.JMenuItem move = new javax.swing.JMenuItem(direction < 0 ? "Move up" : "Move down");
					move.addActionListener(e ->
					{
						if (rowOwner.equals(recoveryOwner))
							attempt(() -> moveSetup(entry.id, direction));
					});
					ordering.add(move);
				}
				themeMenu(ordering);
				((JButton) setupRow.getComponent(0)).setComponentPopupMenu(ordering);
				libraryRows.add(setupRow);
			}
		}
		if (matching == 0)
		{
			boolean filtered = !query.isEmpty() || favorites.isSelected() || archived.isSelected();
			if (filtered)
			{
				libraryRows.add(info(!query.isEmpty() || favorites.isSelected()
						? "No setups match these filters."
						: "No archived setups.", 2));
				libraryRows.add(button("Clear filters", () ->
				{
					favorites.setSelected(false);
					archived.setSelected(false);
					search.setText("");
					renderLibrary();
				}));
			}
			else
				libraryRows.add(card("Start a loadout", info(
						"Choose a Wiki setup, capture gear or start blank. Review items, Save, then open your Bank.",
						4), button("Find Wiki content", () -> tabs.setSelectedIndex(2)),
						button("Capture gear", this::capture),
						button("New setup", () -> createLocalDraft(SetupCodec.blank("New loadout")))));
		}
		themeForm(libraryRows);
		libraryRows.revalidate();
		libraryRows.repaint();
	}

	private void confirmDeleteArchived(String id)
	{
		SetupLibrary.Entry entry = library.find(id);
		if (entry == null || !entry.archived)
			return;
		String capturedScope = scope, owner = recoveryOwner;
		String warning = "Permanently delete \"" + SetupCodec.name(entry.portable)
				+ "\" from your saved library?\nThis cannot be undone.";
		if (id.equals(editingId))
			warning += "\nThe open Builder draft and its unsaved changes will also be discarded.";
		Object[] options = {"Cancel", "Delete permanently"};
		int chosen = JOptionPane.showOptionDialog(this, warning, "Delete archived setup", JOptionPane.DEFAULT_OPTION,
				JOptionPane.WARNING_MESSAGE, null, options, options[0]);
		if (Objects.equals(capturedScope, scope) && Objects.equals(owner, recoveryOwner))
			attempt(() -> deleteArchived(id, chosen == 1));
	}

	boolean deleteArchived(String id, boolean confirmed)
	{
		SetupLibrary.Entry entry = library.find(id);
		if (!confirmed || entry == null || !entry.archived)
			return false;
		commit(l ->
		{
			if (!l.removeArchived(id))
				throw new IllegalStateException("Only archived setups can be deleted.");
		});
		if (id.equals(editingId))
		{
			host.cancelItemInput();
			session = UUID.randomUUID().toString();
			draft = null;
			editingId = null;
			dirty = false;
			differences.clear();
			setupName.setText("");
			notes.setText("");
			code.setText("");
			clearRecovery();
			host.clearBankFilter();
			renderBuilder();
			tabs.setSelectedIndex(0);
		}
		else if (draft == null && recovery != null && id.equals(DraftRecovery.optional(recovery, "editingId")))
			clearRecovery();
		message("Archived setup permanently deleted.");
		return true;
	}

	boolean autoSaveNow()
	{
		autoSaveTimer.stop();
		if (disposed || draft == null || !dirty)
			return true;
		if (!Objects.equals(scope, host.scope()) || !Objects.equals(recoveryOwner, host.recoveryOwner()))
			return false;
		saveDraft(false);
		return !dirty;
	}

	private boolean discard()
	{
		return autoSaveNow();
	}

	void open(SetupLibrary.Entry entry)
	{
		if (!discard())
			return;
		final SetupLibrary.Entry source = library.find(entry.id) == null ? entry : library.find(entry.id);
		host.cancelItemInput();
		ignoreAmmo.setSelected(host.settings().ignoreAmmoQuantities());
		draft = source.portable.deepCopy();
		editorLayout = source.bankLayout == null ? BankLayouts.infer(draft) : source.bankLayout;
		editorBottom = source.bankLayout == null ? BankLayouts.inferBottom(draft) : source.zigzagBottomToTop;
		editingId = source.id;
		editorSection = source.section;
		editorFavorite = source.favorite;
		dirty = false;
		differences.clear();
		session = UUID.randomUUID().toString();
		renderBuilder();
		syncBankFilter();
		tabs.setSelectedIndex(1);
		String compactNotes = WikiParser.compactGeneratedNotes(notes.getText());
		if (!compactNotes.equals(notes.getText()))
			notes.setText(compactNotes);
		message("Opened saved setup. Changes are saved automatically.");
		alternativeRows.removeAll();
		alternativeUndo = null;
		if (library.find(source.id) != null)
			attempt(() -> commit(l -> l.find(source.id).lastOpened = System.currentTimeMillis()));
		host.requestGear();
		scheduleAlternatives();
		resolveDraftDefaults();
	}

	private void setLibraryFavorite(String id, boolean selected)
	{
		commit(next ->
		{
			SetupLibrary.Entry entry = next.find(id);
			if (entry == null)
				throw new IllegalStateException("Setup no longer exists.");
			entry.favorite = selected;
		});
		if (id.equals(editingId))
		{
			editorFavorite = selected;
			favorite.setSelected(selected);
			if (dirty)
				persistRecovery();
		}
		if (recovery != null && id.equals(DraftRecovery.optional(recovery, "editingId")))
		{
			JsonObject updated = recovery.deepCopy();
			updated.addProperty("favorite", selected);
			host.saveRecovery(scope, recoveryOwner, gson.toJson(updated));
			recovery = updated;
		}
	}

