	private void createLocalDraft(JsonObject source)
	{
		LoadoutStudioConfig settings = host.settings();
		String previous = session;
		newDraft(LoadoutDefaults.captured(source, settings));
		if (!previous.equals(session))
		{
			editorLayout = settings.defaultLayout() == LoadoutStudioConfig.DefaultLayout.ZIGZAG
					? BankLayouts.Mode.ZIGZAG
					: BankLayouts.Mode.PRESET;
			editorBottom = settings.defaultZigzagBottom();
			persistRecovery();
			renderBuilder();
		}
	}

	void preferencesChanged()
	{
		if (disposed)
			return;
		LoadoutStudioConfig settings = host.settings();
		int dot = notes.getCaret().getDot(), mark = notes.getCaret().getMark();
		if (draft != null)
			fieldsToDraft();
		diagnostics.enabled(settings.localDiagnostics());
		libraryOrder = settings.libraryOrder();
		ignoreAmmo.setSelected(settings.ignoreAmmoQuantities());
		code.setText("");
		alternativeTimer.stop();
		alternativeRequestVersion++;
		if (Boolean.TRUE.equals(appliedAutoExpand) && !settings.autoShowAlternatives())
			expandedPanels.remove("My gear alternatives");
		if (!Boolean.valueOf(settings.autoShowAlternatives()).equals(appliedAutoExpand))
			autoShownAlternativeSession = null;
		appliedAutoExpand = settings.autoShowAlternatives();
		if (alternativeUndo == null)
			alternativeRows.removeAll();
		renderLibrary();
		renderBuilder();
		notes.getCaret().setDot(Math.min(mark, notes.getDocument().getLength()));
		notes.getCaret().moveDot(Math.min(dot, notes.getDocument().getLength()));
		if (alternativeUndo == null && settings.autoAlternatives())
			scheduleAlternatives();
		revalidate();
		repaint();
	}

	private void newDraft(JsonObject p, boolean defaultsResolved)
	{
		SetupCodec.validate(p, false);
		if (!discard())
			return;
		host.cancelItemInput();
		alternativeRows.removeAll();
		alternativeUndo = null;
		ignoreAmmo.setSelected(host.settings().ignoreAmmoQuantities());
		draft = p.deepCopy();
		editorLayout = BankLayouts.infer(draft);
		editorBottom = BankLayouts.inferBottom(draft);
		editingId = null;
		editorSection = null;
		editorFavorite = false;
		dirty = true;
		differences.clear();
		session = UUID.randomUUID().toString();
		renderBuilder();
		syncBankFilter();
		tabs.setSelectedIndex(1);
		persistRecovery();
		message("New draft. Review it, then Save to your library.");
		host.requestGear();
		scheduleAlternatives();
		if (!defaultsResolved)
			resolveDraftDefaults();
	}

	private boolean needsDefault(JsonElement item)
	{
		if (SetupCodec.id(item) == 0)
			return true;
		if (item == null || !item.isJsonObject() || !item.getAsJsonObject().has("label"))
			return false;
		JsonObject value = item.getAsJsonObject();
		int id = SetupCodec.id(item);
		return ItemCatalogue.legacyRingId(id, value.get("label").getAsString()) != id
				|| value.has("choices") && AutomaticItemExclusions.avoidDefault(id);
	}

	private void resolveDraftDefaults()
	{
		boolean needed = false;
		for (String key : new String[]{"eq", "inv", "rp", "qv", "bp"})
			for (JsonElement e : SetupCodec.setup(draft).has(key) && SetupCodec.setup(draft).get(key).isJsonArray()
					? SetupCodec.setup(draft).getAsJsonArray(key)
					: new JsonArray())
				if (needsDefault(e))
					needed = true;
		if (!needed)
			return;
		String token = session;
		JsonObject current = draft;
		host.whenItemsReady(error ->
		{
			if (disposed || error != null || !token.equals(session) || current != draft)
				return;
			int resolved = 0, unresolved = 0;
			for (String key : new String[]{"eq", "inv", "rp", "qv", "bp"})
				for (JsonElement entry : SetupCodec.setup(draft).has(key)
						&& SetupCodec.setup(draft).get(key).isJsonArray()
								? SetupCodec.setup(draft).getAsJsonArray(key)
								: new JsonArray())
					if (needsDefault(entry))
					{
						JsonObject item = entry.getAsJsonObject();
						int oldId = SetupCodec.id(item);
						ItemInfo first = host.defaultItem(WikiParser.defaultName(item));
						if (first != null)
						{
							if (oldId > 0)
								for (int i = 0; i < draft.getAsJsonArray("layout").size(); i++)
									if (draft.getAsJsonArray("layout").get(i).getAsInt() == oldId)
										draft.getAsJsonArray("layout").set(i,
												new com.google.gson.JsonPrimitive(first.id));
							item.addProperty("id", first.id);
							item.addProperty("label", first.name);
							itemCache.put(first.id, first);
							resolved++;
						}
						else if (oldId > 0)
						{
							for (int i = 0; i < draft.getAsJsonArray("layout").size(); i++)
								if (draft.getAsJsonArray("layout").get(i).getAsInt() == oldId)
									draft.getAsJsonArray("layout").set(i, new com.google.gson.JsonPrimitive(-1));
							item.addProperty("id", 0);
							unresolved++;
						}
					}
			if (resolved > 0 || unresolved > 0)
			{
				rebuildDraftLayout();
				markDirty();
				renderBuilder();
				syncBankFilter();
				scheduleAlternatives();
				message("Applied first choices to " + resolved + " slot(s). " + unresolved
						+ " temporary item(s) need manual selection. Autosave is scheduled. Review the selected items.");
			}
		});
	}

	private void capture()
	{
		if (!discard())
			return;
		String capturedScope = scope, token = session, owner = recoveryOwner;
		long revision = draftRevision;
		host.capture(p ->
		{
			if (disposed || !Objects.equals(scope, capturedScope) || !Objects.equals(owner, recoveryOwner)
					|| !token.equals(session))
				return;
			if (revision != draftRevision)
			{
				message("Capture cancelled because the Builder changed. Your edits were kept.");
				return;
			}
			dirty = false;
			createLocalDraft(p);
		}, this::failure);
	}

	private void manageSections()
	{
		String[] options = new String[library.sections.size() + 1];
		options[0] = "+ New section";
		for (int i = 0; i < library.sections.size(); i++)
			options[i + 1] = library.sections.get(i).name;
		String choice = (String) JOptionPane.showInputDialog(this, "Choose a section", "Sections",
				JOptionPane.PLAIN_MESSAGE, null, options, options[0]);
		if (choice == null)
			return;
		if (choice.equals(options[0]))
		{
			String name = JOptionPane.showInputDialog(this, "Section name (1–60 characters)");
			if (name != null)
				attempt(() ->
				{
					commit(l -> l.sections.add(new SetupLibrary.Section(name.trim())));
					renderBuilder();
				});
		}
		else
		{
			int index = java.util.Arrays.asList(options).indexOf(choice) - 1;
			SetupLibrary.Section chosen = library.sections.get(index);
			int action = JOptionPane.showOptionDialog(this, "Rename this section or move its setups to Unfiled.",
					chosen.name, JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null,
					new String[]{"Rename", "Remove section", "Cancel"}, "Rename");
			if (action == 0)
			{
				String name = JOptionPane.showInputDialog(this, "Section name", chosen.name);
				if (name != null)
					attempt(() ->
					{
						commit(l -> l.sections.stream().filter(s -> s.id.equals(chosen.id)).findFirst()
								.get().name = name.trim());
						renderBuilder();
					});
			}
			else if (action == 1)
				attempt(() ->
				{
					commit(l -> l.removeSection(chosen.id));
					renderBuilder();
				});
		}
	}

	private void markDirty()
	{
		if (rendering || draft == null)
			return;
		draftRevision++;
		dirty = true;
		draftLabel.setText("Saving changes...");
		setupName.setToolTipText(setupName.getText() + " - Autosave pending (Ctrl+S to save now)");
		code.setText("");
		fieldsToDraft();
		persistRecovery();
		autoSaveTimer.setRepeats(false);
		autoSaveTimer.restart();
		refreshGearComparison();
	}

	private void fieldsToDraft()
	{
		if (draft == null)
