	void createBuilderSection(String input)
	{
		String name = input == null ? "" : input.trim();
		if (name.isEmpty() || name.length() > 60)
			throw new IllegalArgumentException("Section name must be 1–60 characters.");
		fieldsToDraft();
		SetupLibrary.Section chosen = library.sections.stream().filter(s -> s.name.equalsIgnoreCase(name)).findFirst()
				.orElse(null);
		if (chosen == null)
		{
			chosen = new SetupLibrary.Section(name);
			SetupLibrary.Section created = chosen;
			commit(l -> l.sections.add(created));
		}
		editorSection = chosen.id;
		markDirty();
		renderBuilder();
		message("Section selected. Autosave is scheduled.");
	}

	private void addResolutionGuide()
	{
		int remaining = 0;
		String targetKey = null;
		int targetIndex = 0;
		JsonObject target = null;
		for (String key : new String[]{"eq", "inv", "rp", "qv", "bp"})
		{
			JsonArray items = SetupCodec.setup(draft).has(key) && SetupCodec.setup(draft).get(key).isJsonArray()
					? SetupCodec.setup(draft).getAsJsonArray(key)
					: new JsonArray();
			for (int i = 0; i < items.size(); i++)
				if (!items.get(i).isJsonNull())
				{
					JsonObject item = items.get(i).getAsJsonObject();
					if (SetupCodec.id(item) == 0 || item.has("q") && item.get("q").isJsonNull())
					{
						remaining++;
						if (target == null)
						{
							target = item;
							targetKey = key;
							targetIndex = i;
						}
					}
				}
		}
		if (target == null)
			return;
		JTextArea guide = new CompactStatusArea(
				remaining + " slots need review. Click ? to search; right-click a slot to set its quantity.");
		guide.setName("resolutionGuide");
		builderTools.add(guide);
	}

