	private JsonElement get(String key, int index)
	{
		JsonObject s = SetupCodec.setup(draft);
		if (key.equals("afi"))
		{
			List<JsonElement> entries = new ArrayList<>();
			for (Map.Entry<String, JsonElement> e : s.getAsJsonObject(key).entrySet())
				entries.add(e.getValue());
			return index < entries.size() ? entries.get(index) : JsonNull.INSTANCE;
		}
		JsonArray a = s.has(key) && s.get(key).isJsonArray() ? s.getAsJsonArray(key) : new JsonArray();
		return index < a.size() ? a.get(index) : JsonNull.INSTANCE;
	}

	private void put(String key, int index, JsonElement value)
	{
		JsonObject s = SetupCodec.setup(draft);
		if (key.equals("afi"))
		{
			JsonObject extras = s.getAsJsonObject(key);
			List<String> keys = new ArrayList<>(extras.keySet());
			if (index < keys.size())
				extras.remove(keys.get(index));
			if (value != null && !value.isJsonNull())
				extras.add(String.valueOf(SetupCodec.id(value)), value);
		}
		else
		{
			JsonArray a = s.getAsJsonArray(key);
			while (a.size() <= index)
				a.add(JsonNull.INSTANCE);
			a.set(index, value == null ? JsonNull.INSTANCE : value);
		}
	}
	private static final String[] EQUIPMENT = {"Head", "Cape", "Neck", "Weapon", "Body", "Shield", "", "Legs", "",
			"Hands", "Feet", "", "Ring", "Ammo"};
	private JButton slot(String key, int index)
	{
		JsonElement entry = get(key, index);
		int id = SetupCodec.id(entry);
		String empty = "";
		String container = key.equals("eq")
				? EQUIPMENT[index]
				: key.equals("inv")
						? "Inventory"
						: key.equals("rp")
								? "Rune Pouch"
								: key.equals("bp")
										? "Bolt Pouch"
										: key.equals("qv") ? "Quiver" : "Additional filtered items";
		LoadoutSlotButton button = new LoadoutSlotButton(id > 0 ? String.valueOf(id) : id == 0 ? "?" : empty);
		button.addActionListener(e -> editSlot(key, index));
		button.setName("itemSlot");
		button.putClientProperty("slotContainer", key);
		button.putClientProperty("slotIndex", index);
		button.setPreferredSize(new Dimension(44, 44));
		button.setMinimumSize(new Dimension(44, 44));
		button.setBackground(SLOT);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setMargin(new Insets(1, 1, 1, 1));
		button.setForeground(GOLD);
		button.setBorder(BorderFactory.createLineBorder(slotDifferent(key + ":" + index) ? highlightColor() : BG,
				slotDifferent(key + ":" + index) ? 2 : 1));
		button.fuzzy(!entry.isJsonNull() && entry.getAsJsonObject().has("f")
				&& entry.getAsJsonObject().get("f").getAsBoolean());
		button.setRolloverEnabled(true);
		button.setContentAreaFilled(true);
		button.getModel().addChangeListener(e -> button.setBorder(BorderFactory.createLineBorder(
				slotDifferent(key + ":" + index) ? highlightColor() : button.getModel().isRollover() ? OUTLINE : BG)));
		button.getAccessibleContext()
				.setAccessibleName((container + " slot " + (index + 1)) + (id < 0 ? " - empty" : " - edit item"));
		if (id < 0)
			button.setToolTipText("Empty " + container + " slot - click to add an item");
		if (id == 0)
			button.setToolTipText((entry.getAsJsonObject().has("label")
					? entry.getAsJsonObject().get("label").getAsString()
					: "Unresolved item") + " · choose an exact Item ID");
		if (id > 0)
			host.describe(id, info ->
			{
				if (disposed)
					return;
