				button.setText(info.icon == null ? "!" : "");
				button.amount(SetupCodec.unlimited(entry)
						? "∞"
						: key.equals("rp") && SetupCodec.quantity(entry) == 0
								? "?"
								: SetupCodec.quantity(entry) > 1 || key.equals("rp")
										? compact(SetupCodec.quantity(entry))
										: "");
				button.setToolTipText(info.name + " · " + id + " · quantity "
						+ (SetupCodec.unlimited(entry)
								? "unlimited (quantity ignored)"
								: SetupCodec.quantity(entry) == 0 ? "unknown" : SetupCodec.quantity(entry)));
				if (key.equals("rp") && SetupCodec.quantity(entry) > 16000)
					button.setToolTipText(button.getToolTipText() + " - effective pouch target 16000 (capacity)");
				button.putClientProperty("baseTooltip", button.getToolTipText());
				updateDifferenceBorders(builder);
			});
		button.setTransferHandler(new TransferHandler()
		{
			@Override
			public int getSourceActions(javax.swing.JComponent c)
			{
				return MOVE;
			}

			@Override
			protected Transferable createTransferable(javax.swing.JComponent c)
			{
				String value = dragPayload(key, index);
				ItemDragImage.prepare(this, button, button.getIcon());
				return value == null ? null : new StringSelection(value);
			}

			@Override
			protected void exportDone(javax.swing.JComponent source, Transferable data, int action)
			{
				ItemDragImage.finish(this);
			}

			@Override
			public boolean canImport(TransferSupport support)
			{
				try
				{
					if (!support.isDataFlavorSupported(DataFlavor.stringFlavor))
						return false;
					return canDrop((String) support.getTransferable().getTransferData(DataFlavor.stringFlavor), key,
							index);
				}
				catch (Exception ex)
				{
					return false;
				}
			}

			@Override
			public boolean importData(TransferSupport support)
			{
				try
				{
					return support.isDataFlavorSupported(DataFlavor.stringFlavor) && importItemDrop(
							(String) support.getTransferable().getTransferData(DataFlavor.stringFlavor), key, index);
				}
				catch (Exception ex)
				{
					message("Could not read the dragged item.");
					return false;
				}
			}
		});
		java.awt.event.MouseAdapter drag = new java.awt.event.MouseAdapter()
		{
			private java.awt.Point start;
			private boolean started;
			@Override
			public void mousePressed(MouseEvent e)
			{
				start = e.getPoint();
				started = false;
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				if (!started && start != null && (e.getModifiersEx() & MouseEvent.BUTTON1_DOWN_MASK) != 0
						&& start.distance(e.getPoint()) >= 5)
				{
					started = true;
					button.getModel().setArmed(false);
					button.getTransferHandler().exportAsDrag(button, e, TransferHandler.MOVE);
				}
			}
		};
		button.addMouseListener(drag);
		button.addMouseMotionListener(drag);
		button.menuFactory = shift -> slotMenu(key, index, shift);
		button.setComponentPopupMenu(slotMenu(key, index));
		return button;
	}

	private void refreshCatalogue()
	{
		if (disposed)
			return;
		catalogueModel.clear();
		String query = catalogueQuery.getText().trim();
		if (!query.isEmpty())
			for (ItemInfo info : host.search(query))
				catalogueModel.addElement(info);
		catalogueCount
				.setText(query.isEmpty() ? "Search English item names or IDs" : catalogueModel.size() + " matches");
		catalogueCount.setToolTipText(host.catalogueStatus());
		if (!catalogueModel.isEmpty())
			catalogueList.setSelectedIndex(0);
	}

	private void addSelectedItem()
	{
		if (draft == null)
			return;
		ItemInfo item = catalogueList.getSelectedValue();
		if (item == null)
		{
			message("Choose an item in Find items first.");
			return;
		}
		int index = firstEmpty();
		if (index < 0)
		{
			message("Inventory is full. Drag an item onto a slot to replace it.");
			return;
		}
		addCatalogueItem(item.id, "inv", index);
	}

	private void addCatalogueItem(int id, String key, int index)
	{
		if (id < 1)
		{
			message("Choose a valid Item ID first.");
			return;
		}
		String token = session;
		JsonElement before = get(key, index).deepCopy();
		host.describe(id, info ->
		{
			if (disposed || !token.equals(session))
				return;
			if (!before.equals(get(key, index)))
			{
				message("This slot changed. Choose the destination again.");
				return;
			}
			attempt(() ->
			{
				itemCache.put(id, info);
				JsonObject item = SetupCodec.item(id, 1);
				slotRules(item, before);
				validateSlot(key, index, item);
				checkExtraDuplicate(key, index, item);
				fieldsToDraft();
				put(key, index, item);
				rebuildDraftLayout();
				markDirty();
				renderBuilder();
				message("Added " + info.name + ". Review its quantity if needed.");
			});
		});
	}

	private void slotRules(JsonObject item, JsonElement before)
	{
		if (before.isJsonNull())
			LoadoutDefaults.newItem(item, host.settings());
		else
			for (String field : new String[]{"f", "sc"})
				if (before.getAsJsonObject().has(field))
					item.add(field, before.getAsJsonObject().get(field).deepCopy());
	}

	private boolean validSlot(String key, int index)
	{
		if (draft == null || index < 0)
			return false;
		if (key.equals("afi"))
			return index < Math.max(4, ((SetupCodec.setup(draft).getAsJsonObject("afi").size() + 3) / 4) * 4);
		int length = key.equals("eq")
				? 14
				: key.equals("inv") ? 28 : (key.equals("rp") || key.equals("bp")) ? 4 : key.equals("qv") ? 1 : 0;
		return index < length && !(key.equals("eq") && (index == 6 || index == 8 || index == 11));
	}

	String catalogueDragPayload()
	{
		ItemInfo item = catalogueList.getSelectedValue();
		return item == null ? null : "loadout-item:" + session + ":" + item.id;
	}

	String dragPayload(String key, int index)
	{
		return validSlot(key, index) && !get(key, index).isJsonNull()
				? "loadout-slot:" + session + ":" + key + ":" + index
				: null;
	}

	private JsonElement dropItem(String key, JsonElement item)
	{
		return item.deepCopy();
	}

	private boolean canDrop(String value, String key, int index)
	{
		if (disposed || !validSlot(key, index) || value == null)
			return false;
		String[] parts = value.split(":");
		if (parts.length < 3 || !parts[1].equals(session))
			return false;
		if (parts[0].equals("loadout-item") && parts.length == 3)
		{
			int id = Integer.parseInt(parts[2]);
			for (int i = 0; i < catalogueModel.size(); i++)
				if (catalogueModel.get(i).id == id)
					return true;
			return false;
		}
		if (!parts[0].equals("loadout-slot") || parts.length != 4 || !validSlot(parts[2], Integer.parseInt(parts[3])))
			return false;
		JsonElement item = get(parts[2], Integer.parseInt(parts[3]));
		if (item.isJsonNull())
			return false;
		validateSlot(key, index, dropItem(key, item));
		validateSlot(parts[2], Integer.parseInt(parts[3]), get(key, index));
		return true;
	}

	private void checkExtraDuplicate(String key, int index, JsonElement item)
	{
		if (key.equals("afi") && !item.isJsonNull() && SetupCodec.id(item) != SetupCodec.id(get(key, index))
				&& SetupCodec.setup(draft).getAsJsonObject("afi").has(String.valueOf(SetupCodec.id(item))))
			throw new IllegalArgumentException("This item is already in Additional filtered items.");
	}

	boolean importItemDrop(String value, String key, int index)
	{
		try
		{
			if (!canDrop(value, key, index))
				return false;
			String[] parts = value.split(":");
			if (parts[0].equals("loadout-item"))
			{
				addCatalogueItem(Integer.parseInt(parts[2]), key, index);
				return true;
			}
			String from = parts[2];
			int old = Integer.parseInt(parts[3]);
			if (from.equals(key) && old == index)
				return false;
			JsonElement a = dropItem(key, get(from, old)), b = get(key, index).deepCopy();
			// Setup planning: preserve the planned amount without creating
			// a remainder slot. A different displaced rune still swaps back.
			if (from.equals("inv") && key.equals("rp") && SetupCodec.quantity(get(from, old)) > 16000
					&& SetupCodec.id(b) == SetupCodec.id(a))
				b = JsonNull.INSTANCE;
			if (from.equals("afi") && key.equals("afi"))
			{
				List<JsonElement> items = new ArrayList<>();
				for (Map.Entry<String, JsonElement> entry : SetupCodec.setup(draft).getAsJsonObject("afi").entrySet())
					items.add(entry.getValue());
				while (items.size() <= Math.max(old, index))
					items.add(JsonNull.INSTANCE);
				items.set(old, b);
				items.set(index, a);
				JsonObject extras = new JsonObject();
				for (JsonElement item : items)
					if (!item.isJsonNull())
						extras.add(String.valueOf(SetupCodec.id(item)), item);
				SetupCodec.setup(draft).add("afi", extras);
			}
			else
			{
				checkExtraDuplicate(key, index, a);
				checkExtraDuplicate(from, old, b);
				fieldsToDraft();
				put(from, old, b);
				put(key, index, a);
			}
			rebuildDraftLayout();
			markDirty();
			renderBuilder();
			scheduleAlternatives();
			diagnostics.completed(StudioDiagnostics.Operation.ITEM_EDIT, StudioDiagnostics.Outcome.SUCCESS, 0);
			message("Moved item. Changes are saved automatically.");
			return true;
		}
		catch (RuntimeException ex)
		{
			diagnostics.failure(StudioDiagnostics.Operation.ITEM_EDIT, ex, 0);
			failure(failureMessage(ex));
			return false;
		}
	}

	private static String compact(int q)
	{
		return q >= 1000 && q % 1000 == 0 ? q / 1000 + "k" : String.valueOf(q);
	}

	private void validateSlot(String key, int index, JsonElement e)
	{
		if (e == null || e.isJsonNull())
			return;
		ItemInfo info = itemCache.get(SetupCodec.id(e));
		if (!key.equals("inv") && info == null)
			throw new IllegalArgumentException("Item details are still loading. Choose an exact Item ID or try again.");
		if (key.equals("rp"))
		{
			if (info != null && !info.name.toLowerCase(java.util.Locale.ROOT).endsWith(" rune"))
				throw new IllegalArgumentException("Rune pouch accepts runes only.");
		}
		if (key.equals("bp") && info != null && !info.name.toLowerCase(java.util.Locale.ROOT).contains("bolt")
				&& !info.name.equalsIgnoreCase("Bolt rack"))
			throw new IllegalArgumentException("Bolt pouch accepts bolts only.");
		if (key.equals("qv") && info != null
				&& !info.name.toLowerCase(java.util.Locale.ROOT).matches(".*(arrow|bolt)s?(?: \\(.*\\))?$"))
			throw new IllegalArgumentException("Quiver accepts arrows or bolts.");
		if (key.equals("eq") && info != null && info.slot != index)
			throw new IllegalArgumentException("This item belongs in a different Equipment slot.");
	}

