		javax.swing.JMenuItem search = new javax.swing.JMenuItem("Update Slot from Search");
		search.addActionListener(e -> editSlot(key, index));
		menu.add(search);
		if (!key.equals("afi"))
		{
			javax.swing.JMenuItem capture = new javax.swing.JMenuItem("Update Slot from " + (key.equals("eq")
					? "Equipment"
					: key.equals("inv")
							? "Inventory"
							: key.equals("rp") ? "Rune Pouch" : key.equals("bp") ? "Bolt Pouch" : "Quiver"));
			capture.addActionListener(e -> updateSlotFromContainer(key, index));
			menu.add(capture);
		}
		javax.swing.JMenuItem quantity = new javax.swing.JMenuItem("Set quantity");
		quantity.setEnabled(!current.isJsonNull() && SetupCodec.id(current) > 0);
		quantity.addActionListener(e -> editQuantity(key, index));
		menu.add(quantity);
		javax.swing.JMenuItem fuzzy = new javax.swing.JMenuItem("Toggle Fuzzy");
		fuzzy.setEnabled(!current.isJsonNull());
		fuzzy.addActionListener(e -> attempt(() ->
		{
			JsonObject item = get(key, index).getAsJsonObject();
			item.addProperty("f", !item.has("f") || !item.get("f").getAsBoolean());
			changedSlot();
		}));
		menu.add(fuzzy);
		javax.swing.JMenu stack = new javax.swing.JMenu("Stack comparison");
		stack.setEnabled(!current.isJsonNull() && !SetupCodec.unlimited(current));
		for (LoadoutStudioConfig.StackRule rule : LoadoutStudioConfig.StackRule.values())
		{
			String value = rule.code;
			javax.swing.JMenuItem option = new javax.swing.JMenuItem(rule.label);
			option.addActionListener(e -> attempt(() ->
			{
				get(key, index).getAsJsonObject().addProperty("sc", value);
				changedSlot();
			}));
			stack.add(option);
		}
		menu.add(stack);
		javax.swing.JMenuItem remove = new javax.swing.JMenuItem("Remove Item from Slot");
		remove.setEnabled(!current.isJsonNull());
		remove.addActionListener(e ->
