	private void bulkFromSearch(String key, int index)
	{
		if (dirty)
			throw new IllegalStateException("Save this setup before updating all saved setups.");
		int old = SetupCodec.id(get(key, index));
		String token = session;
		host.chooseItem(id ->
		{
			if (!disposed && token.equals(session))
				host.describe(id, replacement -> host.describe(old, original ->
				{
					if (!disposed && token.equals(session))
						attempt(() -> confirmBulkUpdate(original, replacement));
				}));
		}, this::failure);
	}

	private void bulkFromContainer(String key, int index)
	{
		if (dirty)
			throw new IllegalStateException("Save this setup before updating all saved setups.");
		int old = SetupCodec.id(get(key, index));
		String token = session;
		host.capture(actual ->
		{
			if (disposed || !token.equals(session))
				return;
			String source = key.equals("eq") ? "eq" : "inv";
			JsonArray slots = SetupCodec.setup(actual).getAsJsonArray(source);
			int id = index < slots.size() ? SetupCodec.id(slots.get(index)) : -1;
			if (id < 1)
			{
				failure("That live slot is empty. Choose Update ALL slots from Search instead.");
				return;
			}
			host.describe(id, replacement -> host.describe(old, original ->
			{
				if (!disposed && token.equals(session))
					attempt(() -> confirmBulkUpdate(original, replacement));
			}));
		}, this::failure);
	}

	Set<String> bulkTargets(int id)
	{
		Set<String> targets = new HashSet<>();
		for (SetupLibrary.Entry entry : library.setups)
			if (BankLayouts.items(entry.portable).stream().anyMatch(item -> SetupCodec.id(item) == id))
				targets.add(entry.id);
		return targets;
	}

	private void confirmBulkUpdate(ItemInfo original, ItemInfo replacement)
	{
		Set<String> targets = bulkTargets(original.id);
		if (targets.isEmpty())
			return;
		String owner = recoveryOwner, token = session;
		if (JOptionPane.showConfirmDialog(this, "Replace " + original.name + " with " + replacement.name + " in ALL "
				+ targets.size()
				+ " matching saved setups, including archived setups? Amounts and matching rules are retained. Undo is in Library tools.",
				"Update all matching slots", JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION)
			return;
		if (owner.equals(recoveryOwner) && token.equals(session))
			replaceLibraryItems(original, replacement, targets);
	}

	private void changedSlot()
	{
		fieldsToDraft();
		rebuildDraftLayout();
		markDirty();
		renderBuilder();
		scheduleAlternatives();
	}

	private void editSlot(String key, int index)
	{
		if (draft == null)
			return;
		fieldsToDraft();
		String token = session;
		JsonElement before = get(key, index).deepCopy();
		message("Choose an item in the RuneLite chatbox.");
		host.chooseItem(id ->
		{
			if (disposed || !token.equals(session) || id < 1 || !before.equals(get(key, index)))
				return;
			host.describe(id, info ->
			{
				if (disposed || !token.equals(session) || !before.equals(get(key, index)))
					return;
				itemCache.put(id, info);
				if (info.stackable || key.equals("rp") || key.equals("qv"))
					host.enterQuantity(host.settings().emptyQuantityInput() ? "" : amountText(before), value ->
					{
						if (token.equals(session) && before.equals(get(key, index)))
							applySlotItem(key, index, id, value, true);
					}, this::failure);
				else
					applySlotItem(key, index, id, "1", false);
			});
		}, this::failure);
	}

	private static String amountText(JsonElement item)
	{
		return item.isJsonNull()
				? "1"
				: item.getAsJsonObject().has("q") && item.getAsJsonObject().get("q").isJsonNull()
						? ""
						: String.valueOf(SetupCodec.quantity(item));
	}

	private void editQuantity(String key, int index)
	{
		JsonElement before = get(key, index).deepCopy();
		String token = session;
		if (before.isJsonNull())
			return;
		host.enterQuantity(host.settings().emptyQuantityInput() ? "" : amountText(before), value ->
		{
			if (!disposed && token.equals(session) && before.equals(get(key, index)))
				applySlotItem(key, index, SetupCodec.id(before), value, true);
		}, this::failure);
	}

	private void applySlotItem(String key, int index, int id, String amount, boolean amountEntered)
	{
		attempt(() ->
		{
			int quantity = amount.trim().equals("0") ? 0 : SetupCodec.parseQuantity(amount);
			ItemInfo info = itemCache.get(id);
			if (info == null)
				throw new IllegalArgumentException("Item details are still loading.");
			if (!info.stackable && quantity > 1)
				throw new IllegalArgumentException("Non-stackable items need separate slots.");
			JsonElement previous = get(key, index);
			JsonObject item = SetupCodec.item(id, quantity);
			slotRules(item, previous);
			if (quantity == 0)
				item.addProperty("sc", "None");
			else if (amountEntered && (!item.has("sc") || item.get("sc").getAsString().equals("None")))
				item.addProperty("sc", "Standard");
			validateSlot(key, index, item);
			checkExtraDuplicate(key, index, item);
			put(key, index, item);
			changedSlot();
			message(quantity == 0 ? "Unlimited: quantity matching is disabled for this slot." : "Slot updated.");
		});
	}

	private void updateSlotFromContainer(String key, int index)
	{
		String token = session;
		JsonElement before = get(key, index).deepCopy();
		host.capture(actual ->
		{
			if (disposed || !token.equals(session) || !before.equals(get(key, index)))
				return;
			JsonElement item = SetupCodec.setup(actual).getAsJsonArray(key).get(index).deepCopy();
			if (item.isJsonNull())
			{
				put(key, index, JsonNull.INSTANCE);
				changedSlot();
				return;
			}
			host.describe(SetupCodec.id(item), info ->
			{
				if (disposed || !token.equals(session) || !before.equals(get(key, index)))
					return;
				itemCache.put(info.id, info);
				attempt(() ->
				{
					slotRules(item.getAsJsonObject(), before);
					validateSlot(key, index, item);
					put(key, index, item);
					changedSlot();
				});
			});
		}, this::failure);
	}

	private void saveDraft(boolean copy)
	{
		autoSaveTimer.stop();
		if (draft == null)
			return;
		if (copy && dirty && editingId != null && !autoSaveNow())
			return;
		attempt(StudioDiagnostics.Operation.SAVE, () ->
		{
			fieldsToDraft();
			SetupCodec.validate(draft, false);
			String chosenSection = sectionIds.get(Math.max(0, section.getSelectedIndex()));
			boolean chosenFavorite = favorite.isSelected();
			String id = copy || editingId == null ? UUID.randomUUID().toString() : editingId;
			commit(l ->
			{
				SetupLibrary.Entry record = l.find(id);
				if (record == null)
				{
					record = new SetupLibrary.Entry(draft);
					record.id = id;
				}
				record.portable = draft.deepCopy();
				if (copy || editingId == null)
					SetupCodec.setup(record.portable).addProperty("name", l.uniqueName(SetupCodec.name(draft)));
				record.section = chosenSection;
				record.favorite = chosenFavorite;
				record.bankLayout = editorLayout;
				record.zigzagBottomToTop = editorBottom;
				record.lastOpened = System.currentTimeMillis();
				if (l.find(id) == null)
					l.setups.add(record);
			});
			String storedName = SetupCodec.name(library.find(id).portable);
			SetupCodec.setup(draft).addProperty("name", storedName);
			boolean beforeRendering = rendering;
			rendering = true;
			setupName.setText(storedName);
			rendering = beforeRendering;
			editingId = id;
			dirty = false;
			clearRecovery();
			draftLabel.setText("Saved setup");
			setupName.setToolTipText(setupName.getText() + " - Saved setup");
			message("Saved to this character/profile library.");
		});
	}

	private void compareGear()
	{
		if (draft == null)
			return;
		fieldsToDraft();
		host.requestGear();
		String token = session;
		long revision = draftRevision;
		host.compareSetup(draft.deepCopy(), ignoreAmmo.isSelected(), result ->
		{
			if (disposed || !token.equals(session) || revision != draftRevision)
				return;
			differences.clear();
			differences.addAll(result);
			updateDifferenceBorders(builder);
			updateGearReadiness(result);
			message(result.size()
					+ " difference(s). Fuzzy variants, Stack comparison, unordered Inventory and Ammo preferences are applied.");
		}, this::failure);
	}

	void acceptLiveGear(JsonObject actual)
	{
		if (disposed)
			return;
		liveActual = actual == null ? null : actual.deepCopy();
		refreshGearComparison();
		scheduleAlternatives();
	}

	private void refreshGearComparison()
	{
		if (draft == null || liveActual == null)
		{
			gearReadiness.setText("Live check: log in");
			gearReadiness.setToolTipText("Current gear is unknown until logged in.");
			if (liveActual == null)
			{
				differences.clear();
				updateDifferenceBorders(builder);
			}
			return;
		}
		Set<String> next = SetupComparison.differences(draft, liveActual, ignoreAmmo.isSelected(),
				SetupVariationMapping::map);
		differences.clear();
		differences.addAll(next);
		updateGearReadiness(next);
		updateDifferenceBorders(builder);
		spellbook.setBorder(highlighting() && next.contains("spellbook")
				? BorderFactory.createLineBorder(highlightColor(), 2)
				: javax.swing.UIManager.getBorder("ComboBox.border"));
	}

	private void updateGearReadiness(Set<String> result)
	{
		gearReadiness.setText(result.isEmpty() ? "Gear matches setup" : result.size() + " gear difference(s)");
		if (result.isEmpty())
		{
			gearReadiness.setToolTipText("Compared with your current local gear.");
			return;
		}
		Map<String, Integer> counts = new java.util.LinkedHashMap<>();
		for (String key : result)
		{
			String group = key.startsWith("eq:")
					? "Equipment"
					: key.startsWith("inv:")
							? "Inventory"
							: key.startsWith("rp:")
									? "Rune Pouch"
									: key.startsWith("qv:")
											? "Quiver"
											: key.startsWith("bp:")
													? "Bolt Pouch"
													: key.equals("spellbook")
															? "Spellbook"
															: key.equals("attackOption") ? "Attack option" : "Other";
			counts.merge(group, 1, Integer::sum);
		}
		StringBuilder tip = new StringBuilder("<html><body style='width:180px'><b>Gear differences</b><br>");
		counts.forEach((name, count) -> tip.append(name).append(": ").append(count).append("<br>"));
		tip.append("<br>Hover a highlighted slot for its details.</body></html>");
		gearReadiness.setToolTipText(tip.toString());
	}

	private void updateDifferenceBorders(Container root)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof JButton && "itemSlot".equals(child.getName()))
			{
				JButton slot = (JButton) child;
				String key = slot.getClientProperty("slotContainer") + ":" + slot.getClientProperty("slotIndex");
				slot.setBorder(BorderFactory.createLineBorder(slotDifferent(key) ? highlightColor() : BG,
						slotDifferent(key) ? 2 : 1));
				slot.getAccessibleContext()
						.setAccessibleDescription(slotDifferent(key) ? differenceReason(key) : "Matches current gear");
				String base = (String) slot.getClientProperty("baseTooltip");
				if (base != null)
					slot.setToolTipText(base + (slotDifferent(key) ? " · " + differenceReason(key) : ""));
			}
			if (child instanceof Container)
				updateDifferenceBorders((Container) child);
		}
	}

	private boolean slotDifferent(String key)
	{
		return highlighting()
				&& (differences.contains(key) || key.equals("eq:3") && differences.contains("attackOption"));
	}

	private String differenceReason(String key)
	{
		if (key.equals("eq:3") && !differences.contains(key) && differences.contains("attackOption"))
			return "Wrong attack option";
		if (key.equals("spellbook"))
			return "Wrong Spellbook";
		if (key.equals("attackOption"))
			return "Wrong attack option";
		String[] parts = key.split(":");
		if (parts.length != 2 || draft == null || liveActual == null)
			return key;
		String container = parts[0];
		int index = Integer.parseInt(parts[1]);
		JsonElement expected = get(container, index);
		JsonObject actual = SetupCodec.setup(liveActual);
		JsonArray items = actual.has(container) && actual.get(container).isJsonArray()
				? actual.getAsJsonArray(container)
				: new JsonArray();
		JsonElement present = index < items.size() ? items.get(index) : JsonNull.INSTANCE;
		String name = container.equals("eq")
				? EQUIPMENT[index]
				: container.toUpperCase(java.util.Locale.ROOT) + " " + (index + 1);
		if (SetupCodec.id(expected) == 0)
			return name + ": unresolved item";
		if (expected.isJsonObject() && expected.getAsJsonObject().has("q")
				&& expected.getAsJsonObject().get("q").isJsonNull())
			return name + ": quantity unknown";
		if (container.equals("inv") && SetupCodec.setup(draft).has("uh")
				&& SetupCodec.setup(draft).get("uh").getAsBoolean())
			return name + ": required item or amount missing";
		if (SetupCodec.id(present) < 1)
			return name + ": missing item";
		if (SetupCodec.id(expected) < 1)
			return name + ": extra item";
		if (SetupCodec.id(expected) != SetupCodec.id(present) && !(expected.getAsJsonObject().has("f")
				&& expected.getAsJsonObject().get("f").getAsBoolean() && SetupVariationMapping
						.fuzzy(SetupCodec.id(expected)) == SetupVariationMapping.fuzzy(SetupCodec.id(present))))
			return name + ": different item or slot";
		return name + ": quantity differs";
	}

	private void scheduleAlternatives()
	{
		if (alternativeUndo != null && draftRevision != alternativeUndoRevision)
			alternativeUndo = null;
		if (!disposed && draft != null && host.settings().autoAlternatives() && alternativeUndo == null)
			alternativeTimer.restart();
	}

	private void refreshAutomaticAlternatives()
	{
		if (!disposed && host.settings().autoAlternatives())
			refreshAlternatives();
	}

	private void refreshAlternativeRows()
	{
		themeForm(alternativeRows);
		for (Container parent = alternativeRows; parent != null; parent = parent.getParent())
		{
			parent.invalidate();
			if (parent == this)
				break;
		}
		builder.revalidate();
		builder.repaint();
	}

	private void showAlternativesOnce(boolean available)
	{
		if (!available)
		{
			autoShownAlternativeSession = null;
			expandedPanels.remove("My gear alternatives");
			if (alternativesContent != null)
			{
				alternativesContent.setVisible(false);
				Container parent = alternativesContent.getParent();
				if (parent != null)
					for (Component child : parent.getComponents())
						if (child instanceof JButton && "disclosure:My gear alternatives".equals(child.getName()))
							((JButton) child).setText("+ My gear alternatives");
			}
			return;
		}
		if (session.equals(autoShownAlternativeSession) || !host.settings().autoShowAlternatives())
			return;
		autoShownAlternativeSession = session;
		expandedPanels.add("My gear alternatives");
		if (alternativesContent != null)
		{
			alternativesContent.setVisible(true);
			Container parent = alternativesContent.getParent();
			if (parent != null)
				for (Component child : parent.getComponents())
					if (child instanceof JButton && "disclosure:My gear alternatives".equals(child.getName()))
						((JButton) child).setText("- My gear alternatives");
		}
	}

	void refreshAlternatives()
	{
		if (draft == null)
			return;
		long alternativesStarted = System.nanoTime();
		fieldsToDraft();
		String token = session;
		long revision = draftRevision, request = ++alternativeRequestVersion;
		alternativeRows.removeAll();
		if (BankLayouts.items(draft).isEmpty())
			return;
		alternativeRows.add(info("Checking local gear...", 1));
		host.availableGear(draft.deepCopy(), owned ->
		{
			if (disposed || !token.equals(session) || revision != draftRevision || request != alternativeRequestVersion)
				return;
			diagnostics.completed(StudioDiagnostics.Operation.ALTERNATIVES,
					owned.observedAt == 0
							? StudioDiagnostics.Outcome.EXPECTED_STATE
							: StudioDiagnostics.Outcome.SUCCESS,
					alternativesStarted);
			alternativeRows.removeAll();
			if (owned.observedAt == 0)
			{
				alternativeRows.add(info("Open your Bank to see owned alternatives.", 2));
				refreshAlternativeRows();
				return;
			}
			if (preferDivinePouch(owned))
			{
				refreshAlternatives();
				return;
			}
			String date = java.time.Instant.ofEpochMilli(owned.observedAt).atZone(java.time.ZoneId.systemDefault())
					.format(java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss"));
			alternativeRows.add(info((owned.bankOpen
					? "Bank observed now; available potion storage included"
					: "Last Bank observation " + date)
					+ ". Other storage is not included. Review requirements before replacing.", 4));
			List<OwnedGear.Proposal> proposals = owned.alternatives(draft, host::defaultItem);
			Map<OwnedGear.Proposal, JComboBox<ItemInfo>> choices = new java.util.LinkedHashMap<>();
			for (List<OwnedGear.Proposal> group : OwnedGear.grouped(proposals))
			{
				OwnedGear.Proposal proposal = group.get(0);
				int id = SetupCodec.id(proposal.before);
				ItemInfo original = owned.items.get(id);
				String missingName = proposal.before.getAsJsonObject().has("label")
						? proposal.before.getAsJsonObject().get("label").getAsString()
						: original == null
								? itemCache.containsKey(id) ? itemCache.get(id).name : "Item " + id
								: original.name;
				JLabel missing = text((proposal.container.equals("eq")
						? EQUIPMENT[proposal.index]
						: "Inventory " + (proposal.index + 1)) + ": " + missingName);
				missing.setMinimumSize(new Dimension(0, 18));
				missing.setToolTipText(missing.getText() + " · " + proposal.reason);
				alternativeRows.add(missing);
				if (group.size() > 1)
				{
					missing.setText("Inventory ×" + group.size() + ": " + missingName);
					missing.setToolTipText(
							"Replaces all " + group.size() + " matching Inventory slots · " + proposal.reason);
				}
				JComboBox<ItemInfo> select = new JComboBox<>();
				select.setName("ownedChoice:" + proposal.container + ":" + proposal.index);
				select.addItem(new ItemInfo(-1, "Keep original", false, -1, null));
				for (ItemInfo item : proposal.choices.subList(0,
						Math.min(Math.max(1, Math.min(5, host.settings().maxAlternatives())), proposal.choices.size())))
				{
					select.addItem(item);
					itemCache.put(item.id, item);
				}
				select.setRenderer(new javax.swing.DefaultListCellRenderer()
				{
					@Override
					public Component getListCellRendererComponent(JList<?> list, Object value, int index,
							boolean selected, boolean focused)
					{
						JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, selected,
								focused);
						label.putClientProperty("html.disable", true);
						label.setFont(BODY_FONT);
						label.setBackground(selected ? StudioTheme.SELECTED : CONTROL);
						label.setForeground(selected ? GOLD : TEXT);
						label.setText(value == null || ((ItemInfo) value).id < 1
								? "Keep original"
								: ((ItemInfo) value).name + " (" + owned.count(((ItemInfo) value).id) + " seen)");
						return label;
					}
				});
				select.putClientProperty("preserveRenderer", true);
				select.setToolTipText(proposal.reason);
				alternativeRows.add(select);
				for (OwnedGear.Proposal member : group)
					choices.put(member, select);
			}
			if (proposals.isEmpty())
				alternativeRows.add(
						info("No supported owned alternatives found. Missing gear is not automatically replaced.", 3));
			else
				alternativeRows.add(button("Use selected alternatives", () -> attempt(() ->
				{
					if (!token.equals(session))
						throw new IllegalStateException("Another setup is open. Check its Bank alternatives.");
					Map<OwnedGear.Proposal, ItemInfo> selected = new java.util.LinkedHashMap<>();
					choices.forEach((proposal, select) ->
					{
						ItemInfo item = (ItemInfo) select.getSelectedItem();
						if (item != null && item.id > 0)
							selected.put(proposal, item);
					});
					host.availableGear(draft.deepCopy(), fresh ->
					{
						if (disposed || !token.equals(session))
							return;
						attempt(() ->
						{
							for (ItemInfo item : selected.values())
								if (fresh.count(item.id) < 1)
									throw new IllegalStateException(
											"An alternative is no longer observed. Check your Bank again.");
							if (host.settings().checkAlternativeStock())
								fresh.requireReplacementStock(draft, selected);
							applyAlternatives(selected);
						});
					}, this::failure);
				})));
			showAlternativesOnce(!proposals.isEmpty());
			refreshAlternativeRows();
		}, error ->
		{
			if (!disposed && token.equals(session) && request == alternativeRequestVersion)
			{
				alternativeRows.removeAll();
				alternativeRows.add(info(error, 2));
				refreshAlternativeRows();
			}
		});
	}

	private boolean preferDivinePouch(OwnedGear owned)
	{
		int divine = owned.amounts.keySet().stream()
				.filter(id -> EquipmentVariants.divinePouch(id) && owned.count(id) > 0).sorted().findFirst().orElse(-1);
		if (divine < 1)
			return false;
		JsonArray inventory = SetupCodec.setup(draft).getAsJsonArray("inv");
		for (JsonElement item : inventory)
			if (EquipmentVariants.divinePouch(SetupCodec.id(item)))
				return false;
		for (int i = 0; i < inventory.size(); i++)
			if (EquipmentVariants.runePouch(SetupCodec.id(inventory.get(i))))
			{
				int normal = SetupCodec.id(inventory.get(i));
				JsonObject replacement = inventory.get(i).getAsJsonObject().deepCopy();
				replacement.addProperty("id", divine);
				replacement.addProperty("label",
						owned.items.containsKey(divine) ? owned.items.get(divine).name : "Divine rune pouch");
				inventory.set(i, replacement);
				if (owned.items.containsKey(divine))
					itemCache.put(divine, owned.items.get(divine));
				if (editorLayout == BankLayouts.Mode.CUSTOM
						&& BankLayouts.items(draft).stream().noneMatch(item -> SetupCodec.id(item) == normal))
					for (int pos = 0; pos < draft.getAsJsonArray("layout").size(); pos++)
						if (draft.getAsJsonArray("layout").get(pos).getAsInt() == normal)
							draft.getAsJsonArray("layout").set(pos, new com.google.gson.JsonPrimitive(divine));
				rebuildDraftLayout();
				markDirty();
				renderBuilder();
				syncBankFilter();
				message("Using your owned Divine rune pouch. Rune contents are retained; the fourth slot is available.");
				return true;
			}
		return false;
	}

	void applyAlternatives(Map<OwnedGear.Proposal, ItemInfo> selected)
	{
		if (draft == null || selected.isEmpty())
		{
			message("Choose at least one alternative.");
			return;
		}
		JsonObject next = draft.deepCopy();
		for (Map.Entry<OwnedGear.Proposal, ItemInfo> e : selected.entrySet())
		{
			OwnedGear.Proposal proposal = e.getKey();
			ItemInfo item = e.getValue();
			if (!proposal.before.equals(get(proposal.container, proposal.index))
					|| proposal.choices.stream().noneMatch(choice -> choice.id == item.id))
				throw new IllegalStateException("Alternative no longer matches this slot. Check again.");
			itemCache.put(item.id, item);
			JsonObject replacement = proposal.before.getAsJsonObject().deepCopy();
			replacement.addProperty("id", item.id);
			replacement.addProperty("label", item.name);
			validateSlot(proposal.container, proposal.index, replacement);
			SetupCodec.setup(next).getAsJsonArray(proposal.container).set(proposal.index, replacement);
			if (!item.stackable && SetupCodec.quantity(replacement) > 1)
				throw new IllegalArgumentException("Adjust the quantity before choosing a non-stackable replacement.");
		}
		if (editorLayout == BankLayouts.Mode.CUSTOM)
			for (Map.Entry<OwnedGear.Proposal, ItemInfo> e : selected.entrySet())
			{
				int oldId = SetupCodec.id(e.getKey().before), newId = e.getValue().id;
				if (BankLayouts.items(next).stream().noneMatch(item -> SetupCodec.id(item) == oldId))
					for (int i = 0; i < next.getAsJsonArray("layout").size(); i++)
						if (next.getAsJsonArray("layout").get(i).getAsInt() == oldId)
							next.getAsJsonArray("layout").set(i, new com.google.gson.JsonPrimitive(newId));
			}
		next.add("layout", BankLayouts.generate(next, editorLayout, editorBottom));
		SetupCodec.validate(next, false);
		alternativeUndo = draft.deepCopy();
		draft = next;
		markDirty();
		alternativeUndoRevision = draftRevision;
		alternativeRows.removeAll();
		alternativeRows.add(
				info("Alternatives applied to this draft. Changes are saved automatically. Undo is available.", 3));
		alternativeRows.add(button("Undo alternatives", () -> attempt(this::undoAlternatives)));
		syncBankFilter();
		renderBuilder();
	}

	void undoAlternatives()
	{
		if (alternativeUndo == null || draftRevision != alternativeUndoRevision)
			throw new IllegalStateException("The draft changed after replacement. Undo is no longer available.");
		draft = alternativeUndo;
		alternativeUndo = null;
		alternativeRows.removeAll();
		markDirty();
		syncBankFilter();
		renderBuilder();
	}

	String libraryDragPayload(String id)
	{
		if (library.find(id) == null)
			return null;
		JsonObject data = new JsonObject();
		data.addProperty("owner", recoveryOwner);
		data.addProperty("id", id);
		return "studio-library:" + gson.toJson(data);
	}

	private String libraryDraggedId(String payload, String target)
	{
		if (disposed || payload == null || !payload.startsWith("studio-library:")
				|| !Objects.equals(recoveryOwner, host.recoveryOwner()))
			return null;
		if (target != null && library.sections.stream().noneMatch(group -> group.id.equals(target)))
			return null;
		try
		{
			JsonObject data = gson.fromJson(payload.substring(15), JsonObject.class);
			if (!Objects.equals(recoveryOwner, data.get("owner").getAsString()))
				return null;
			String id = data.get("id").getAsString();
			return library.find(id) == null ? null : id;
		}
		catch (RuntimeException error)
		{
			return null;
		}
	}

	boolean moveLibraryDrop(String payload, String target)
	{
		String id = libraryDraggedId(payload, target);
		if (id == null)
			return false;
		if (!autoSaveNow())
			return false;
		commit(next -> next.find(id).section = target);
		if (id.equals(editingId))
		{
			editorSection = target;
			renderBuilder();
		}
		message("Setup moved to section. Changes are saved automatically.");
		return true;
	}

	private void installLibraryTarget(javax.swing.JComponent component, String target)
	{
		component.setTransferHandler(new TransferHandler()
		{
			@Override
			public boolean canImport(TransferSupport support)
			{
				try
				{
					return support.isDataFlavorSupported(DataFlavor.stringFlavor) && libraryDraggedId(
							(String) support.getTransferable().getTransferData(DataFlavor.stringFlavor),
							target) != null;
				}
				catch (Exception error)
				{
					return false;
				}
			}

			@Override
			public boolean importData(TransferSupport support)
			{
				try
				{
					return canImport(support) && moveLibraryDrop(
							(String) support.getTransferable().getTransferData(DataFlavor.stringFlavor), target);
				}
				catch (Exception error)
				{
					failure("Could not move setup to section.");
					return false;
				}
			}
		});
	}

	private void installLibrarySource(JButton button, String id, String target)
	{
		button.setTransferHandler(new TransferHandler()
		{
			@Override
			public boolean canImport(TransferSupport support)
			{
				try
				{
					return support.isDataFlavorSupported(DataFlavor.stringFlavor) && libraryDraggedId(
							(String) support.getTransferable().getTransferData(DataFlavor.stringFlavor),
							target) != null;
				}
				catch (Exception error)
				{
					return false;
				}
			}

			@Override
			public boolean importData(TransferSupport support)
			{
				try
				{
					return canImport(support) && moveLibraryDrop(
							(String) support.getTransferable().getTransferData(DataFlavor.stringFlavor), target);
				}
				catch (Exception error)
				{
					failure("Could not move setup to section.");
					return false;
				}
			}

			@Override
			public int getSourceActions(javax.swing.JComponent source)
			{
				return MOVE;
			}

			@Override
			protected Transferable createTransferable(javax.swing.JComponent source)
			{
				String payload = libraryDragPayload(id);
				return payload == null ? null : new StringSelection(payload);
			}
		});
		java.awt.event.MouseAdapter drag = new java.awt.event.MouseAdapter()
		{
			private java.awt.Point start;
			private boolean started;
			@Override
			public void mousePressed(MouseEvent event)
			{
				start = event.getPoint();
				started = false;
			}

			@Override
			public void mouseDragged(MouseEvent event)
			{
				if (!started && start != null && (event.getModifiersEx() & MouseEvent.BUTTON1_DOWN_MASK) != 0
						&& start.distance(event.getPoint()) >= 5)
				{
					started = true;
					button.getModel().setArmed(false);
					button.getModel().setPressed(false);
					button.getTransferHandler().exportAsDrag(button, event, TransferHandler.MOVE);
				}
			}
		};
		button.addMouseListener(drag);
		button.addMouseMotionListener(drag);
	}

	void moveSetup(String id, int direction)
	{
		SetupLibrary.Entry entry = library.find(id);
		if (entry == null)
			return;
		List<String> peers = new ArrayList<>();
		for (SetupLibrary.Entry candidate : library.setups)
			if (Objects.equals(candidate.section, entry.section) && candidate.archived == entry.archived)
				peers.add(candidate.id);
		int from = peers.indexOf(id), to = from + direction;
		if (to < 0 || to >= peers.size())
			return;
		String other = peers.get(to);
		commit(next -> java.util.Collections.swap(next.setups, next.setups.indexOf(next.find(id)),
				next.setups.indexOf(next.find(other))));
		libraryOrder = LoadoutStudioConfig.LibraryOrder.MANUAL;
		host.libraryOrder(libraryOrder);
		renderLibrary();
	}

	private void shareSetups()
	{
		String owner = recoveryOwner;
		List<SetupLibrary.Entry> entries = new ArrayList<>(library.setups);
		if (entries.isEmpty())
		{
			message("Save a setup before sharing.");
			return;
		}
		JList<String> list = new JList<>(entries.stream().map(e -> SetupCodec.name(e.portable)).toArray(String[]::new));
		list.putClientProperty("html.disable", true);
		list.setCellRenderer(plainNames());
		list.setVisibleRowCount(8);
		JComboBox<String> groups = new JComboBox<>();
		groups.addItem("Choose setups individually");
		for (SetupLibrary.Section section : library.sections)
			groups.addItem(section.name);
		groups.setRenderer(plainNames());
		groups.addActionListener(e ->
		{
			list.clearSelection();
			int group = groups.getSelectedIndex() - 1;
			if (group >= 0)
			{
				String id = library.sections.get(group).id;
				for (int i = 0; i < entries.size(); i++)
					if (Objects.equals(entries.get(i).section, id))
						list.addSelectionInterval(i, i);
			}
		});
		JPanel panel = vertical();
		panel.add(info(
				"Select setups or a section. Only this selection is shared, including its Notes. Import adds independent copies.",
				4));
		panel.add(groups);
		panel.add(new JScrollPane(list));
		themeForm(panel);
		if (JOptionPane.showConfirmDialog(this, panel, "Share selected setups", JOptionPane.OK_CANCEL_OPTION,
				JOptionPane.PLAIN_MESSAGE) != JOptionPane.OK_OPTION)
			return;
		if (!owner.equals(recoveryOwner))
			return;
		Set<String> ids = new HashSet<>();
		for (int i : list.getSelectedIndices())
			ids.add(entries.get(i).id);
		attempt(() ->
		{
			String json = gson.toJson(LibraryTools.bundle(library, ids, gson));
			getToolkit().getSystemClipboard().setContents(new StringSelection(json), null);
			message("Selected setup bundle copied.");
		});
	}

	private void upgradeItems()
	{
		if (dirty)
		{
			message("Save your current draft before upgrading saved setups.");
			return;
		}
		String owner = recoveryOwner, token = session;
		message("Choose the old item in the chatbox, then choose its replacement.");
		host.chooseItem(oldId ->
		{
			if (disposed || !owner.equals(recoveryOwner) || !token.equals(session))
				return;
			host.describe(oldId, old ->
			{
				if (disposed || !owner.equals(recoveryOwner) || !token.equals(session))
					return;
				host.chooseItem(newId -> host.describe(newId, replacement ->
				{
					if (disposed || !owner.equals(recoveryOwner) || !token.equals(session))
						return;
					List<SetupLibrary.Entry> entries = new ArrayList<>();
					for (SetupLibrary.Entry entry : library.setups)
						if (!entry.archived && BankLayouts.items(entry.portable).stream()
								.anyMatch(item -> SetupCodec.id(item) == oldId))
							entries.add(entry);
					if (entries.isEmpty())
					{
						message("No active saved setups contain that exact item.");
						return;
					}
					JList<String> list = new JList<>(
							entries.stream().map(e -> SetupCodec.name(e.portable)).toArray(String[]::new));
					list.putClientProperty("html.disable", true);
					list.setCellRenderer(plainNames());
					list.setVisibleRowCount(8);
					JPanel preview = vertical();
					preview.add(info("Replace " + old.name + " with " + replacement.name
							+ " in selected setups only. Review combat style and requirements. Exact Item IDs only.",
							5));
					preview.add(new JScrollPane(list));
					themeForm(preview);
					if (JOptionPane.showConfirmDialog(this, preview, "Review item upgrade",
							JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE) != JOptionPane.OK_OPTION)
						return;
					if (!owner.equals(recoveryOwner) || !token.equals(session))
						return;
					Set<String> ids = new HashSet<>();
					for (int i : list.getSelectedIndices())
						ids.add(entries.get(i).id);
					attempt(() -> replaceLibraryItems(old, replacement, ids));
				}), this::failure);
			});
		}, this::failure);
	}

	void replaceLibraryItems(ItemInfo old, ItemInfo replacement, Set<String> ids)
	{
		if (dirty)
			throw new IllegalStateException("Save your draft first.");
		if (ids.isEmpty())
			throw new IllegalArgumentException("Select at least one setup.");
		if (old.slot != replacement.slot)
			throw new IllegalArgumentException("Replacement must fit the same Equipment slot or item category.");
		String before = library.serialize(gson);
		commit(next ->
		{
			for (String id : ids)
			{
				SetupLibrary.Entry entry = next.find(id);
				if (entry == null)
					throw new IllegalArgumentException("Choose saved setups.");
				if (!replacement.stackable)
					for (JsonElement item : BankLayouts.items(entry.portable))
						if (SetupCodec.id(item) == old.id && SetupCodec.quantity(item) > 1)
							throw new IllegalArgumentException(
									"A selected stack cannot be replaced by a non-stackable item.");
				for (String key : new String[]{"eq", "inv", "rp", "qv", "bp"})
					if (SetupCodec.setup(entry.portable).has(key))
						for (JsonElement item : SetupCodec.setup(entry.portable).getAsJsonArray(key))
							if (SetupCodec.id(item) == old.id)
							{
								if (key.equals("rp")
										&& !replacement.name.toLowerCase(java.util.Locale.ROOT).endsWith(" rune"))
									throw new IllegalArgumentException("Rune Pouch replacements must be runes.");
								if (key.equals("qv") && replacement.slot != 13)
									throw new IllegalArgumentException("Quiver replacements must be arrows or bolts.");
								if (key.equals("bp")
										&& !replacement.name.toLowerCase(java.util.Locale.ROOT).contains("bolt")
										&& !replacement.name.equalsIgnoreCase("Bolt rack"))
									throw new IllegalArgumentException("Bolt Pouch replacements must be bolts.");
							}
				LibraryTools.replace(entry.portable, old.id, replacement.id, replacement.name);
			}
		});
		if (editingId != null && ids.contains(editingId))
			open(library.find(editingId));
		upgradeBefore = before;
		upgradeAfter = library.serialize(gson);
		message("Updated " + ids.size() + " saved setup(s). Undo last upgrade is available in Library tools.");
	}

	void undoUpgrade()
	{
		if (dirty || upgradeBefore == null || !library.serialize(gson).equals(upgradeAfter))
			throw new IllegalStateException("Library or draft changed. This upgrade can no longer be undone safely.");
		SetupLibrary previous = SetupLibrary.read(upgradeBefore, gson);
		host.save(scope, previous.serialize(gson));
		library = previous;
		String id = editingId;
		upgradeBefore = null;
		upgradeAfter = null;
		if (id != null && library.find(id) != null)
			open(library.find(id));
		renderLibrary();
		message("Last item upgrade undone.");
	}

