	private void refreshCodeOrThrow()
	{
		code.setText("");
		if (draft == null)
			throw new IllegalStateException("Open a setup in the Builder first.");
		fieldsToDraft();
		JsonObject p = draft.deepCopy();
		conversionNotice.setText(format.getSelectedIndex() == 3
				? "Loadout Studio: slots, quantities, item choices, Notes and layout are retained. Use Library > Import to open this code."
				: format.getSelectedIndex() == 0 ? ConversionReview.inventory(p) : ConversionReview.bank(p));
		conversionNotice.setRows(format.getSelectedIndex() == 0 || format.getSelectedIndex() == 3 ? 4 : 8);
		conversionNotice.setMaximumSize(new Dimension(500, conversionNotice.getRows() * 18 + 8));
		conversionNotice.setToolTipText(conversionNotice.getText());
		if (ignoreAmmo.isSelected())
			for (String key : new String[]{"eq", "qv"})
			{
				JsonArray items = SetupCodec.setup(p).getAsJsonArray(key);
				if (items == null)
					continue;
				int start = key.equals("eq") ? 13 : 0;
				for (int i = start; i < items.size(); i++)
					if (!items.get(i).isJsonNull())
					{
						items.get(i).getAsJsonObject().remove("q");
						items.get(i).getAsJsonObject().remove("sc");
					}
			}
		if (format.getSelectedIndex() != 3)
		{
			String invalid = host.itemExportError(p);
			if (invalid != null)
				throw new IllegalArgumentException(invalid);
		}
		code.setText(format.getSelectedIndex() == 3
				? codec.studio(p, exportPretty.isSelected(), exportCompress.isSelected())
				: format.getSelectedIndex() == 0
						? codec.inventory(p, exportPretty.isSelected())
						: codec.bank(p, format.getSelectedIndex() == 2, host::bankItemId));
		code.setCaretPosition(0);
	}

	private void importDialog()
	{
		JTextArea input = new JTextArea(12, 34);
		JScrollPane inputPane = new JScrollPane(input);
		themeForm(inputPane);
		int action = JOptionPane.showConfirmDialog(this, inputPane, "Import setup", JOptionPane.OK_CANCEL_OPTION,
				JOptionPane.PLAIN_MESSAGE);
		if (action != JOptionPane.OK_OPTION)
			return;
		attempt(StudioDiagnostics.Operation.IMPORT, () ->
		{
			String text = SetupExportText.unpack(input.getText());
			JsonElement parsed = text.startsWith("{") ? codec.parse(text) : null;
			if (parsed != null && parsed.isJsonObject() && parsed.getAsJsonObject().has("sections")
					&& parsed.getAsJsonObject().has("setups"))
			{
				if (parsed.getAsJsonObject().has("libraryBundle"))
				{
					SetupLibrary incoming = SetupLibrary.read(text, gson);
					if (JOptionPane.showConfirmDialog(this,
							"Add " + incoming.setups.size() + " shared setup copies? Existing setups stay intact.",
							"Import shared bundle", JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION)
						return;
					commit(next -> LibraryTools.merge(next, incoming, gson));
					message("Shared setups added as independent copies.");
					return;
				}
				SetupLibrary restored = SetupLibrary.read(text, gson);
				if (JOptionPane.showConfirmDialog(this,
						"Replace this plugin's current library with " + restored.setups.size()
								+ " saved setups? Export a backup first if needed.",
						"Restore library backup", JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION)
					return;
				host.save(scope, restored.serialize(gson));
				reloadScope();
				message("Library backup restored.");
				return;
			}
			List<JsonObject> imported = codec.importText(text);
			boolean bankImport = !(text.startsWith("{") || text.startsWith("["))
					|| parsed != null && parsed.isJsonObject() && parsed.getAsJsonObject().has("bankTag");
			JTextArea review = info("Add " + imported.size() + " setup(s)? Existing saved setups are retained.\n"
					+ ConversionReview.imported(imported.get(0), bankImport
							? "Bank Tag"
							: parsed != null && parsed.isJsonObject() && parsed.getAsJsonObject().has("loadoutStudio")
									? "Loadout Studio"
									: "Inventory Setup"),
					9);
			themeForm(review);
			if (JOptionPane.showConfirmDialog(this, review, "Review import",
					JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION)
				return;
			commit(l ->
			{
				for (JsonObject p : imported)
				{
					JsonObject copy = p.deepCopy();
					SetupCodec.setup(copy).addProperty("name", l.uniqueName(SetupCodec.name(copy)));
					l.setups.add(new SetupLibrary.Entry(copy));
				}
			});
			message("Imported " + imported.size() + " setup(s). Open them from Library.");
			renderLibrary();
		});
	}

