		p.add(wikiPresetRows);
		final boolean[] refreshRequested = {false};
		Runnable fetchPage = () ->
		{
			boolean force = refreshRequested[0];
			refreshRequested[0] = false;
			wikiPageTimer.stop();
			long revision = ++wikiPageRevision;
			if (!force)
			{
				wikiPresetRows.removeAll();
				wikiPresetRows.revalidate();
				wikiPresetRows.repaint();
			}
			String requested = url.getText().trim(), capturedScope = scope;
			if (disposed)
				return;
			final String page;
			try
			{
				page = WikiClient.title(requested);
			}
			catch (RuntimeException error)
			{
				wikiPageStatus.setText(failureMessage(error));
				return;
			}
			wikiPageStatus.setText("Loading setups from " + page + "...");
			try
			{
				host.fetchWikiPage(requested, true, force, (loaded, error) ->
				{
					if (disposed || revision != wikiPageRevision || !Objects.equals(scope, capturedScope)
							|| !url.getText().trim().equals(requested))
						return;
					if (error != null)
					{
						wikiPageStatus
								.setText((force ? "Refresh failed; existing choices are retained. " : "") + error);
						message(error);
						return;
