						wikiPageStatus.setToolTipText(wikiPageStatus.getText());
					}
					catch (RuntimeException failure)
					{
						wikiPageStatus.setText(failureMessage(failure));
						message(failureMessage(failure));
					}
				});
			}
			catch (RuntimeException failure)
			{
				wikiPageStatus.setText(failureMessage(failure));
				message(failureMessage(failure));
			}
		};
		wikiPageTimer = new Timer(300, e -> fetchPage.run());
		wikiPageTimer.setRepeats(false);
		watch(url, () ->
		{
			wikiPageRevision++;
			wikiPageTimer.stop();
			wikiPresetRows.removeAll();
			wikiPresetRows.revalidate();
