			if (JOptionPane.showConfirmDialog(this,
					"Fetch a fresh copy from OSRS Wiki? Cached pages already work without a new request.",
					"Refresh Wiki source", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
