	private void generateWiki(String text, String title, String source)
	{
		List<JsonObject> presets = new WikiParser().parse(text, title, source);
		wikiPresetRows.removeAll();
		for (JsonObject preset : presets)
		{
			String variant = WikiParser.variant(preset);
			JButton choose = button(variant, () -> attempt(() -> openWikiPreset(preset)));
			choose.setName("wikiPreset:" + variant);
			choose.setMaximumSize(new Dimension(500, 44));
			choose.setToolTipText("Open " + variant
					+ ". First Wiki choices are a starting point; review gear, quantities and Spellbook before Save.");
			wikiPresetRows.add(choose);
		}
		wikiPageStatus.setText(presets.size() + " setups. Review first choices before Save.");
		themeForm(wikiPresetRows);
		wikiPresetRows.invalidate();
		if (wikiPresetRows.getParent() != null)
			wikiPresetRows.getParent().invalidate();
		wikiPresetRows.revalidate();
		wikiPresetRows.repaint();
	}

	void openWikiPreset(JsonObject original)
	{
		long choice = ++wikiChoiceRevision, page = wikiPageRevision;
		String token = session;
		message("Loading game items for this Wiki setup...");
		host.whenItemsReady(error ->
		{
			if (disposed || choice != wikiChoiceRevision || page != wikiPageRevision || !token.equals(session))
				return;
			if (error != null)
			{
				message(error);
				return;
			}
			JsonObject preset = original.deepCopy(), setup = SetupCodec.setup(preset);
			int unresolved = 0;
			for (String key : new String[]{"eq", "inv", "rp", "qv"})
				for (JsonElement entry : setup.getAsJsonArray(key))
					if (entry != null && !entry.isJsonNull())
					{
						JsonObject item = entry.getAsJsonObject();
						String label = WikiParser.defaultName(item);
						ItemInfo exact = host.defaultItem(label);
						if (exact != null)
						{
							item.addProperty("id", exact.id);
							item.addProperty("label", exact.name);
							itemCache.put(exact.id, exact);
						}
						else
							unresolved++;
					}
			preset = LoadoutDefaults.created(preset, host.settings());
			String previousSession = session;
			newDraft(preset, true);
			if (!previousSession.equals(session))
			{
				editorLayout = host.settings().defaultLayout() == LoadoutStudioConfig.DefaultLayout.ZIGZAG
						? BankLayouts.Mode.ZIGZAG
						: BankLayouts.Mode.PRESET;
				editorBottom = host.settings().defaultZigzagBottom();
				persistRecovery();
				renderBuilder();
			}
			if (!previousSession.equals(session))
				message("Wiki draft loaded. " + unresolved
						+ " unresolved slot(s): click '?' to choose an item. Review quantities and Spellbook before export.");
		});
	}
}

