package com.loadoutstudio;

import java.io.IOException;
import java.net.URI;
import java.net.URLDecoder;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.function.BiConsumer;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okio.Buffer;

/** Public Wiki text only; no player state is transmitted. */
public final class WikiClient
{
	private final com.google.gson.Gson gson;
	private final OkHttpClient http;
	private final Set<Call> pending = ConcurrentHashMap.newKeySet();
	private final java.util.concurrent.ScheduledExecutorService scheduler = java.util.concurrent.Executors
			.newSingleThreadScheduledExecutor(r ->
			{
				Thread t = new Thread(r, "loadout-wiki-on-demand");
				t.setDaemon(true);
				return t;
			});
	private final java.util.Map<String, CacheEntry> cache = new java.util.LinkedHashMap<>(16, 0.75f, true);
	private final java.util.Map<String, Job> jobs = new java.util.HashMap<>();
	private final java.util.ArrayDeque<Job> queue = new java.util.ArrayDeque<>();
	private final java.util.ArrayDeque<Long> starts = new java.util.ArrayDeque<>();
	private java.util.concurrent.ScheduledFuture<?> scheduled;
	private final long interval;
	private long nextRequest, cooldown;
	private boolean busy;
	private volatile boolean closed;
	private static final String USER_AGENT = "LoadoutStudio/0.9.1-rc.12 (https://github.com/Pa5cal1/runelite-loadout-studio; RuneLite)";
	interface Store
	{
		String load() throws IOException;

		void save(String data) throws IOException;
	}
	private final Store store;
	private java.util.function.IntSupplier refreshDays = () -> 0;
	private boolean cacheLoaded;
	private volatile String cacheWarning = "";
	private static final class CacheEntry
	{
		final String text;
		final long fetched, until;
		CacheEntry(String text, long fetched, long until)
		{
			this.text = text;
			this.fetched = fetched;
			this.until = until;
		}
	}
	private static final class Reply
	{
		final String text;
		final long fetched;
		final boolean cached, stale;
		Reply(CacheEntry entry, boolean cached)
		{
			text = entry.text;
			fetched = entry.fetched;
			this.cached = cached;
			stale = System.currentTimeMillis() > entry.until;
		}
	}
	private static final class Job
	{
		final String url;
		final int limit;
		final long ttl;
		final boolean refresh;
		final java.util.List<BiConsumer<Reply, String>> callbacks = new java.util.ArrayList<>();
		Job(String url, int limit, long ttl, boolean refresh)
		{
			this.url = url;
			this.limit = limit;
			this.ttl = ttl;
			this.refresh = refresh;
		}
	}
	public WikiClient(OkHttpClient injected, com.google.gson.Gson gson)
	{
		this(injected, gson, 2000, null);
	}

	WikiClient(OkHttpClient injected, com.google.gson.Gson gson, long interval)
	{
		this(injected, gson, interval, null);
	}

	WikiClient(OkHttpClient injected, com.google.gson.Gson gson, long interval, Store store)
	{
		this.gson = gson;
		this.interval = interval;
		this.store = store;
		http = injected.newBuilder().followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false)
				.callTimeout(25, TimeUnit.SECONDS).build();
	}

	WikiClient(OkHttpClient http, com.google.gson.Gson gson, long interval, Store store,
			java.util.function.IntSupplier refreshDays)
	{
		this(http, gson, interval, store);
		this.refreshDays = refreshDays;
	}

	static java.util.List<String> activityTitles(java.util.List<String> titles)
	{
		java.util.Map<String, String> activities = new java.util.LinkedHashMap<>();
		for (String title : titles)
		{
			if (title.toLowerCase(java.util.Locale.ROOT).contains("\'s head") || title.matches(
					"(?i).*(?:/| )(?:table|miniquest|transcript|dialogue|head|stuffed head|pet|money making guide|loot|drops)(?:/.*)?$"))
				continue;
			String base = title.replaceFirst("(?i)(?:/| )strategies$", "");
			// Slayer task pages contain the actual gear recommendations, not technical subpages.
			if (base.contains("/") && !base.matches("(?i)^Slayer task/[^/]+$"))
				continue;
			String key = base.toLowerCase(java.util.Locale.ROOT).replaceFirst("^the ", "");
			activities.putIfAbsent(key, base);
		}
		return new java.util.ArrayList<>(activities.values());
	}

	public void search(String query, BiConsumer<java.util.List<String>, String> callback)
	{
		String term = query.trim();
		if (term.length() < 2 || term.length() > 120)
			throw new IllegalArgumentException("Enter 2–120 characters to search the Wiki.");
		String url = "https://oldschool.runescape.wiki/api.php?action=opensearch&namespace=0&limit=10&format=json&maxlag=5&maxage=3600&smaxage=3600&search="
				+ URLEncoder.encode(term, StandardCharsets.UTF_8);
		requestJson(url, 100000, 6 * 60 * 60 * 1000L, false, (reply, error) ->
		{
			if (error != null)
			{
				callback.accept(null, error);
				return;
			}
			try
			{
				callback.accept(searchTitles(reply.text, gson), null);
			}
			catch (RuntimeException e)
			{
				callback.accept(null, e.getMessage());
			}
		});
	}

	/** Suggestions from already cached responses only; never calls the HTTP client. */
	public void suggestLocal(String query, java.util.function.Consumer<java.util.List<String>> callback)
	{
		String term = query.trim().toLowerCase(java.util.Locale.ROOT);
		onWorker(() ->
		{
			loadCache();
			java.util.Set<String> titles = new java.util.TreeSet<>();
			for (java.util.Map.Entry<String, CacheEntry> value : cache.entrySet())
				try
				{
					if (value.getKey().contains("action=opensearch"))
						titles.addAll(searchTitles(value.getValue().text, gson));
					else
					{
						Page page = pageResponse(value.getValue().text, gson);
						if (page != null)
							titles.add(page.title);
					}
				}
				catch (RuntimeException ignored)
				{
				}
			callback.accept(titles.stream().filter(title -> title.toLowerCase(java.util.Locale.ROOT).contains(term))
					.limit(10).collect(java.util.stream.Collectors.toList()));
		});
	}

	private void onWorker(Runnable action)
	{
		if (closed)
			return;
		try
		{
			scheduler.execute(() ->
			{
				if (!closed)
					action.run();
			});
		}
		catch (java.util.concurrent.RejectedExecutionException ignored)
		{
		}
	}

	private void loadCache()
	{
		if (cacheLoaded)
			return;
		cacheLoaded = true;
		if (store == null)
			return;
		try
		{
			String data = store.load();
			if (data.isEmpty())
				return;
			if (data.length() > 8_000_000 || !data.startsWith("LOADOUT-WIKI-CACHE-1\n"))
				throw new IOException("Invalid Wiki cache.");
			int count = 0;
			for (String line : data.substring(21).split("\n"))
			{
				if (line.isEmpty())
					continue;
				if (++count > 64)
					throw new IOException("Too many cached pages.");
				try
				{
					com.google.gson.JsonObject entry = new SetupCodec(gson).parse(line).getAsJsonObject();
					String url = entry.get("url").getAsString(), text = entry.get("text").getAsString();
					long fetched = entry.get("fetched").getAsLong(), until = entry.get("until").getAsLong(),
							now = System.currentTimeMillis();
					if (!allowedUrl(url) || fetched < 1 || fetched > now + 60000 || until < fetched
							|| until > fetched + 30 * 24 * 60 * 60 * 1000L)
						continue;
					validateResponse(url, text);
					cache.put(url, new CacheEntry(text, fetched, until));
				}
				catch (RuntimeException ignored)
				{
					cacheWarning = "Some invalid cached Wiki entries were ignored.";
				}
			}
			trimCache();
		}
		catch (IOException | RuntimeException ex)
		{
			diagnostics.completed(StudioDiagnostics.Operation.WIKI_CACHE_IO, StudioDiagnostics.Outcome.IO_FAILURE, 0);
			cacheWarning = "Local Wiki cache could not be read; saved loadouts are unaffected.";
			cache.clear();
		}
	}

	private static boolean allowedUrl(String url)
	{
		try
		{
			URI uri = URI.create(url);
			return "https".equals(uri.getScheme()) && "oldschool.runescape.wiki".equals(uri.getHost())
					&& uri.getPort() == -1 && uri.getUserInfo() == null && "/api.php".equals(uri.getPath())
					&& (url.contains("action=query&redirects=1&prop=revisions")
							|| url.contains("action=opensearch&namespace=0"));
		}
		catch (RuntimeException ex)
		{
			return false;
		}
	}

	private void validateResponse(String url, String text)
	{
		if (url.contains("action=opensearch"))
		{
			if (text.length() > 100000)
				throw new IllegalArgumentException();
			searchTitles(text, gson);
		}
		else
			pageResponse(text, gson);
	}

	private void trimCache()
	{
		int characters = 0;
		for (CacheEntry entry : cache.values())
			characters += entry.text.length();
		java.util.Iterator<CacheEntry> it = cache.values().iterator();
		while ((characters > 4_000_000 || cache.size() > 64) && it.hasNext())
		{
			characters -= it.next().text.length();
			it.remove();
		}
	}

	private void persistCache()
	{
		if (store == null)
			return;
		try
		{
			StringBuilder data = new StringBuilder("LOADOUT-WIKI-CACHE-1\n");
			for (java.util.Map.Entry<String, CacheEntry> value : cache.entrySet())
			{
				com.google.gson.JsonObject entry = new com.google.gson.JsonObject();
				entry.addProperty("url", value.getKey());
				entry.addProperty("text", value.getValue().text);
				entry.addProperty("fetched", value.getValue().fetched);
				entry.addProperty("until", value.getValue().until);
				String line = gson.toJson(entry).replace("\n", "").replace("\r", "");
				if (line.length() > SetupCodec.MAX_TEXT)
					continue;
				if (data.length() + line.length() > 4_000_000)
					continue;
				data.append(line).append('\n');
			}
			store.save(data.toString());
			cacheWarning = "";
		}
		catch (IOException | RuntimeException ex)
		{
			diagnostics.completed(StudioDiagnostics.Operation.WIKI_CACHE_IO, StudioDiagnostics.Outcome.IO_FAILURE, 0);
			cacheWarning = "Wiki cache could not be saved to disk; this session still works.";
		}
	}

	public String cacheWarning()
	{
		return cacheWarning;
	}
	private StudioDiagnostics diagnostics = new StudioDiagnostics();
	void diagnostics(StudioDiagnostics diagnostics)
	{
		this.diagnostics = diagnostics;
	}

	private void requestJson(String url, int limit, long ttl, boolean refresh, BiConsumer<Reply, String> callback)
	{
		onWorker(() ->
		{
			loadCache();
			CacheEntry saved = cache.get(url);
			long now = System.currentTimeMillis();
			int days = Math.max(0, Math.min(30, refreshDays.getAsInt()));
			if (saved != null && days > 0 && url.contains("prop=revisions"))
			{
				saved = new CacheEntry(saved.text, saved.fetched, saved.fetched + days * 24 * 60 * 60 * 1000L);
				cache.put(url, saved);
			}
			if (!refresh && saved != null && (now < saved.until || url.contains("prop=revisions") && days == 0))
			{
				diagnostics.completed(StudioDiagnostics.Operation.WIKI_CACHE_HIT, StudioDiagnostics.Outcome.SUCCESS, 0);
				callback.accept(new Reply(saved, true), null);
				return;
			}
			if (now < cooldown)
			{
				if (!refresh && saved != null)
				{
					diagnostics.completed(StudioDiagnostics.Operation.WIKI_CACHE_FALLBACK,
							StudioDiagnostics.Outcome.SUCCESS, 0);
					callback.accept(new Reply(saved, true), null);
				}
				else
					callback.accept(null, "Wiki requests are paused. Use cached/saved setups or try later.");
				return;
			}
			Job existing = jobs.get(url);
			if (existing != null)
			{
				diagnostics.completed(StudioDiagnostics.Operation.WIKI_COALESCED, StudioDiagnostics.Outcome.SUCCESS, 0);
				existing.callbacks.add(callback);
				return;
			}
			if (jobs.size() >= 12)
			{
				callback.accept(null, "Too many pending Wiki requests. Wait for the current search.");
				return;
			}
			Job job = new Job(url, limit, ttl, refresh);
			job.callbacks.add(callback);
			jobs.put(url, job);
			queue.add(job);
			schedule();
		});
	}

	private synchronized void schedule()
	{
		if (closed || busy || queue.isEmpty() || scheduled != null && !scheduled.isDone())
			return;
		long now = System.currentTimeMillis();
		while (!starts.isEmpty() && now - starts.peekFirst() >= 60000)
			starts.removeFirst();
		long due = Math.max(now, nextRequest);
		if (starts.size() >= 10)
			due = Math.max(due, starts.peekFirst() + 60000);
		scheduled = scheduler.schedule(() ->
		{
			synchronized (WikiClient.this)
			{
				scheduled = null;
				if (closed || busy || queue.isEmpty())
					return;
				busy = true;
				starts.addLast(System.currentTimeMillis());
				nextRequest = System.currentTimeMillis() + interval;
			}
			send();
		}, Math.max(0, due - now), TimeUnit.MILLISECONDS);
	}

	private void send()
	{
		final long started = System.nanoTime();
		final Job job;
		synchronized (this)
		{
			if (closed || queue.isEmpty())
			{
				busy = false;
				return;
			}
			job = queue.removeFirst();
		}
		Call call = http.newCall(new Request.Builder().url(job.url).header("User-Agent", USER_AGENT)
				.header("Cache-Control", job.refresh ? "no-cache" : "max-age=3600").build());
		synchronized (this)
		{
			if (closed)
				return;
			pending.add(call);
			call.enqueue(new Callback()
			{
				public void onFailure(Call c, IOException e)
				{
					pending.remove(c);
					onWorker(() ->
					{
						diagnostics.completed(StudioDiagnostics.Operation.WIKI_HTTP,
								StudioDiagnostics.Outcome.SERVICE_FAILURE, started);
						finish(job, null, "Wiki request failed. No automatic retry was made.", false);
					});
				}

				public void onResponse(Call c, Response response)
				{
					String text = null, error = null, retry = null;
					boolean paused = false;
					try (Response r = response)
					{
						if (r.code() == 429 || r.code() == 503 || r.header("Retry-After") != null)
						{
							paused = true;
							retry = r.header("Retry-After");
							throw new IOException("Wiki is busy. Requests paused; no automatic retry will be made.");
						}
						if (!r.isSuccessful() || r.body() == null)
							throw new IOException("Wiki API request failed (HTTP " + r.code() + ").");
						if (r.body().contentLength() > job.limit)
							throw new IOException("Wiki response is too large.");
						Buffer buffer = new Buffer();
						while (r.body().source().read(buffer, 8192) != -1)
							if (buffer.size() > job.limit)
								throw new IOException("Wiki response is too large.");
						text = buffer.readUtf8();
						com.google.gson.JsonElement parsed = new SetupCodec(gson).parse(text);
						if (parsed.isJsonObject() && parsed.getAsJsonObject().has("error"))
						{
							paused = true;
							retry = r.header("Retry-After");
							throw new IOException("Wiki API rejected this request. Requests paused; try later.");
						}
						validateResponse(job.url, text);
					}
					catch (IOException | RuntimeException ex)
					{
						error = ex.getMessage();
						text = null;
					}
					finally
					{
						pending.remove(c);
					}
					final String result = text, failure = error, after = retry;
					final boolean pause = paused;
					onWorker(() ->
					{
						diagnostics.completed(StudioDiagnostics.Operation.WIKI_HTTP,
								failure == null
										? StudioDiagnostics.Outcome.SUCCESS
										: StudioDiagnostics.Outcome.SERVICE_FAILURE,
								started);
						if (pause)
							pause(after);
						finish(job, result, failure, pause);
					});
				}
			});
		}
	}

	private void pause(String retry)
	{
		long delay = 60000;
		if (retry != null)
			try
			{
				long seconds = Long.parseLong(retry.trim());
				delay = Math.max(delay, seconds > 86400 ? 86400000 : Math.max(0, seconds) * 1000);
			}
			catch (NumberFormatException ex)
			{
				try
				{
					delay = Math.max(delay,
							java.time.ZonedDateTime.parse(retry, java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME)
									.toInstant().toEpochMilli() - System.currentTimeMillis());
				}
				catch (RuntimeException ignored)
				{
				}
			}
		cooldown = System.currentTimeMillis() + Math.min(86400000, delay);
	}

	private void finish(Job job, String text, String error, boolean paused)
	{
		busy = false;
		if (closed)
			return;
		jobs.remove(job.url);
		if (text != null)
		{
			long now = System.currentTimeMillis();
			cache.put(job.url, new CacheEntry(text, now, now + job.ttl));
			trimCache();
			persistCache();
		}
		deliver(job, text, error);
		if (paused)
		{
			java.util.List<Job> waiting = new java.util.ArrayList<>(queue);
			queue.clear();
			jobs.clear();
			for (Job next : waiting)
				deliver(next, null, error);
		}
		schedule();
	}

	private void deliver(Job job, String text, String error)
	{
		CacheEntry entry = cache.get(job.url);
		Reply reply = entry != null && (text != null || !job.refresh) ? new Reply(entry, text == null) : null;
		if (reply != null && text == null)
			diagnostics.completed(StudioDiagnostics.Operation.WIKI_CACHE_FALLBACK, StudioDiagnostics.Outcome.SUCCESS,
					0);
		for (BiConsumer<Reply, String> callback : job.callbacks)
			if (!closed)
				callback.accept(reply, reply == null ? error : null);
	}

	static java.util.List<String> searchTitles(String text, com.google.gson.Gson gson)
	{
		com.google.gson.JsonElement parsed = new SetupCodec(gson).parse(text);
		if (parsed == null || !parsed.isJsonArray() || parsed.getAsJsonArray().size() != 4
				|| !parsed.getAsJsonArray().get(1).isJsonArray())
			throw new IllegalArgumentException("Unexpected Wiki search response.");
		java.util.List<String> result = new java.util.ArrayList<>();
		for (com.google.gson.JsonElement item : parsed.getAsJsonArray().get(1).getAsJsonArray())
		{
			if (!item.isJsonPrimitive() || !item.getAsJsonPrimitive().isString())
				throw new IllegalArgumentException("Invalid Wiki search title.");
			String title = item.getAsString();
			if (!title.isEmpty() && title.length() <= 250 && result.size() < 10)
				result.add(title);
		}
		return result;
	}

	public static String articleUrl(String title)
	{
		return "https://oldschool.runescape.wiki/w/"
				+ URLEncoder.encode(title.replace(' ', '_'), StandardCharsets.UTF_8).replace("%2F", "/");
	}

	public static String title(String url)
	{
		URI uri = URI.create(url.trim());
		if (!"https".equals(uri.getScheme()) || !"oldschool.runescape.wiki".equals(uri.getHost()) || uri.getPort() != -1
				|| uri.getUserInfo() != null || !uri.getRawPath().startsWith("/w/"))
			throw new IllegalArgumentException("Enter an HTTPS article URL on oldschool.runescape.wiki/w/.");
		String title = URLDecoder.decode(uri.getRawPath().substring(3).replace("+", "%2B"), StandardCharsets.UTF_8)
				.replace('_', ' ');
		if (title.trim().isEmpty() || title.length() > 250)
			throw new IllegalArgumentException("Invalid Wiki page title.");
		return title;
	}
	public static final class Page
	{
		public final String title, text;
		public final long fetchedAt;
		public final boolean cached, stale;
		public Page(String title, String text)
		{
			this(title, text, 0, false, false);
		}

		public Page(String title, String text, long fetchedAt, boolean cached, boolean stale)
		{
			this.title = title;
			this.text = text;
			this.fetchedAt = fetchedAt;
			this.cached = cached;
			this.stale = stale;
		}

		public String url()
		{
			return articleUrl(title);
		}
	}
	public void fetch(String url, BiConsumer<String, String> callback)
	{
		fetchPage(url, false, (page, error) -> callback.accept(page == null ? null : page.text, error));
	}

	public void fetchPage(String url, boolean preferStrategies, BiConsumer<Page, String> callback)
	{
		fetchPage(url, preferStrategies, false, callback);
	}

	public void fetchPage(String url, boolean preferStrategies, boolean refresh, BiConsumer<Page, String> callback)
	{
		String requested = title(url);
		requestPage(requested, refresh, (page, error) ->
		{
			if (error != null)
			{
				callback.accept(null, error);
				return;
			}
			if (page == null && requested.toLowerCase(java.util.Locale.ROOT).endsWith("/strategies"))
			{
				String base = requested.substring(0, requested.length() - "/Strategies".length());
				requestPage(base, refresh, (fallback, failure) ->
				{
					if (failure != null)
						callback.accept(null, failure);
					else if (fallback == null)
						callback.accept(null, "Wiki page not found: " + requested);
					else
						preferredPage(fallback, preferStrategies, refresh, callback);
				});
			}
			else if (page == null)
				callback.accept(null, "Wiki page not found: " + requested);
			else
				preferredPage(page, preferStrategies, refresh, callback);
		});
	}

	private void preferredPage(Page page, boolean preferStrategies, boolean refresh, BiConsumer<Page, String> callback)
	{
		if (closed)
			return;
		if (!preferStrategies || page.title.toLowerCase(java.util.Locale.ROOT).endsWith("/strategies"))
		{
			callback.accept(page, null);
			return;
		}
		requestPage(page.title + "/Strategies", refresh,
				(strategy, error) -> callback.accept(error == null ? strategy == null ? page : strategy : null, error));
	}

	static Page pageResponse(String text, com.google.gson.Gson gson)
	{
		com.google.gson.JsonElement parsed = new SetupCodec(gson).parse(text);
		if (parsed == null || !parsed.isJsonObject())
			throw new IllegalArgumentException("Unexpected Wiki page response.");
		com.google.gson.JsonObject root = parsed.getAsJsonObject();
		if (root.has("error"))
			throw new IllegalArgumentException("The Wiki API could not resolve this page.");
		if (!root.has("query") || !root.get("query").isJsonObject())
			throw new IllegalArgumentException("Missing Wiki page information.");
		com.google.gson.JsonObject query = root.getAsJsonObject("query");
		if (query.has("interwiki") || !query.has("pages") || !query.get("pages").isJsonArray()
				|| query.getAsJsonArray("pages").size() != 1)
			throw new IllegalArgumentException("Choose a single article on OSRS Wiki.");
		com.google.gson.JsonObject page = query.getAsJsonArray("pages").get(0).getAsJsonObject();
		if (page.has("invalid"))
			throw new IllegalArgumentException("Invalid Wiki page title.");
		if (page.has("missing") && page.get("missing").getAsBoolean())
			return null;
		if (page.has("ns") && page.get("ns").getAsInt() != 0)
			throw new IllegalArgumentException("Choose an OSRS Wiki article, rather than a special page or template.");
		String title = page.get("title").getAsString();
		if (title.trim().isEmpty() || title.length() > 250 || title.indexOf('|') >= 0)
			throw new IllegalArgumentException("Invalid canonical Wiki title.");
		if (page.has("redirect") && page.get("redirect").getAsBoolean())
			throw new IllegalArgumentException("The Wiki redirect could not be resolved.");
		com.google.gson.JsonArray revisions = page.getAsJsonArray("revisions");
		if (revisions == null || revisions.size() != 1)
			throw new IllegalArgumentException("Wiki page source is unavailable.");
		String source = revisions.get(0).getAsJsonObject().getAsJsonObject("slots").getAsJsonObject("main")
				.get("content").getAsString();
		if (source.length() > 1_500_000)
			throw new IllegalArgumentException("Wiki page source is too large.");
		return new Page(title, source);
	}

	private void requestPage(String title, boolean refresh, BiConsumer<Page, String> callback)
	{
		if (closed)
			return;
		if (title.trim().isEmpty() || title.length() > 250 || title.indexOf('|') >= 0)
		{
			callback.accept(null, "Enter a single valid Wiki page title.");
			return;
		}
		String url = "https://oldschool.runescape.wiki/api.php?action=query&redirects=1&prop=revisions&rvprop=content&rvslots=main&format=json&formatversion=2&titles="
				+ URLEncoder.encode(title, StandardCharsets.UTF_8);
		url += "&maxlag=5&maxage=3600&smaxage=3600";
		requestJson(url, 1_500_000, 7 * 24 * 60 * 60 * 1000L, refresh, (reply, error) ->
		{
			if (error != null)
			{
				callback.accept(null, error);
				return;
			}
			try
			{
				Page page = pageResponse(reply.text, gson);
				callback.accept(
						page == null ? null : new Page(page.title, page.text, reply.fetched, reply.cached, reply.stale),
						null);
			}
			catch (RuntimeException ex)
			{
				callback.accept(null, ex.getMessage());
			}
		});
	}

	public synchronized void close()
	{
		closed = true;
		if (scheduled != null)
			scheduled.cancel(false);
		scheduler.shutdownNow();
		for (Call c : pending)
			c.cancel();
		pending.clear();
	}
}

/* SPDX-License-Identifier: BSD-2-Clause */
package com.loadoutstudio;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads concrete Wiki templates and their locally scoped, source-ordered recommendations. */
public final class WikiParser
{
	static final class Node
	{
		String kind;
		Map<String, String> fields = new LinkedHashMap<>();
		int start;
		int end;
	}
	public static List<String> split(String text, String delimiter)
	{
		List<String> result = new ArrayList<>();
		int braces = 0, links = 0, tables = 0, start = 0;
		for (int i = 0; i < text.length(); i++)
		{
			if (text.startsWith("{{", i))
			{
				braces++;
				i++;
			}
			else if (text.startsWith("}}", i))
			{
				braces--;
				i++;
			}
			else if (text.startsWith("[[", i))
			{
				links++;
				i++;
			}
			else if (text.startsWith("]]", i))
			{
				links--;
				i++;
			}
			else if (text.startsWith("{|", i))
			{
				tables++;
				i++;
			}
			else if (text.startsWith("|}", i))
			{
				tables--;
				i++;
			}
			else if (braces == 0 && links == 0 && tables == 0 && text.startsWith(delimiter, i))
			{
				result.add(text.substring(start, i));
				i += delimiter.length() - 1;
				start = i + 1;
			}
		}
		result.add(text.substring(start));
		return result;
	}

	static List<Node> nodes(String text)
	{
		List<Integer> stack = new ArrayList<>();
		List<Node> result = new ArrayList<>();
		for (int i = 0; i < text.length() - 1; i++)
		{
			if (text.startsWith("{{", i))
			{
				if (stack.size() >= 48)
					throw new IllegalArgumentException("Wiki nesting exceeds the supported limit.");
				stack.add(i++);
			}
			else if (text.startsWith("}}", i) && !stack.isEmpty())
			{
				int start = stack.remove(stack.size() - 1);
				Node node = new Node();
				node.start = start;
				node.end = i + 2;
				List<String> fields = split(text.substring(start + 2, i), "|");
				node.kind = fields.get(0).trim().replace('_', ' ').toLowerCase(Locale.ROOT);
				int positional = 1;
				for (String field : fields.subList(1, fields.size()))
				{
					List<String> pair = split(field, "=");
					if (pair.size() > 1)
						node.fields.put(pair.get(0).trim(), String.join("=", pair.subList(1, pair.size())).trim());
					else
						node.fields.put(String.valueOf(positional++), field.trim());
				}
				result.add(node);
				if (result.size() > 10000)
					throw new IllegalArgumentException("Too many Wiki templates.");
				i++;
			}
		}
		result.sort(java.util.Comparator.comparingInt(n -> n.start));
		return result;
	}

	public static String plain(String text)
	{
		return text.replaceAll("(?s)<!--.*?-->", "").replaceAll("\\[\\[([^]|]+)\\|([^]]+)]]", "$2")
				.replaceAll("\\[\\[([^]]+)]]", "$1").replaceAll("<[^>]+>", "").replace("'''", "").replace("''", "")
				.replace("&amp;", "&").replace("&nbsp;", " ").trim();
	}

	private static boolean concrete(Node n)
	{
		return n.kind.equals("equipment") || n.kind.equals("inventory") || n.kind.equals("rune pouch");
	}

	/** Bundled source order, deliberately independent of live market prices. */
	static String defaultName(JsonObject item)
	{
		if (item.has("choices") && item.get("choices").isJsonArray() && item.getAsJsonArray("choices").size() > 0)
		{
			String chosen = item.has("label") ? item.get("label").getAsString() : "";
			return chosen.isBlank() ? item.getAsJsonArray("choices").get(0).getAsString() : chosen;
		}
		String name = item.has("label") ? item.get("label").getAsString() : "";
		String marker = name.trim().replace('_', ' ').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
		if (marker.matches("\\{\\{ ?cheap food ?}}"))
			return "Manta ray";
		if (marker.matches("\\{\\{ ?cheap prayer ?}}"))
			return "Prayer potion(4)";
		return name;
	}

	private static JsonElement item(String value, String explicit, boolean quantityRequired)
	{
		if (value == null || value.trim().isEmpty() || value.trim().matches("(?i)none|empty|n/a|-"))
			return JsonNull.INSTANCE;
		Matcher quantity = Pattern.compile("\\\\([0-9,]+)").matcher(value);
		String q = explicit;
		if (quantity.find())
			q = quantity.group(1);
		String names = value.split("\\\\", 2)[0];
		String[] parts = names.split(";");
		String name = itemName(parts[0]);
		for (int i = 1; i < parts.length; i++)
			if (!parts[i].matches("[ng]") && !parts[i].trim().isEmpty())
			{
				name = itemName(parts[i]);
				break;
			}
		JsonObject item = SetupCodec.item(0, 1);
		item.addProperty("label", name);
		if (names.contains(" / "))
		{
			JsonArray options = new JsonArray();
			for (String option : names.split("\\s+/\\s+"))
			{
				String candidate = itemName(option);
				if (!candidate.isBlank())
					options.add(candidate);
			}
			if (options.size() > 1)
			{
				item.add("choices", options);
				item.addProperty("label", options.get(0).getAsString());
			}
		}
		if (q != null && q.matches("[0-9,]+"))
			item.addProperty("q", SetupCodec.parseQuantity(q));
		else if (quantityRequired)
			item.add("q", JsonNull.INSTANCE);
		return item;
	}

	static String itemName(String raw)
	{
		String value = plain(raw).replaceAll("(?s)<ref.*?</ref>", "").trim();
		for (Node node : nodes(raw))
			if (node.kind.equals("plink") || node.kind.equals("item") || node.kind.equals("icon")
					|| node.kind.equals("rune"))
			{
				String first = node.fields.getOrDefault("1", "");
				if (!first.isBlank())
				{
					value = first.contains("#")
							? node.fields.getOrDefault("pic", node.fields.getOrDefault("txt", first))
							: first;
					if (node.kind.equals("rune") && !value.toLowerCase(Locale.ROOT).endsWith(" rune"))
						value += " rune";
					break;
				}
			}
		value = value.replaceAll("(?i)\\s*\\((tablet|tab)\\)$", "").replaceAll("\\s*\\[.*?]", "").trim();
		return ItemCatalogue.normalize(value);
	}

	private static String namedVariant(String raw, String text, int offset, String fallback)
	{
		String label = plain(raw).trim();
		if (label.isEmpty() || label.matches(
				"(?i)(?:wiki preset \\d+|(?:style|class|rowspan|colspan)\\s*=.*|item|slot|equipment|inventory)"))
		{
			String prefix = text.substring(0, Math.max(0, Math.min(offset, text.length())));
			Matcher headings = Pattern.compile("(?m)^={2,5}\\s*(.*?)\\s*={2,5}\\s*$").matcher(prefix);
			String heading = "";
			while (headings.find())
				heading = plain(headings.group(1));
			label = heading.matches(
					"(?i)(equipment|inventory|recommended equipment|requirements|suggested skills|strategy|strategies)")
							? ""
							: heading;
		}
		return label.isEmpty() ? fallback : label;
	}

	private static JsonObject fill(String title, String variant, String source, List<Node> nodes)
	{
		JsonObject p = SetupCodec.blank(title.isEmpty() ? variant : title), s = SetupCodec.setup(p);
		s.addProperty("notes", "Source: " + source + "\nPreset: " + variant + "");
		String[] keys = {"head", "cape", "neck", "weapon", "body", "shield", "", "legs", "", "hands", "feet", "",
				"ring", "ammo"};
		for (Node node : nodes)
		{
			if (node.kind.equals("inventory"))
				for (int i = 0; i < 28; i++)
					s.getAsJsonArray("inv").set(i, item(node.fields.get(String.valueOf(i + 1)), null, false));
			else if (node.kind.equals("equipment"))
			{
				for (int i = 0; i < 14; i++)
					if (!keys[i].isEmpty())
						s.getAsJsonArray("eq").set(i,
								item(equipmentField(node, keys[i]), node.fields.get(keys[i] + "quantity"), i == 13));
				s.getAsJsonArray("qv").set(0, item(node.fields.get("ammo2"), node.fields.get("ammo2quantity"), true));
			}
			else if (node.kind.equals("rune pouch"))
				for (int i = 0; i < 4; i++)
					s.getAsJsonArray("rp").set(i, item(node.fields.get(String.valueOf(i + 1)), null, true));
		}
		// Concrete loadouts retain their selected gear and Inventory. The adjacent table
		// supplies alternatives, never a separate variant's or a global same-slot list.
		for (JsonObject ranked : recommendations(nodes, title, source))
		{
			JsonArray alternatives = SetupCodec.setup(ranked).getAsJsonArray("eq");
			for (int i = 0; i < alternatives.size(); i++)
			{
				JsonElement current = s.getAsJsonArray("eq").get(i), row = alternatives.get(i);
				if (!row.isJsonNull())
				{
					if (!current.isJsonNull())
						current.getAsJsonObject().add("choices",
								row.getAsJsonObject().getAsJsonArray("choices").deepCopy());
					else if (nodes.stream().noneMatch(n -> n.kind.equals("equipment")))
						s.getAsJsonArray("eq").set(i, row.deepCopy());
				}
			}

		}
		SetupCodec.rebuildLayout(p);
		return p;
	}

	private static String equipmentField(Node node, String key)
	{
		if (node.fields.containsKey(key))
			return node.fields.get(key);
		String alias = key.equals("body")
				? "torso"
				: key.equals("hands") ? "gloves" : key.equals("feet") ? "boots" : key;
		return node.fields.get(alias);
	}

	private static String tabberVariant(String text, int offset, String fallback)
	{
		int start = text.lastIndexOf("<tabber", offset), closed = text.lastIndexOf("</tabber>", offset);
		if (start < 0 || closed > start)
			return fallback;
		Matcher labels = Pattern.compile("(?m)^([^\\r\\n|{}<>=]{1,100})=\\s*$").matcher(text.substring(start, offset));
		String label = fallback;
		while (labels.find())
			label = plain(labels.group(1));
		return label;
	}

	public static String variant(JsonObject preset)
	{
		String notes = SetupCodec.setup(preset).get("notes").getAsString();
		for (String line : notes.split("\\R"))
			if (line.startsWith("Preset: "))
				return line.substring(8);
		return SetupCodec.name(preset);
	}

	public List<JsonObject> parse(String text, String pageTitle, String source)
	{
		if (text == null || text.length() > 1_500_000)
			throw new IllegalArgumentException("Wiki text must be smaller than 1.5 MB.");
		String title = plain(pageTitle).replace('_', ' ').split("(?i)/Strategies", 2)[0];
		if (title.length() > 50)
			title = title.substring(0, 50);
		List<JsonObject> result = new ArrayList<>();
		List<int[]> used = new ArrayList<>();
		int search = 0;
		while ((search = text.indexOf("{|", search)) >= 0)
		{
			int end = search + 2, depth = 1;
			while (end < text.length() - 1 && depth > 0)
			{
				if (text.startsWith("{|", end))
				{
					depth++;
					end++;
				}
				else if (text.startsWith("|}", end))
				{
					depth--;
					end++;
				}
				end++;
			}
			if (depth != 0)
				break;
			Map<Integer, List<List<Node>>> columns = new LinkedHashMap<>();
			Map<Integer, String> headers = new HashMap<>();
			String table = text.substring(search + 2, end - 2);
			for (String row : split(table, "\n|-"))
			{
				Matcher header = Pattern.compile("(?m)^!\\s*(.*)$").matcher(row);
				while (header.find())
				{
					int column = 0;
					for (String cell : split(header.group(1), "!!"))
					{
						List<String> parts = split(cell, "|");
						String name = plain(
								parts.size() > 1 && parts.get(0).contains("=") ? parts.get(parts.size() - 1) : cell);
						if (!name.isBlank())
							headers.putIfAbsent(column, name);
						column++;
					}
				}
				if (!row.contains("{{"))
					continue;
				List<String> cells = new ArrayList<>();
				for (String chunk : split("\n" + row, "\n|"))
				{
					if (chunk.trim().isEmpty() || chunk.startsWith("+") || !chunk.contains("{{")
							&& chunk.trim().matches("(?s)(?:class|style|rowspan|colspan)\\s*=.*"))
						continue;
					for (String cell : split(chunk, "||"))
						cells.addAll(split(cell, "\n!"));
				}

				for (int col = 0; col < cells.size(); col++)
				{
					String cell = cells.get(col);
					if (!cell.contains("{{") && !plain(cell).isEmpty() && plain(cell).length() < 80)
						headers.putIfAbsent(col, plain(cell));
					for (Node node : nodes(cell))
						if (concrete(node) || node.kind.equals("recommended equipment"))
						{
							List<List<Node>> groups = columns.computeIfAbsent(col, k -> new ArrayList<>());
							if (groups.isEmpty()
									|| groups.get(groups.size() - 1).stream().anyMatch(n -> n.kind.equals(node.kind)))
								groups.add(new ArrayList<>());
							groups.get(groups.size() - 1).add(node);
						}
				}
			}
			for (Map.Entry<Integer, List<List<Node>>> column : columns.entrySet())
				for (List<Node> group : column.getValue())
					if (group.stream().anyMatch(n -> n.kind.equals("inventory")))
					{
						result.add(fill(title, namedVariant(headers.getOrDefault(column.getKey(), ""), text, search,
								tierName(result.size())), source, group));
						used.add(new int[]{search, end});
					}
			search = end;
		}
		List<Node> free = new ArrayList<>();
		for (Node node : nodes(text))
			if ((concrete(node) || node.kind.equals("recommended equipment"))
					&& used.stream().noneMatch(range -> range[0] <= node.start && node.start < range[1]))
				free.add(node);
		List<Node> group = new ArrayList<>();
		String variant = "";
		for (Node node : free)
		{
			String nextVariant = tabberVariant(text, node.start, "");
			if (!group.isEmpty()
					&& (!variant.equals(nextVariant) || group.stream().anyMatch(n -> n.kind.equals(node.kind))))
			{
				if (group.stream().anyMatch(n -> n.kind.equals("inventory") || n.kind.equals("equipment")))
					result.add(fill(title, namedVariant(variant, text, node.start, tierName(result.size())), source,
							group));
				else
					result.addAll(recommendations(group, title, source));
				group = new ArrayList<>();
			}
			variant = nextVariant;
			group.add(node);
		}
		if (group.stream().anyMatch(n -> n.kind.equals("inventory") || n.kind.equals("equipment")))
			result.add(fill(title, namedVariant(variant, text, text.length(), tierName(result.size())), source, group));
		else
			result.addAll(recommendations(group, title, source));
		if (result.size() > 100)
			throw new IllegalArgumentException("Too many presets on this page.");
		if (result.isEmpty())
			result.addAll(recommendations(nodes(text), title, source));
		if (result.isEmpty())
			throw new IllegalArgumentException(
					"No Equipment, Inventory or Recommended equipment templates found. Use the Builder or import a setup.");
		for (JsonObject preset : result)
		{
			String variantName = variant(preset);
			String name = title + " (" + variantName + ")";
			setupName(preset, name.length() > 50 ? name.substring(0, 50) : name);
		}
		return result;
	}

	private static void setupName(JsonObject preset, String name)
	{
		SetupCodec.setup(preset).addProperty("name", name);
	}

	private static String tierName(int index)
	{
		return index == 0
				? "Max gear"
				: index == 1
						? "High-tier gear"
						: index == 2 ? "Mid-game gear" : index == 3 ? "Budget gear" : "Gear option " + (index + 1);
	}

	/** Remove only recognisable generated rank lines, preserving personal additions. */
	static String compactGeneratedNotes(String text)
	{
		if (text == null || !text.startsWith("Source: ") || !text.contains("\nPreset: "))
			return text;
		String marker = "\nWiki recommendation order (most to least effective); conditions:";
		int start = text.indexOf(marker), tail;
		if (start < 0)
		{
			start = text.indexOf("\nFirst listed items are selected by default. Gear alternatives only:");
			if (start < 0)
				return text;
			tail = text.indexOf('\n', start + 1);
			if (tail < 0)
				tail = text.length();
		}
		else
			tail = start + marker.length();
		String head = text.substring(0, start).replace("\nReview Item IDs, quantities and Spellbook before use.", "");
		StringBuilder result = new StringBuilder(head);
		for (String line : text.substring(tail).split("\\R"))
			if (!line.isBlank()
					&& !line.matches(
							"(?i)^(head|cape|neck|weapon|body|shield|legs|hands|feet|ring|ammo) rank [0-9]+:.*")
					&& !line.equals("See the source page for remaining conditions."))
				result.append('\n').append(line);
		return result.toString();
	}

	/** The first listed recommendation is the default; conditions and alternatives remain editable. */
	private static List<JsonObject> recommendations(List<Node> tables, String title, String source)
	{
		List<JsonObject> result = new ArrayList<>();
		String[] keys = {"head", "cape", "neck", "weapon", "body", "shield", "", "legs", "", "hands", "feet", "",
				"ring", "ammo"};
		for (Node table : tables)
			if (table.kind.equals("recommended equipment"))
			{
				if (result.size() >= 100)
					throw new IllegalArgumentException("Too many recommendation tables.");
				String style = plain(table.fields.getOrDefault("style", "Gear"));
				if (style.length() > 80)
					style = style.substring(0, 80);
				JsonObject p = SetupCodec.blank(title);
				JsonObject setup = SetupCodec.setup(p);
				StringBuilder notes = new StringBuilder(
						"Source: " + source + "\nPreset: Recommended " + style + " (first choices)");
				int populated = 0;
				for (int i = 0; i < keys.length; i++)
					if (!keys[i].isEmpty())
					{
						JsonArray choices = new JsonArray();
						java.util.Set<String> names = new java.util.LinkedHashSet<>();
						boolean hasRecommendation = false;
						for (int rank = 1; rank <= 10; rank++)
						{
							String value = table.fields.get(keys[i] + rank);
							if (value == null || value.isBlank() || value.matches("(?i)none|empty|-"))
								continue;
							hasRecommendation = true;
							// The first component represents this slot; read the linked source for the full combination.
							boolean combination = value.contains("+");
							int before = names.size();
							List<Node> nested = nodes(value);
							for (Node item : nested)
								if (item.kind.equals("plink") && nested.stream()
										.noneMatch(parent -> parent != item && parent.start < item.start
												&& parent.end > item.end
												&& (parent.kind.equals("efn") || parent.kind.equals("refn"))))
								{
									String name = itemName(value.substring(item.start, item.end));
									if (!name.isEmpty() && name.length() < 150)
									{
										names.add(name);
										if (combination)
											break;
									}
								}
							if (names.size() == before && !value.contains("{{"))
							{
								for (String name : plain(value).split(combination ? "\\s*\\+\\s*" : "\\s+/\\s+"))
								{
									if (!name.isBlank() && name.length() < 150)
										names.add(name.trim());
									if (combination)
										break;
								}
							}
						}
						if (!hasRecommendation)
							continue;
						for (String name : names)
							if (choices.size() < 40)
								choices.add(name);
						JsonObject item = SetupCodec.item(0, 1);
						item.addProperty("label",
								choices.size() > 0
										? choices.get(0).getAsString()
										: "Choose " + keys[i] + " · " + style);
						item.add("choices", choices);
						if (i == 13)
							item.add("q", JsonNull.INSTANCE);
						setup.getAsJsonArray("eq").set(i, item);
						populated++;
					}
				if (populated > 0)
				{
					String detail = notes.toString();
					setup.addProperty("notes",
							detail.length() > 10000
									? detail.substring(0, 9900) + "\nSee the source page for remaining conditions."
									: detail);
					SetupCodec.rebuildLayout(p);
					result.add(p);
				}
			}
		return result;
	}

}

