public class AccountReadinessTest
{
	private static class Host extends PanelTest.FakeHost
	{
		final Map<String, String> libraries = new HashMap<>();
		BiConsumer<List<String>, String> pending;
		@Override
		public String read(String scope)
		{
			return libraries.get(scope);
		}

		@Override
		public void save(String scope, String text)
		{
			super.save(scope, text);
			libraries.put(scope, text);
		}

		@Override
		public void searchWiki(String query, BiConsumer<List<String>, String> callback)
		{
			pending = callback;
		}
