		cells[0] = 10;
		cells[8] = 20;
		cells[16] = 30;
		java.util.List<Integer> requested = new ArrayList<>();
		BufferedImage target = new BufferedImage(160, 80, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = target.createGraphics();
		BankPlaceholderOverlay.paint(g, new Rectangle(0, 10, 120, 36), 36, cells, id ->
		{
			requested.add(id);
			return sprite();
		});
		assertEquals(Collections.singletonList(20), requested);
		assertEquals(135, target.getRGB(51, 10) >>> 24);
		assertEquals(0, target.getRGB(51, 46));
		g.dispose();
	}
}

package com.loadoutstudio;
import static org.junit.Assert.*;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import org.junit.Test;
public class BrandIconTest
{
	@Test
	public void nativeSidebarIconUsesTheFullRuneLiteTabSize()
	{
		BufferedImage icon = StudioBrandIcon.navigation();
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		int minX = 16, minY = 16, maxX = -1, maxY = -1;
		for (int y = 0; y < 16; y++)
			for (int x = 0; x < 16; x++)
				if ((icon.getRGB(x, y) >>> 24) > 0)
				{
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
					maxY = Math.max(maxY, y);
				}
		assertEquals(0, minX);
		assertEquals(0, minY);
		assertEquals(15, maxX);
		assertEquals(15, maxY);
	}

	@Test
	public void rendersDistinctiveIconAtSidebarSizes() throws Exception
	{
		BufferedImage icon = StudioBrandIcon.create();
		assertEquals(32, icon.getWidth());
		assertEquals(32, icon.getHeight());
		BufferedImage preview = new BufferedImage(180, 70, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = preview.createGraphics();
		g.setColor(new Color(37, 37, 37));
		g.fillRect(0, 0, 180, 70);
