import org.junit.Test;
public class ExportOptionsTest
{
	private final SetupCodec codec = new SetupCodec(RuneLiteAPI.GSON);
	private static JsonObject setup()
	{
		JsonObject p = SetupCodec.blank("Boss – test");
		JsonObject item = SetupCodec.item(560, 15000);
		item.addProperty("label", "Death rune");
		JsonArray choices = new JsonArray();
		choices.add("Death rune");
		item.add("choices", choices);
		SetupCodec.setup(p).getAsJsonArray("inv").set(3, item);
		SetupCodec.setup(p).addProperty("notes", "Unicode café 🎣\nKeep this note.");
		SetupCodec.rebuildLayout(p);
		return p;
	}

	private static void rejected(Runnable r)
	{
		try
		{
			r.run();
			fail("Invalid export text accepted");
		}
		catch (IllegalArgumentException expected)
		{
			assertNotNull(expected.getMessage());
		}
	}

	private static String gzip(byte[] data) throws Exception
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (GZIPOutputStream g = new GZIPOutputStream(out))
		{
			g.write(data);
		}
		return SetupExportText.PREFIX + Base64.getEncoder().encodeToString(out.toByteArray());
	}

	@Test
	public void prettyInventoryChangesOnlyWhitespaceAndKeepsPlainPluginJson()
	{
		JsonObject p = setup();
		String normal = codec.inventory(p), pretty = codec.inventory(p, true);
		assertFalse(normal.contains("\n"));
		assertTrue(pretty.contains("\n"));
		assertEquals(codec.parse(normal), codec.parse(pretty));
		assertFalse(codec.parse(pretty).getAsJsonObject().has("loadoutStudio"));
		assertEquals(1, codec.importText(pretty).size());
		assertEquals(p, setup());
	}

	@Test
	public void compressedNativeRoundTripRetainsLabelsChoicesUnicodeAndLayout()
	{
		JsonObject p = setup();
		String compressed = codec.studio(p, true, true);
		assertTrue(compressed.startsWith(SetupExportText.PREFIX));
		assertFalse(compressed.contains("\n"));
		JsonObject restored = codec.importText(compressed).get(0);
		assertEquals(1, restored.remove("loadoutStudio").getAsInt());
		assertEquals(p, restored);
		assertEquals(codec.studio(p, false, true), compressed);
	}

	@Test
	public void nativePrettyMarkerDoesNotLeakIntoInventoryExports()
	{
		String pretty = codec.studio(setup(), true, false);
		assertTrue(pretty.contains("\n"));
		JsonObject p = codec.importText(pretty).get(0);
		assertEquals(1, p.get("loadoutStudio").getAsInt());
		JsonObject external = codec.parse(codec.inventory(p, true)).getAsJsonObject();
		assertFalse(external.has("loadoutStudio"));
		assertFalse(SetupCodec.setup(external).getAsJsonArray("inv").get(3).getAsJsonObject().has("choices"));
	}

	@Test
	public void brokenBase64GzipTruncationAndVersionsAreRejected()
	{
		rejected(() -> codec.importText("loadoutstudio:gz2:abc"));
		rejected(() -> codec.importText(SetupExportText.PREFIX + "%%%"));
		rejected(() -> codec.importText(SetupExportText.PREFIX + "e30="));
		String text = codec.studio(setup(), false, true);
		rejected(() -> codec.importText(text.substring(0, text.length() - 12)));
		JsonObject future = setup();
		future.addProperty("loadoutStudio", 2);
		rejected(() -> codec.importText(RuneLiteAPI.GSON.toJson(future)));
		future.addProperty("loadoutStudio", "1");
		rejected(() -> codec.importText(RuneLiteAPI.GSON.toJson(future)));
	}

	@Test
	public void compressedInputStillPassesExistingSchemaAndDepthChecks()
	{
		JsonObject bad = setup();
		SetupCodec.setup(bad).addProperty("fb", "true");
		rejected(() -> codec.importText(SetupExportText.compress(RuneLiteAPI.GSON.toJson(bad))));
		rejected(() -> codec.importText(SetupExportText.compress("[".repeat(49) + "]".repeat(49))));
	}

	@Test
	public void expandedLimitAndInvalidUtf8AreRejected() throws Exception
	{
		String bomb = gzip(new byte[SetupCodec.MAX_TEXT + 1]);
		rejected(() -> codec.importText(bomb));
		String invalid = gzip(new byte[]{(byte) 0xC3, 0x28});
		rejected(() -> codec.importText(invalid));
		rejected(() -> SetupExportText.unpack(" ".repeat(SetupCodec.MAX_TEXT + 1)));
	}
