	private static LoadoutSlotButton slot(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof LoadoutSlotButton
					&& "inv".equals(((LoadoutSlotButton) c).getClientProperty("slotContainer"))
					&& Integer.valueOf(0).equals(((LoadoutSlotButton) c).getClientProperty("slotIndex")))
				return (LoadoutSlotButton) c;
			if (c instanceof Container)
			{
				LoadoutSlotButton found = slot((Container) c);
				if (found != null)
					return found;
			}
		}
		return null;
	}

