	@Test
	public void setupNameAcceptsDropsIntoItsSectionAndStillProvidesADragSource() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			OwnedGearPanelTest.Host host = new OwnedGearPanelTest.Host();
			SetupLibrary library = new SetupLibrary();
			SetupLibrary.Section group = new SetupLibrary.Section("Bosses");
			library.sections.add(group);
			SetupLibrary.Entry source = new SetupLibrary.Entry(SetupCodec.blank("Source")),
					target = new SetupLibrary.Entry(SetupCodec.blank("Target"));
			target.section = group.id;
			target.favorite = true;
			library.setups.add(source);
			library.setups.add(target);
			host.saved = library.serialize(RuneLiteAPI.GSON);
			StudioPanel panel = new StudioPanel(host, RuneLiteAPI.GSON);
			panel.open(source);
			String payload = panel.libraryDragPayload(source.id);
			JComponent name = (JComponent) OwnedGearPanelTest.find(panel, "libraryOpen:" + target.id);
			TransferHandler handler = name.getTransferHandler();
			assertEquals(TransferHandler.MOVE, handler.getSourceActions(name));
			TransferHandler.TransferSupport drop = new TransferHandler.TransferSupport(name,
					new StringSelection(payload));
			assertTrue(handler.canImport(drop));
			assertTrue(handler.importData(drop));
			SetupLibrary saved = SetupLibrary.read(host.saved, RuneLiteAPI.GSON);
			assertEquals(2, saved.setups.size());
			assertEquals(group.id, saved.find(source.id).section);
			assertEquals(group.id, saved.find(target.id).section);
			assertTrue(saved.find(target.id).favorite);
			JComponent moved = (JComponent) OwnedGearPanelTest.find(panel, "libraryOpen:" + source.id);
			assertEquals(TransferHandler.MOVE, moved.getTransferHandler().getSourceActions(moved));
			assertFalse(moved.getTransferHandler()
					.canImport(new TransferHandler.TransferSupport(moved, new StringSelection("not-a-setup"))));
			panel.dispose();
		});
	}

	@Test
	public void setupDropsIntoEmptySectionsAndUnfiledPersistWithoutDuplication() throws Exception
	{
