		{
			OwnedGearPanelTest.Host host = new OwnedGearPanelTest.Host();
			SetupLibrary library = new SetupLibrary();
			SetupLibrary.Section group = new SetupLibrary.Section("Raids");
			library.sections.add(group);
			SetupLibrary.Entry entry = new SetupLibrary.Entry(SetupCodec.blank("Move me"));
			library.setups.add(entry);
			host.saved = library.serialize(RuneLiteAPI.GSON);
			StudioPanel panel = new StudioPanel(host, RuneLiteAPI.GSON);
			panel.open(entry);
			String payload = panel.libraryDragPayload(entry.id);
			JComponent header = (JComponent) OwnedGearPanelTest.find(panel, "libraryGroup:" + group.id);
			TransferHandler.TransferSupport drop = new TransferHandler.TransferSupport(header,
					new StringSelection(payload));
			assertTrue(header.getTransferHandler().canImport(drop));
			assertTrue(header.getTransferHandler().importData(drop));
			SetupLibrary result = SetupLibrary.read(host.saved, RuneLiteAPI.GSON);
			assertEquals(1, result.setups.size());
			assertEquals(group.id, result.find(entry.id).section);
			assertTrue(panel.moveLibraryDrop(payload, null));
			assertNull(SetupLibrary.read(host.saved, RuneLiteAPI.GSON).find(entry.id).section);
			assertFalse(panel.moveLibraryDrop(payload, "missing-section"));
			host.scope = "other-character";
			assertFalse(panel.moveLibraryDrop(payload, group.id));
			panel.dispose();
		});
	}
