public class GroupedAlternativesTest
{
	private static JsonObject food()
	{
		JsonObject p = SetupCodec.blank("Food swaps");
		for (int i = 0; i < 20; i++)
		{
			JsonObject item = SetupCodec.item(ItemID.MANTARAY, 1);
			item.addProperty("label", "Manta ray");
			item.addProperty("f", i % 2 == 0);
			SetupCodec.setup(p).getAsJsonArray("inv").set(i, item);
		}
		SetupCodec.rebuildLayout(p);
		return p;
	}

	private static OwnedGear gear(int sharks)
	{
		Map<Integer, Integer> counts = new LinkedHashMap<>();
		counts.put(ItemID.SHARK, sharks);
		Map<Integer, StudioPanel.ItemInfo> items = new LinkedHashMap<>();
		items.put(ItemID.MANTARAY, OwnedGearTest.item(ItemID.MANTARAY, "Manta ray", -1));
		items.put(ItemID.SHARK, OwnedGearTest.item(ItemID.SHARK, "Shark", -1));
		return new OwnedGear(counts, items, 123, true);
	}

	private static void assertFood(StudioPanel panel, OwnedGearPanelTest.Host host, int id)
	{
		OwnedGearPanelTest.click(panel, "Save");
		JsonObject saved = SetupLibrary.read(host.saved, RuneLiteAPI.GSON).setups.get(0).portable;
		for (int i = 0; i < 20; i++)
		{
			JsonObject item = SetupCodec.setup(saved).getAsJsonArray("inv").get(i).getAsJsonObject();
			assertEquals(id, SetupCodec.id(item));
			assertEquals(1, SetupCodec.quantity(item));
			assertEquals(i % 2 == 0, item.get("f").getAsBoolean());
		}
	}

