			assertFood(panel, host, ItemID.MANTARAY);
			panel.refreshAlternatives();
			((JComboBox<?>) OwnedGearPanelTest.find(panel, "ownedChoice:inv:0")).setSelectedIndex(1);
			OwnedGearPanelTest.click(panel, "Use selected alternatives");
