package com.loadoutstudio;
import static org.junit.Assert.*;

import com.google.gson.*;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;
public class ImportSchemaTest
{
	private void rejected(Runnable action)
	{
		try
		{
			action.run();
			fail("Invalid input accepted");
		}
		catch (IllegalArgumentException expected)
		{
		}
	}

	@Test
	public void allConsumedSetupFlagsRejectNonBooleans()
	{
		for (String flag : new String[]{"fb", "hd", "uh", "fv"})
			for (String value : new String[]{"[]", "{}", "0", "\"false\"", "null"})
			{
				JsonObject p = SetupCodec.blank("Bad flag");
				SetupCodec.setup(p).add(flag, new SetupCodec(RuneLiteAPI.GSON).parse(value));
				rejected(() -> new SetupCodec(RuneLiteAPI.GSON)
						.importText(RuneLiteAPI.GSON.newBuilder().serializeNulls().create().toJson(p)));
			}
	}

	@Test
	public void itemFlagsAndStackRuleAreStrict()
	{
		for (String value : new String[]{"[]", "{}", "0", "\"false\"", "null"})
		{
			JsonObject p = SetupCodec.blank("Bad item");
			JsonObject item = SetupCodec.item(560, 1);
			item.add("f", new SetupCodec(RuneLiteAPI.GSON).parse(value));
			SetupCodec.setup(p).getAsJsonArray("inv").set(0, item);
			rejected(() -> SetupCodec.validate(p, false));
		}
		JsonObject p = SetupCodec.blank("Bad rule");
		JsonObject item = SetupCodec.item(560, 1);
		item.add("sc", JsonNull.INSTANCE);
		SetupCodec.setup(p).getAsJsonArray("inv").set(0, item);
		rejected(() -> SetupCodec.validate(p, false));
	}

	@Test
	public void optionalMissingFlagsAndValidFalseValuesRemainCompatible()
	{
		JsonObject p = SetupCodec.blank("Compatible");
		for (String flag : new String[]{"fb", "hd", "uh", "fv"})
			SetupCodec.setup(p).addProperty(flag, false);
		assertEquals(1, new SetupCodec(RuneLiteAPI.GSON)
				.importText(RuneLiteAPI.GSON.newBuilder().serializeNulls().create().toJson(p)).size());
		for (String flag : new String[]{"fb", "hd", "uh", "fv"})
			SetupCodec.setup(p).remove(flag);
		assertEquals(1, new SetupCodec(RuneLiteAPI.GSON)
				.importText(RuneLiteAPI.GSON.newBuilder().serializeNulls().create().toJson(p)).size());
	}

	@Test
	public void storedMetadataAndRecoveryRejectCoercedBooleans()
	{
		SetupLibrary library = new SetupLibrary();
		library.setups.add(new SetupLibrary.Entry(SetupCodec.blank("Stored")));
		for (String flag : new String[]{"favorite", "archived", "zigzagBottomToTop"})
		{
			JsonObject raw = RuneLiteAPI.GSON.toJsonTree(library).getAsJsonObject();
			raw.getAsJsonArray("setups").get(0).getAsJsonObject().addProperty(flag, "true");
			rejected(() -> SetupLibrary.read(RuneLiteAPI.GSON.toJson(raw), RuneLiteAPI.GSON));
		}
		for (String flag : new String[]{"favorite", "bottom", "ignoreAmmo"})
		{
			String encoded = DraftRecovery.encode(library.setups.get(0).portable, null, null, false,
					BankLayouts.Mode.PRESET, false, false, RuneLiteAPI.GSON);
			JsonObject raw = new SetupCodec(RuneLiteAPI.GSON).parse(encoded).getAsJsonObject();
			raw.add(flag, new JsonArray());
			rejected(() -> DraftRecovery.decode(RuneLiteAPI.GSON.toJson(raw), RuneLiteAPI.GSON));
		}
	}

	@Test
	public void malformedDraftCannotReplaceCurrentBuilder() throws Exception
	{
		javax.swing.SwingUtilities.invokeAndWait(() ->
		{
			PanelTest.FakeHost host = new PanelTest.FakeHost();
			StudioPanel panel = new StudioPanel(host, RuneLiteAPI.GSON);
			JsonObject original = SetupCodec.blank("Keep this");
			panel.open(new SetupLibrary.Entry(original));
			JsonObject broken = SetupCodec.blank("Invalid");
			SetupCodec.setup(broken).add("fb", new JsonArray());
			rejected(() -> panel.newDraft(broken));
			assertEquals("Keep this", SetupCodec.name(host.selectedBankSetup));
			panel.dispose();
		});
	}

	@Test
	public void notesMustBeText()
	{
		JsonObject p = SetupCodec.blank("Notes");
		SetupCodec.setup(p).addProperty("notes", 12);
		rejected(() -> SetupCodec.validate(p, false));
	}
}

