				{ItemID.NZONE_BERZERKER_RING, ItemID.SW_BERZERKER_RING, ItemID.PVPA_BERZERKER_RING}};
		for (int[] family : families)
		{
			ItemCatalogue catalogue = new ItemCatalogue();
			for (int id : family)
			{
				assertEquals(id, ItemCatalogue.selectionId(id));
				assertFalse(AutomaticItemExclusions.avoidDefault(id));
				catalogue.add(id, "Imbued variant", false, -1, -1, 0, false, true);
			}
			assertNotNull(catalogue.firstExact("Imbued variant"));
		}
	}

	@Test
	public void savedSourceChoiceKeepsTheUsersLegitimateSalveVariant() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			PanelTest.FakeHost host = new PanelTest.FakeHost()
			{
				@Override
				public StudioPanel.ItemInfo defaultItem(String name)
				{
					return new StudioPanel.ItemInfo(ItemID.NZONE_SALVE_AMULET_E, name, false, 2, null);
				}
			};
			JsonObject source = SetupCodec.blank("Keep my imbue");
			JsonObject item = SetupCodec.item(ItemID.SW_SALVE_AMULET_E, 1);
			item.addProperty("label", "Salve amulet(ei)");
			JsonArray choices = new JsonArray();
			choices.add("Salve amulet(ei)");
			item.add("choices", choices);
			SetupCodec.setup(source).getAsJsonArray("eq").set(2, item);
			SetupCodec.rebuildLayout(source);
			StudioPanel panel = new StudioPanel(host, RuneLiteAPI.GSON);
			panel.open(new SetupLibrary.Entry(source));
			assertEquals(ItemID.SW_SALVE_AMULET_E,
					SetupCodec.id(SetupCodec.setup(host.selectedBankSetup).getAsJsonArray("eq").get(2)));
			assertNull(host.saved);
			panel.dispose();
		});
	}

	private static JButton neck(Container root)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof JButton && "eq".equals(((JButton) child).getClientProperty("slotContainer"))
					&& Integer.valueOf(2).equals(((JButton) child).getClientProperty("slotIndex")))
				return (JButton) child;
			if (child instanceof Container)
			{
				JButton found = neck((Container) child);
				if (found != null)
					return found;
			}
		}
		return null;
	}

	@Test
	public void allThreeSalveChoicesCanBeInsertedSavedAndExportedFromTheSidebar() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			class Host extends PanelTest.FakeHost
			{
				Consumer<Integer> selected;
				@Override
				public void chooseItem(Consumer<Integer> chosen, Consumer<String> error)
				{
					selected = chosen;
				}

				@Override
				public void describe(int id, Consumer<StudioPanel.ItemInfo> done)
				{
					done.accept(new StudioPanel.ItemInfo(id, "Salve amulet(ei)", false, 2, null));
				}
			}
			for (int id : SALVES)
			{
				Host host = new Host();
				StudioPanel panel = new StudioPanel(host, RuneLiteAPI.GSON);
				panel.newDraft(SetupCodec.blank("Salve variant"));
				neck(panel).doClick();
				assertNotNull(host.selected);
				host.selected.accept(ItemCatalogue.selectionId(id));
				assertEquals(id, SetupCodec.id(SetupCodec.setup(host.selectedBankSetup).getAsJsonArray("eq").get(2)));
				OwnedGearPanelTest.click(panel, "Save");
				SetupLibrary saved = SetupLibrary.read(host.saved, RuneLiteAPI.GSON);
				SetupCodec codec = new SetupCodec(RuneLiteAPI.GSON);
				JsonObject copy = codec.importText(codec.inventory(saved.setups.get(0).portable)).get(0);
				assertEquals(id, SetupCodec.id(SetupCodec.setup(copy).getAsJsonArray("eq").get(2)));
				panel.dispose();
			}
		});
	}
}

