	public void duplicatesReuseConfiguredNativeSlotsAndRestoreTheHiddenBankItems()
	{
		NativeWidget original = new NativeWidget(0, true, 391);
		original.actions = StudioPotionStorage.actions(0, 50);
		original.name = "Manta ray";
		original.qty = 1499;
		NativeWidget spare = new NativeWidget(1, true, 995);
		Widget[] children = {original, spare};
		IndependentBankView view = new IndependentBankView(null, null, null, id -> id);
		Widget copy = view.proxy(children, new int[]{391, -1}, original, 6, 391, 1499, "Manta ray", original.actions);
		assertSame(spare, copy);
		assertEquals(1, copy.getIndex());
		assertEquals(391, copy.getItemId());
		assertTrue(spare.hasMenuAction("Withdraw-1"));
		assertTrue(spare.hasMenuAction("Withdraw-5"));
		assertEquals(0, spare.getClickMask());
		assertEquals(1499, copy.getItemQuantity());
		assertNull(view.proxy(children, new int[]{391, -1}, original, 7, 391, 1499, "Manta ray", original.actions));
		view.removeCopies();
		assertEquals(995, spare.id);
		assertEquals(15, spare.qty);
		assertEquals("Original", spare.name);
		assertEquals("Original operation", spare.actions[0]);
		assertTrue(spare.hidden);
		assertEquals(400, spare.x);
		assertEquals(500, spare.y);
		assertEquals(391, original.id);
		assertEquals(1499, original.qty);
	}

