	private static JButton slot(Container c, String key, int index)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof JButton && key.equals(((JButton) child).getClientProperty("slotContainer"))
					&& Integer.valueOf(index).equals(((JButton) child).getClientProperty("slotIndex")))
				return (JButton) child;
			if (child instanceof Container)
			{
				JButton result = slot((Container) child, key, index);
				if (result != null)
					return result;
			}
		}
		return null;
	}

	private static Component find(Container c, String name)
	{
		for (Component child : c.getComponents())
		{
			if (name.equals(child.getName()))
				return child;
			if (child instanceof Container)
			{
				Component result = find((Container) child, name);
				if (result != null)
					return result;
			}
		}
		return null;
	}

	private static JMenuItem menu(JButton slot, String text)
	{
		for (Component c : slot.getComponentPopupMenu().getComponents())
			if (c instanceof JMenuItem && text.equals(((JMenuItem) c).getText()))
				return (JMenuItem) c;
		throw new AssertionError(text);
	}

	private static void layout(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
			if (child instanceof Container)
				layout((Container) child);
	}

