	static Component find(Container root, String name)
	{
		for (Component child : root.getComponents())
		{
			if (name.equals(child.getName())
					|| child instanceof AbstractButton && name.equals(((AbstractButton) child).getText())
					|| child instanceof JLabel && name.equals(((JLabel) child).getText()))
				return child;
			if (child instanceof Container)
			{
				Component result = find((Container) child, name);
				if (result != null)
					return result;
			}
		}
		return null;
	}

	static void click(Container root, String name)
	{
		if (name.equals("Check my Bank"))
		{
			((StudioPanel) root).refreshAlternatives();
			return;
		}
		AbstractButton b = (AbstractButton) find(root, name);
		assertNotNull(name, b);
		b.doClick();
	}

	static void layout(Container root)
	{
		root.doLayout();
		for (Component c : root.getComponents())
			if (c instanceof Container)
				layout((Container) c);
	}

