				+ "{{Recommended equipment|style=Ranged|body1={{plink|Masori body (f)}}|body2={{plink|Crystal body}}{{efn|If using crystal armour}}|body3={{plink|Karil's leathertop}}|body4={{plink|Black d'hide body}}|weapon1={{plink|Toxic blowpipe}} > {{plink|Twisted bow}}}}\n"
				+ "{{Inventory|Shark}}\n</tabber>";
	}

	private static List<JsonObject> presets()
	{
		return new WikiParser().parse(source(), "Slayer task/Aquanites",
				"https://oldschool.runescape.wiki/w/Slayer_task/Aquanites");
	}

	private static JsonObject body(JsonObject p)
	{
		return SetupCodec.setup(p).getAsJsonArray("eq").get(4).getAsJsonObject();
	}

	private static List<String> names(JsonObject item)
	{
		List<String> n = new ArrayList<>();
		for (JsonElement e : item.getAsJsonArray("choices"))
			n.add(e.getAsString());
		return n;
	}

	@Test
	public void concreteSetupsRetainAdjacentRankedTablesAndInventory()
	{
		List<JsonObject> p = presets();
		assertEquals(2, p.size());
		assertEquals("Melee Slash/Stab", WikiParser.variant(p.get(0)));
		assertEquals(Arrays.asList("Oathplate chest", "Torva platebody", "Bandos chestplate", "Blood Moon chestplate",
				"Fighter torso", "Sunfire fanatic cuirass", "Proselyte hauberk"), names(body(p.get(0))));
		assertEquals("Dragon claws",
				SetupCodec.setup(p.get(0)).getAsJsonArray("inv").get(0).getAsJsonObject().get("label").getAsString());
