public class RecoveryAndImportPanelTest
{
	static class Host extends PanelTest.FakeHost
	{
		String profile = "one";
		Map<String, String> recovery = new HashMap<>();
		int imports;
		public String recoveryOwner()
		{
			return profile + ":" + scope;
		}

		public String readRecovery(String scope, String owner)
		{
			return recovery.get(owner);
		}

		public void saveRecovery(String scope, String owner, String text)
		{
			assertEquals(recoveryOwner(), owner);
			if (text == null)
				recovery.remove(owner);
			else
				recovery.put(owner, text);
		}

		public void existingSetups(java.util.function.Consumer<ExistingSetupReader.Result> success,
				java.util.function.Consumer<String> error)
		{
			imports++;
			success.accept(new ExistingSetupReader.Result());
		}
	}
	static Component find(Container c, String name)
	{
		for (Component child : c.getComponents())
		{
			if (name.equals(child.getName()) || child instanceof JButton && name.equals(((JButton) child).getText()))
				return child;
			if (child instanceof Container)
			{
				Component result = find((Container) child, name);
				if (result != null)
					return result;
			}
		}
		return null;
	}

