		OwnedGearPanelTest.layout(panel);
		OwnedGearPanelTest.layout(panel);
		try
		{
			java.io.File dir = new java.io.File("build/previews/readiness");
			dir.mkdirs();
			java.awt.image.BufferedImage image = new java.awt.image.BufferedImage(220, 900,
					java.awt.image.BufferedImage.TYPE_INT_RGB);
			java.awt.Graphics2D g = image.createGraphics();
			panel.printAll(g);
			g.dispose();
			javax.imageio.ImageIO.write(image, "png", new java.io.File(dir, name + ".png"));
		}
		catch (java.io.IOException ex)
		{
			throw new AssertionError(ex);
		}
	}

	private static JButton findSlot(java.awt.Container root)
	{
		for (java.awt.Component c : root.getComponents())
		{
			if (c instanceof JButton && "inv".equals(((JButton) c).getClientProperty("slotContainer"))
					&& Integer.valueOf(0).equals(((JButton) c).getClientProperty("slotIndex")))
				return (JButton) c;
			if (c instanceof java.awt.Container)
			{
				JButton found = findSlot((java.awt.Container) c);
				if (found != null)
					return found;
			}
		}
		return null;
	}
}

