	static JButton slot(Container c)
	{
		for (Component x : c.getComponents())
		{
			if (x instanceof JButton && "inv".equals(((JButton) x).getClientProperty("slotContainer"))
					&& Integer.valueOf(0).equals(((JButton) x).getClientProperty("slotIndex")))
				return (JButton) x;
			if (x instanceof Container)
			{
