	@Test
	public void creationDefaultsRespectBothBooleanValuesEveryAmountRuleAndCaptureScope()
	{
		for (boolean on : new boolean[]{false, true})
			for (LoadoutStudioConfig.StackRule rule : LoadoutStudioConfig.StackRule.values())
			{
				Settings s = new Settings();
				s.on = on;
				s.rule = rule;
				JsonObject input = source(), before = input.deepCopy();
				JsonObject created = SetupCodec.setup(LoadoutDefaults.created(input, s)),
						captured = SetupCodec.setup(LoadoutDefaults.captured(input, s));
				for (JsonObject setup : Arrays.asList(created, captured))
				{
					for (String flag : new String[]{"hd", "fb", "uh"})
						assertEquals(on, setup.get(flag).getAsBoolean());
					assertEquals("#FF00FFFF", setup.get("hc").getAsString());
					JsonObject item = setup.getAsJsonArray("inv").get(0).getAsJsonObject();
					assertEquals(on, item.get("f").getAsBoolean());
					assertEquals(rule.code, item.get("sc").getAsString());
				}
				assertTrue(created.has("ao"));
				assertEquals(on, captured.has("ao"));
				assertEquals(before, input);
			}
	}

