		for (Component child : root.getComponents())
		{
			if (name.equals(child.getName()) || child instanceof JButton && name.equals(((JButton) child).getText())
					|| child instanceof JCheckBox && name.equals(((JCheckBox) child).getText()))
				return child;
			if (child instanceof Container)
			{
				Component found = find((Container) child, name);
				if (found != null)
					return found;
			}
		}
		return null;
	}

	private static void layout(Container root)
	{
		root.doLayout();
		for (Component c : root.getComponents())
			if (c instanceof Container)
				layout((Container) c);
	}

