public class SlotTransferTest
{
	private static final class Host extends PanelTest.FakeHost
	{
		final Map<Integer, StudioPanel.ItemInfo> items = new HashMap<>();
		Host()
		{
			item(13441, "Anglerfish", false, -1);
			item(22978, "Dragon hunter lance", false, 3);
			item(560, "Death rune", true, -1);
			item(561, "Nature rune", true, -1);
			item(892, "Rune arrow", true, 13);
			item(385, "Shark", false, -1);
		}

		void item(int id, String name, boolean stackable, int slot)
		{
			items.put(id, new StudioPanel.ItemInfo(id, name, stackable, slot, null));
		}

		@Override
		public void describe(int id, java.util.function.Consumer<StudioPanel.ItemInfo> callback)
		{
			callback.accept(items.get(id));
		}

		@Override
		public java.util.List<StudioPanel.ItemInfo> search(String query)
		{
			java.util.List<StudioPanel.ItemInfo> result = new ArrayList<>();
			for (StudioPanel.ItemInfo i : items.values())
				if (i.name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))
					result.add(i);
			return result;
		}
	}
	private static Component find(Container root, String name)
	{
		for (Component c : root.getComponents())
		{
			if (name.equals(c.getName()) || c instanceof JButton && name.equals(((JButton) c).getText()))
				return c;
			if (c instanceof Container)
			{
				Component found = find((Container) c, name);
				if (found != null)
					return found;
			}
		}
		return null;
	}

	private static JButton slot(Container root, String key, int index)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JButton && key.equals(((JButton) c).getClientProperty("slotContainer"))
					&& Integer.valueOf(index).equals(((JButton) c).getClientProperty("slotIndex")))
				return (JButton) c;
			if (c instanceof Container)
			{
				JButton found = slot((Container) c, key, index);
				if (found != null)
					return found;
			}
		}
		return null;
	}

	private static boolean drop(StudioPanel panel, String payload, String key, int index)
	{
		JButton target = slot(panel, key, index);
		return target.getTransferHandler()
				.importData(new TransferHandler.TransferSupport(target, new StringSelection(payload)));
	}

