	@Test
	public void potionStorageAliasesUseTheSelectedDoseWithoutMultiplyingStock()
	{
		StudioPotionStorage cache = new StudioPotionStorage(null, null);
		StudioPotionStorage.Potion potion = new StudioPotionStorage.Potion(7, new int[]{101, 102, 103, 104}, 23, 4);
		cache.install(Collections.singletonList(potion), 20);
		for (int id : new int[]{101, 102, 103, 104})
			assertSame(potion, cache.forItem(id));
		assertEquals(104, potion.itemId());
		assertEquals(5, potion.count());
		assertEquals(35, potion.withdrawChild());
		assertEquals(36, potion.dosesChild());
		assertEquals(Collections.singletonMap(104, 5), cache.counts());
		assertTrue(cache.current(potion));
		cache.invalidate();
		assertFalse(cache.current(potion));
		assertTrue(cache.counts().isEmpty());
		assertNull(cache.forItem(104));
	}

