				empty = new StudioPotionStorage.Potion(1, new int[]{201, 202, 203, 204}, 0, 4);
		cache.install(Arrays.asList(partial, empty), 2);
		assertEquals(0, partial.count());
		assertTrue(cache.counts().isEmpty());
		assertNotNull(cache.forItem(101));
		assertNull(cache.forItem(201));
		String[] actions = StudioPotionStorage.actions(4, 50, false);
		for (int i = 0; i < 10; i++)
			assertNull(actions[i]);
		assertEquals("Doses", actions[10]);
	}

