public class StudioDiagnosticsTest
{
	@Test
	public void typedOutcomesExcludeMessagesAndSeparateBadInputFromBugs()
	{
		StudioDiagnostics d = new StudioDiagnostics();
		d.failure(StudioDiagnostics.Operation.IMPORT, new IllegalArgumentException("PRIVATE_INPUT_MARKER"), 0);
		d.failure(StudioDiagnostics.Operation.SAVE, new IllegalStateException("PRIVATE_STATE_MARKER"), 0);
		d.failure(StudioDiagnostics.Operation.WIKI_HTTP, new java.io.IOException("PRIVATE_URL_MARKER"), 0);
		d.failure(StudioDiagnostics.Operation.UI_ACTION, new NullPointerException("PRIVATE_ERROR_MARKER"), 0);
		String report = d.report("not/a/version");
		for (String secret : new String[]{"PRIVATE_INPUT_MARKER", "PRIVATE_STATE_MARKER", "PRIVATE_URL_MARKER",
				"PRIVATE_ERROR_MARKER", "not/a/version"})
			assertFalse(report.contains(secret));
		assertTrue(report.contains("VALIDATION=1"));
		assertTrue(report.contains("EXPECTED_STATE=1"));
		assertTrue(report.contains("IO_FAILURE=1"));
		assertTrue(report.contains("UNEXPECTED=1"));
		assertTrue(report.contains("RuneLite: unknown"));
		assertTrue(report.contains("StudioDiagnosticsTest.typedOutcomes"));
	}

	@Test
	public void recentOutcomesAreBoundedAndDisableAndResetClearTheSession()
	{
		StudioDiagnostics d = new StudioDiagnostics();
		for (int i = 0; i < 100; i++)
			d.completed(StudioDiagnostics.Operation.IMPORT, StudioDiagnostics.Outcome.VALIDATION, 0);
		String report = d.report("1.13.3");
		String recent = report.substring(report.indexOf("Recent technical"));
		assertEquals(25, recent.lines().count());
		d.enabled(false);
		d.completed(StudioDiagnostics.Operation.SAVE, StudioDiagnostics.Outcome.SUCCESS, 0);
		assertTrue(d.report("1.13.3").contains("No samples."));
		assertTrue(d.report("1.13.3").contains("Recording: disabled"));
		d.enabled(true);
		d.completed(StudioDiagnostics.Operation.SAVE, StudioDiagnostics.Outcome.SUCCESS, 0);
		assertTrue(d.report("1.13.3").contains("SAVE: calls=1"));
		d.clear();
		assertTrue(d.report("1.13.3").contains("No samples."));
	}
