	@Test
	public void wikiCacheAndHttpCountersDoNotAddTrafficOrRetainThePageTitle() throws Exception
	{
		java.util.concurrent.atomic.AtomicInteger requests = new java.util.concurrent.atomic.AtomicInteger();
		okhttp3.OkHttpClient http = new okhttp3.OkHttpClient.Builder().addInterceptor(chain ->
		{
			requests.incrementAndGet();
			return new okhttp3.Response.Builder().request(chain.request()).protocol(okhttp3.Protocol.HTTP_1_1).code(200)
					.message("OK").body(okhttp3.ResponseBody.create(okhttp3.MediaType.parse("application/json"),
							PersistentWikiTest.BODY))
					.build();
		}).build();
		WikiClient wiki = new WikiClient(http, RuneLiteAPI.GSON, 0, new PersistentWikiTest.Store());
		StudioDiagnostics d = new StudioDiagnostics();
		wiki.diagnostics(d);
		try
		{
			assertEquals(0, requests.get());
			PersistentWikiTest.page(wiki, false);
			PersistentWikiTest.page(wiki, false);
			assertEquals(1, requests.get());
			String report = d.report("1.13.3");
			assertTrue(report.contains("WIKI_HTTP: calls=1"));
			assertTrue(report.contains("WIKI_CACHE_HIT: calls=1"));
			assertFalse(report.contains("Vorkath"));
			assertFalse(report.contains("https://oldschool"));
		}
		finally
		{
			wiki.close();
			http.dispatcher().executorService().shutdownNow();
			http.connectionPool().evictAll();
		}
	}

	@Test
	public void concurrentRecordingDoesNotLoseCalls() throws Exception
	{
		StudioDiagnostics d = new StudioDiagnostics();
		ExecutorService pool = Executors.newFixedThreadPool(4);
		try
		{
			List<CompletableFuture<Void>> jobs = new ArrayList<>();
			for (int i = 0; i < 1000; i++)
				jobs.add(CompletableFuture.runAsync(() -> d.completed(StudioDiagnostics.Operation.WIKI_CACHE_HIT,
						StudioDiagnostics.Outcome.SUCCESS, 0), pool));
			CompletableFuture.allOf(jobs.toArray(new CompletableFuture[0])).get(10, TimeUnit.SECONDS);
			assertTrue(d.report("1.13.3").contains("WIKI_CACHE_HIT: calls=1000"));
		}
		finally
		{
			pool.shutdownNow();
		}
	}
}

