			SetupCodec.setup(source).getAsJsonArray("inv").set(4, fixed);
			StudioPanel panel = new StudioPanel(host, RuneLiteAPI.GSON);
			panel.newDraft(source);
			JsonObject setup = SetupCodec.setup(host.selectedBankSetup);
			assertEquals(391, SetupCodec.id(setup.getAsJsonArray("inv").get(0)));
			assertTrue(setup.getAsJsonArray("inv").get(1).isJsonNull());
