	{
		for (Component child : root.getComponents())
		{
			if (name.equals(child.getName()) || child instanceof JButton && name.equals(((JButton) child).getText()))
				return child;
			if (child instanceof Container)
			{
				Component found = find((Container) child, name);
				if (found != null)
					return found;
			}
		}
		return null;
	}

